import { prisma } from "@/lib/prisma";
import { formatCurrency } from "@/lib/format";
import Link from "next/link";
import { FulfillmentStatus, PaymentStatus } from "@prisma/client";
import { safeQuery } from "@/lib/safeQuery";

async function getOrders(opts: {
  fulfillment?: string;
  payment?: string;
  emailStatus?: string;
  search?: string;
  page: number;
  limit: number;
}) {
  const where: any = {};
  const and: any[] = [];

  if (opts.fulfillment && opts.fulfillment !== "alle") {
    and.push({ fulfillmentStatus: opts.fulfillment as FulfillmentStatus });
  }
  if (opts.payment && opts.payment !== "alle") {
    and.push({ paymentStatus: opts.payment as PaymentStatus });
  }
  if (opts.emailStatus === "FAILED") {
    and.push({ customerEmailStatus: "FAILED" });
  }
  if (opts.search?.trim()) {
    const q = opts.search.trim();
    and.push({
      OR: [
        { orderNumber: { contains: q, mode: "insensitive" } },
        { customerEmail: { contains: q, mode: "insensitive" } },
        { customer: { name: { contains: q, mode: "insensitive" } } },
        { customer: { email: { contains: q, mode: "insensitive" } } },
      ],
    });
  }
  if (and.length) where.AND = and;

  const skip = (opts.page - 1) * opts.limit;
  const [orders, total] = await Promise.all([
    safeQuery(
      () =>
        prisma.order.findMany({
          where,
          include: { customer: true },
          orderBy: { createdAt: "desc" },
          skip,
          take: opts.limit,
        }),
      [],
      "orders:list"
    ),
    safeQuery(() => prisma.order.count({ where }), 0, "orders:count"),
  ]);

  return { orders, total };
}

function payBadge(status: string) {
  const map: Record<string, string> = {
    pending: "bg-yellow-100 text-yellow-800",
    paid: "bg-green-100 text-green-800",
    failed: "bg-red-100 text-red-800",
    refunded: "bg-gray-200 text-gray-800",
  };
  const labels: Record<string, string> = {
    pending: "Ubetalt",
    paid: "Betalt",
    failed: "Feilet",
    refunded: "Refundert",
  };
  return (
    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${map[status] || "bg-gray-100"}`}>
      {labels[status] || status}
    </span>
  );
}

function fulfillBadge(status: string) {
  const map: Record<string, { label: string; className: string }> = {
    NEW: { label: "NY", className: "bg-yellow-100 text-yellow-800" },
    ORDERED_FROM_SUPPLIER: { label: "Bestilt", className: "bg-blue-100 text-blue-800" },
    SHIPPED: { label: "Sendt", className: "bg-indigo-100 text-indigo-800" },
    DELIVERED: { label: "Fullført", className: "bg-green-100 text-green-800" },
    CANCELLED: { label: "Kansellert", className: "bg-red-100 text-red-800" },
  };
  const c = map[status] || { label: status, className: "bg-gray-100 text-gray-800" };
  return (
    <span className={`rounded-full px-2.5 py-0.5 text-xs font-medium ${c.className}`}>{c.label}</span>
  );
}

function parseItems(items: any) {
  try {
    if (typeof items === "string") return JSON.parse(items);
    return items || [];
  } catch {
    return [];
  }
}

export default async function AdminOrdersPage({
  searchParams,
}: {
  searchParams: Promise<{
    filter?: string;
    payment?: string;
    email?: string;
    search?: string;
    page?: string;
  }>;
}) {
  const params = await searchParams;
  const fulfillment = params.filter || "alle";
  const payment = params.payment || "alle";
  const emailStatus = params.email || "";
  const search = params.search || "";
  const page = Math.max(1, parseInt(params.page || "1", 10) || 1);
  const limit = 50;

  const { orders, total } = await getOrders({
    fulfillment,
    payment,
    emailStatus,
    search,
    page,
    limit,
  });
  const pages = Math.max(1, Math.ceil(total / limit));

  const qs = (overrides: Record<string, string>) => {
    const p = new URLSearchParams();
    const merged = {
      filter: fulfillment,
      payment,
      email: emailStatus,
      search,
      page: String(page),
      ...overrides,
    };
    Object.entries(merged).forEach(([k, v]) => {
      if (v && v !== "alle" && !(k === "page" && v === "1") && !(k === "email" && !v)) {
        p.set(k === "filter" && v === "alle" ? "" : k, v);
      }
      if (k === "filter" && v && v !== "alle") p.set("filter", v);
      if (k === "payment" && v && v !== "alle") p.set("payment", v);
      if (k === "email" && v) p.set("email", v);
      if (k === "search" && v) p.set("search", v);
      if (k === "page" && v && v !== "1") p.set("page", v);
    });
    // rebuild cleanly
    const clean = new URLSearchParams();
    if (merged.filter && merged.filter !== "alle") clean.set("filter", merged.filter);
    if (merged.payment && merged.payment !== "alle") clean.set("payment", merged.payment);
    if (merged.email) clean.set("email", merged.email);
    if (merged.search) clean.set("search", merged.search);
    if (merged.page && merged.page !== "1") clean.set("page", merged.page);
    const s = clean.toString();
    return s ? `/admin/orders?${s}` : "/admin/orders";
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 sm:text-3xl">Ordrer</h1>
          <p className="mt-1 text-sm text-gray-600">Morgenkø — betaling og oppfyllelse</p>
        </div>
        <div className="text-sm font-medium text-gray-700">
          {total} {total === 1 ? "ordre" : "ordrer"}
        </div>
      </div>

      {/* Quick money queues */}
      <div className="flex flex-wrap gap-2">
        {[
          { href: qs({ payment: "paid", filter: "NEW", page: "1" }), label: "Betalt + NY (pakk/kjøp)" },
          { href: qs({ payment: "pending", page: "1", filter: "alle" }), label: "Ubetalt" },
          { href: qs({ payment: "failed", page: "1", filter: "alle" }), label: "Feilet betaling" },
          { href: qs({ payment: "refunded", page: "1", filter: "alle" }), label: "Refundert" },
          { href: qs({ email: "FAILED", page: "1", filter: "alle", payment: "alle" }), label: "E-post feilet" },
          { href: "/admin/orders", label: "Alle" },
        ].map((chip) => (
          <Link
            key={chip.label}
            href={chip.href}
            className="rounded-full border border-gray-300 bg-white px-3 py-1.5 text-xs font-medium text-gray-800 hover:bg-gray-50"
          >
            {chip.label}
          </Link>
        ))}
      </div>

      <div className="rounded-lg border border-gray-200 bg-white p-4 shadow-sm sm:p-6">
        <form method="GET" className="flex flex-col gap-3 md:flex-row md:flex-wrap md:items-end">
          <div>
            <label className="mb-1 block text-xs font-medium text-gray-700">Oppfyllelse</label>
            <select
              name="filter"
              defaultValue={fulfillment}
              className="rounded-lg border border-gray-300 px-3 py-2 text-sm"
            >
              <option value="alle">Alle</option>
              <option value="NEW">NY</option>
              <option value="ORDERED_FROM_SUPPLIER">Bestilt hos leverandør</option>
              <option value="SHIPPED">Sendt</option>
              <option value="DELIVERED">Fullført</option>
              <option value="CANCELLED">Kansellert</option>
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-gray-700">Betaling</label>
            <select
              name="payment"
              defaultValue={payment}
              className="rounded-lg border border-gray-300 px-3 py-2 text-sm"
            >
              <option value="alle">Alle</option>
              <option value="pending">Ubetalt</option>
              <option value="paid">Betalt</option>
              <option value="failed">Feilet</option>
              <option value="refunded">Refundert</option>
            </select>
          </div>
          <div>
            <label className="mb-1 block text-xs font-medium text-gray-700">E-post</label>
            <select
              name="email"
              defaultValue={emailStatus}
              className="rounded-lg border border-gray-300 px-3 py-2 text-sm"
            >
              <option value="">Alle</option>
              <option value="FAILED">Feilet</option>
            </select>
          </div>
          <div className="min-w-[200px] flex-1">
            <label className="mb-1 block text-xs font-medium text-gray-700">Søk</label>
            <input
              type="text"
              name="search"
              defaultValue={search}
              placeholder="Ordrenr, navn, e-post…"
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm"
            />
          </div>
          <button
            type="submit"
            className="rounded-lg bg-green-600 px-5 py-2 text-sm font-medium text-white hover:bg-green-700"
          >
            Filtrer
          </button>
        </form>
      </div>

      <div className="overflow-hidden rounded-lg border border-gray-200 bg-white shadow-sm">
        <div className="overflow-x-auto">
          <table className="w-full min-w-[900px]">
            <thead className="border-b border-gray-200 bg-gray-50">
              <tr>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Ordre</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Kunde</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Varer</th>
                <th className="px-4 py-3 text-right text-xs font-semibold uppercase text-gray-700">Total</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Betaling</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Oppfyllelse</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Dato</th>
                <th className="px-4 py-3 text-left text-xs font-semibold uppercase text-gray-700">Handling</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {orders.length === 0 ? (
                <tr>
                  <td colSpan={8} className="px-6 py-12 text-center text-sm text-gray-600">
                    Ingen ordrer matcher filteret
                  </td>
                </tr>
              ) : (
                orders.map((order) => {
                  const items = parseItems(order.items);
                  const itemCount = items.reduce(
                    (sum: number, item: any) => sum + (item.quantity || 1),
                    0
                  );
                  return (
                    <tr key={order.id} className="hover:bg-gray-50">
                      <td className="whitespace-nowrap px-4 py-3">
                        <Link
                          href={`/admin/orders/${order.id}`}
                          className="text-sm font-semibold text-green-600 hover:underline"
