                          {order.orderNumber}
                        </Link>
                      </td>
                      <td className="px-4 py-3">
                        <div className="text-sm font-medium text-gray-900">
                          {order.customer?.name || "—"}
                        </div>
                        <div className="max-w-[180px] truncate text-xs text-gray-500">
                          {order.customer?.email || order.customerEmail || "—"}
                        </div>
                      </td>
                      <td className="px-4 py-3 text-sm text-gray-900">{itemCount} stk</td>
                      <td className="px-4 py-3 text-right text-sm font-medium">
                        {formatCurrency(order.total)}
                      </td>
                      <td className="px-4 py-3">{payBadge(order.paymentStatus)}</td>
                      <td className="px-4 py-3">{fulfillBadge(order.fulfillmentStatus)}</td>
                      <td className="whitespace-nowrap px-4 py-3 text-xs text-gray-600">
                        {new Date(order.createdAt).toLocaleString("no-NO")}
                      </td>
                      <td className="space-x-2 whitespace-nowrap px-4 py-3 text-sm">
                        <Link
                          href={`/admin/orders/${order.id}`}
                          className="font-medium text-green-600 hover:underline"
                        >
                          Åpne
                        </Link>
                        <Link
                          href={`/admin/orders/${order.id}/print`}
                          className="font-medium text-gray-600 hover:underline"
                          target="_blank"
                        >
                          Pakkseddel
                        </Link>
                      </td>
                    </tr>
                  );
                })
              )}
            </tbody>
          </table>
        </div>
      </div>

      {pages > 1 && (
        <div className="flex items-center justify-between text-sm">
          <span className="text-gray-600">
            Side {page} av {pages}
          </span>
          <div className="flex gap-2">
            {page > 1 && (
              <Link
                href={qs({ page: String(page - 1) })}
                className="rounded border px-3 py-1 hover:bg-gray-50"
              >
                Forrige
              </Link>
            )}
            {page < pages && (
              <Link
                href={qs({ page: String(page + 1) })}
                className="rounded border px-3 py-1 hover:bg-gray-50"
              >
                Neste
              </Link>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import { ArrowLeft, Save, Image as ImageIcon, ExternalLink, Copy, Check } from 'lucide-react';
import Image from 'next/image';

interface Variant {
  id: string;
  name: string;
  image: string | null;
  attributes: any;
}

export default function EditVariantsPage() {
  const params = useParams();
  const router = useRouter();
  const productId = params.id as string;
  
  const [product, setProduct] = useState<any>(null);
  const [variants, setVariants] = useState<Variant[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [copiedIndex, setCopiedIndex] = useState<number | null>(null);

  useEffect(() => {
    fetchProduct();
  }, [productId]);

  const fetchProduct = async () => {
    try {
      const res = await fetch(`/api/admin/products/${productId}`);
      if (!res.ok) throw new Error('Failed to fetch product');
      const data = await res.json();
      setProduct(data);
      setVariants(data.variants || []);
    } catch (error) {
      console.error('Error:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleImageChange = (variantId: string, imageUrl: string) => {
    setVariants(prev => prev.map(v => 
      v.id === variantId ? { ...v, image: imageUrl } : v
    ));
  };

  const copyImageUrl = (url: string, index: number) => {
    navigator.clipboard.writeText(url);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  const getAvailableImages = (): string[] => {
    if (!product?.images) return [];
    try {
      return JSON.parse(product.images);
    } catch {
      return [];
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      for (const variant of variants) {
        await fetch(`/api/admin/products/variants/${variant.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ image: variant.image }),
        });
      }
      
      // Update product images to include all variant images
      const variantImages = variants
        .map(v => v.image)
        .filter((img): img is string => !!img);
      
      const productImages = product.images ? JSON.parse(product.images) : [];
      const allImages = [...new Set([...variantImages, ...productImages])];
      
      await fetch(`/api/admin/products/${productId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ images: JSON.stringify(allImages) }),
      });
      
      router.push(`/admin/products`);
    } catch (error) {
      console.error('Error saving:', error);
      alert('Feil ved lagring');
    } finally {
      setSaving(false);
    }
  };

  if (loading) {
    return (
      <div className="p-8">
        <div className="text-center">Laster...</div>
      </div>
    );
  }

  const availableImages = getAvailableImages();

  return (
    <div className="p-8 max-w-6xl mx-auto">
      <div className="mb-6">
        <button
          onClick={() => router.back()}
          className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4"
        >
          <ArrowLeft size={20} />
          Tilbake
        </button>
        <div className="flex items-center justify-between mb-2">
          <div>
            <h1 className="text-2xl font-bold">Rediger Variant-bilder</h1>
            <p className="text-gray-600 mt-1">{product?.name}</p>
          </div>
          {product?.supplierUrl && (
            <a
              href={product.supplierUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
            >
              <ExternalLink size={18} />
              Åpne på Temu
            </a>
          )}
        </div>
      </div>

      {/* Available images gallery */}
      {availableImages.length > 0 && (
        <div className="mb-8 bg-white p-6 rounded-lg shadow">
          <h2 className="text-lg font-semibold mb-4">Tilgjengelige bilder</h2>
          <div className="grid grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-4">
            {availableImages.map((imgUrl: string, index: number) => (
              <div key={index} className="relative group">
                <div className="aspect-square bg-gray-100 rounded-lg overflow-hidden">
                  <Image
                    src={imgUrl}
                    alt={`Bilde ${index + 1}`}
                    width={100}
                    height={100}
                    className="w-full h-full object-contain"
                    unoptimized
                  />
                </div>
                <button
                  onClick={() => copyImageUrl(imgUrl, index)}
                  className="absolute inset-0 bg-black bg-opacity-0 group-hover:bg-opacity-50 transition-all flex items-center justify-center opacity-0 group-hover:opacity-100 rounded-lg"
                  title="Klikk for å kopiere URL"
                >
                  {copiedIndex === index ? (
                    <Check size={20} className="text-green-400" />
                  ) : (
                    <Copy size={20} className="text-white" />
                  )}
                </button>
              </div>
            ))}
          </div>
          <p className="text-xs text-gray-500 mt-2">
            Hover over bildene for å kopiere URL. Klikk på "Kopier" for å lime inn i variant-feltet.
          </p>
        </div>
      )}

      <div className="space-y-6">
        {variants.map((variant) => {
          const attrs = variant.attributes || {};
          const color = attrs.color || attrs.farge || variant.name;
          
          return (
            <div key={variant.id} className="bg-white p-6 rounded-lg shadow">
              <h3 className="text-lg font-semibold mb-4">{color}</h3>
              
              <div className="flex gap-6">
                <div className="w-32 h-32 bg-gray-100 rounded-lg overflow-hidden flex-shrink-0">
                  {variant.image ? (
                    <Image
                      src={variant.image}
                      alt={color}
                      width={128}
                      height={128}
                      className="w-full h-full object-contain"
                      unoptimized
                      onError={(e) => {
                        (e.target as HTMLImageElement).style.display = 'none';
                        (e.target as HTMLImageElement).parentElement!.innerHTML = 
                          '<div class="w-full h-full flex items-center justify-center text-red-400 text-xs text-center">Feil ved lasting</div>';
                      }}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center text-gray-400">
                      <ImageIcon size={32} />
                    </div>
                  )}
                </div>
                
                <div className="flex-1">
                  <label className="block text-sm font-medium mb-2">
                    Bilde URL
                  </label>
                  <div className="flex gap-2">
                    <input
                      type="url"
                      value={variant.image || ''}
                      onChange={(e) => handleImageChange(variant.id, e.target.value)}
                      placeholder="https://img.kwcdn.com/product/..."
                      className="flex-1 px-3 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                    />
                    {variant.image && (
                      <button
                        onClick={() => copyImageUrl(variant.image!, -1)}
                        className="px-3 py-2 border rounded-lg hover:bg-gray-50"
                        title="Kopier URL"
                      >
                        <Copy size={16} />
                      </button>
                    )}
                  </div>
                  <p className="text-xs text-gray-500 mt-1">
                    Lim inn URL til bildet for denne varianten, eller klikk på et bilde over for å kopiere URL
                  </p>
                </div>
              </div>
            </div>
          );
        })}
      </div>

      <div className="mt-8 flex gap-4">
        <button
          onClick={handleSave}
          disabled={saving}
          className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 disabled:opacity-50"
        >
          <Save size={20} />
          {saving ? 'Lagrer...' : 'Lagre alle bilder'}
        </button>
        <button
          onClick={() => router.back()}
          className="px-6 py-3 border rounded-lg hover:bg-gray-50"
        >
          Avbryt
        </button>
      </div>
    </div>
  );
}

"use server";

import { getAuthSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import slugify from "slugify";
import { improveTitle } from "@/lib/utils/improve-product-title";
import { safeQuery } from "@/lib/safeQuery";
import { DEFAULT_STORE_ID } from "@/lib/store";
import { getProviderRegistry } from "@/lib/providers/server-only";
import type { BulkImportResult } from "@/lib/providers";
import { SupplierName } from "@prisma/client";
import { sanitizeDescriptionWithFallback } from "@/lib/import/sanitizeDescription";
import {
  calculateCompareAtPrice,
  calculateSuggestedRetailPrice,
  convertPriceToNOK,
} from "@/lib/import/pricing";

function generateId(): string {
  return Math.random().toString(36).substring(2, 10) + Date.now().toString(36).substring(2, 6);
}

/**
 * Map provider name string to SupplierName enum value
 * Returns null if provider name doesn't match any known supplier
 */
function mapProviderToSupplierName(providerName: string): SupplierName | null {
  const normalized = providerName.toLowerCase().trim();
  
  // Map known provider names to SupplierName enum values
  if (normalized === "alibaba") {
    return SupplierName.alibaba;
  }
  if (normalized === "ebay") {
    return SupplierName.ebay;
  }
  if (normalized === "temu") {
    return SupplierName.temu;
  }
  
  // Unknown provider
  return null;
}

async function importProduct(
  inputUrl: string,
  providerName?: string
): Promise<BulkImportResult> {
  try {
    const registry = getProviderRegistry();
    
    // Get provider (by name or auto-detect)
    const provider = registry.getProviderForUrl(inputUrl, providerName);
    
    const warnings: string[] = [];
    
    if (!provider) {
      const detectedProviders = registry.getAllProviders().map(p => p.getName()).join(", ");
      return {
        inputUrl,
        normalizedUrl: inputUrl,
        providerUsed: "none",
        status: "error",
        message: `Ustøttet leverandør. Støttede: ${detectedProviders}`,
        warnings,
      };
    }

    const providerUsed = provider.getName();

    // Normalize URL
    const normalizedUrl = provider.normalizeUrl(inputUrl);

    // Fetch raw product data
    let rawProduct;
    try {
      rawProduct = await provider.fetchProduct(normalizedUrl);
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : "Ukjent feil";
      console.error(`[Bulk Import] Error fetching product from ${providerUsed}:`, {
        url: normalizedUrl,
        error: errorMessage,
      });
      
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "error",
        message: "Kunne ikke hente produktdata. Sjekk at URL-en er korrekt og at produktet eksisterer.",
        warnings,
      };
    }

    // Check for warnings in raw product metadata
    if (rawProduct.metadata?.warnings && Array.isArray(rawProduct.metadata.warnings)) {
      warnings.push(...rawProduct.metadata.warnings);
    }

    // Map to our product format
    const data = provider.mapToProduct(rawProduct, normalizedUrl);

    // Sjekk om produktet allerede eksisterer (bruk normalisert URL)
    const existing = await safeQuery(
      () =>
        prisma.product.findFirst({
          where: {
            supplierUrl: normalizedUrl,
          },
        }),
      null,
      "admin:bulk-import:existing"
    );

    if (existing) {
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "warning",
        message: `Produktet eksisterer allerede: ${existing.name}`,
        warnings: [...warnings, "Produktet ble ikke opprettet fordi det allerede finnes i databasen"],
      };
    }

    // Forbered data
    const baseImages = data.images || [];
    
    // Sanitize description to remove supplier references
    const rawDescription = data.description || "";
    const description = sanitizeDescriptionWithFallback(
      rawDescription,
      "Dette produktet er en del av vårt utvalg av elektronikk og tilbehør. Vi leverer kvalitetsprodukter med fokus på funksjonalitet og verdi."
    );
    const shortDescription = description.substring(0, 150) + (description.length > 150 ? "..." : "");

    // Håndter varianter
    const hasVariants = data.variants && data.variants.length > 1;
    const variants = data.variants || [];

    // CRITICAL: Collect ALL images from product AND variants
    const allImagesSet = new Set<string>();
    
    baseImages.forEach((img: string) => {
      if (img && img.startsWith('http') && !img.includes('placeholder')) {
        allImagesSet.add(img);
      }
    });
    
    variants.forEach((variant: any) => {
      if (variant.image && 
          variant.image.startsWith('http') && 
          !variant.image.includes('placeholder') &&
          !variant.image.includes('placehold.co')) {
        allImagesSet.add(variant.image);
      }
    });

    const variantImages = variants
      .map((v: any) => v.image)
      .filter((img: string) => img && img.startsWith('http') && !img.includes('placeholder'));

    const images = [
      ...variantImages.filter((img: string, idx: number, arr: string[]) => arr.indexOf(img) === idx),
      ...Array.from(allImagesSet).filter(img => !variantImages.includes(img))
    ];

    // Bestem kategori
    let category = "Elektronikk";
    const titleLower = data.title.toLowerCase();
    if (titleLower.includes("phone") || titleLower.includes("iphone") || titleLower.includes("mobil")) {
      category = "Mobil & Tilbehør";
    } else if (
      titleLower.includes("computer") ||
      titleLower.includes("laptop") ||
      titleLower.includes("pc") ||
      titleLower.includes("tastatur") ||
      titleLower.includes("keyboard")
    ) {
      category = "Datamaskiner";
    } else if (titleLower.includes("tv") || titleLower.includes("speaker") || titleLower.includes("høyttaler")) {
      category = "TV & Lyd";
    } else if (titleLower.includes("game") || titleLower.includes("gaming")) {
      category = "Gaming";
    } else if (titleLower.includes("home") || titleLower.includes("hjem")) {
      category = "Hjem & Fritid";
    }

    // Base price
    let basePrice = variants.length > 0 ? Math.min(...variants.map((v) => v.price)) : data.price.amount;

    if (!basePrice || basePrice === 0) {
      basePrice = 9.99;
    }

    // Konverter pris til NOK og bruk den dynamiske priskurven
    const baseSupplierPriceNok = Math.round(convertPriceToNOK(basePrice, "USD"));
    const baseSellingPriceNok = calculateSuggestedRetailPrice(baseSupplierPriceNok);
    const baseCompareAtPriceNok = calculateCompareAtPrice(baseSellingPriceNok);

    // Forbedre produkt-tittel
    const improvedTitle = improveTitle(data.title);
    
    const sku = `${providerUsed.toUpperCase()}-${generateId().toUpperCase()}`;
    const slugBase = slugify(improvedTitle, { lower: true, strict: true });
    const slug = `${slugBase}-${generateId().substring(0, 4)}`;

    // Opprett produkt med varianter
    let product;
    try {
      product = await prisma.product.create({
        data: {
          name: improvedTitle,
          slug,
          description: description || shortDescription,
          shortDescription,
          price: baseSellingPriceNok,
          compareAtPrice: baseCompareAtPriceNok,
          supplierPrice: baseSupplierPriceNok,
          images: JSON.stringify(images),
          tags: data.specs ? JSON.stringify(Object.keys(data.specs).slice(0, 10)) : JSON.stringify([]),
          category,
          sku,
          isActive: true,
          storeId: DEFAULT_STORE_ID,
          supplierUrl: normalizedUrl,
          supplierName: mapProviderToSupplierName(providerUsed),
        variants: hasVariants
          ? {
              create: variants.map((variant, index) => {
                const variantSupplierPriceNok = Math.round(convertPriceToNOK(variant.price, "USD"));
                const variantSellingPriceNok = calculateSuggestedRetailPrice(variantSupplierPriceNok);
                const variantCompareAtPriceNok = calculateCompareAtPrice(variantSellingPriceNok);

                return {
                  name: variant.name,
                  sku: `${sku}-V${index + 1}`,
                  price: variantSellingPriceNok,
                  compareAtPrice: variantCompareAtPriceNok,
                  supplierPrice: variantSupplierPriceNok,
                  image: variant.image || null,
                  attributes: variant.attributes || {},
                  stock: variant.stock || 0,
                  isActive: true,
                };
              }),
            }
          : undefined,
      },
        include: {
          variants: true,
        },
      });
    } catch (dbError) {
      console.error(`[Bulk Import] Database error creating product:`, {
        url: normalizedUrl,
        provider: providerUsed,
        error: dbError instanceof Error ? dbError.message : "Ukjent database-feil",
      });
      
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "error",
        message: "Kunne ikke lagre produktet i databasen. Prøv igjen senere.",
        warnings,
      };
    }

    // Check for warnings
    if (images.length === 0) {
      warnings.push("Ingen bilder funnet for produktet");
    }
    if (basePrice < 1) {
      warnings.push("Pris ser ut til å være ugyldig eller manglende");
    }

    return {
      inputUrl,
      normalizedUrl,
      providerUsed,
      status: warnings.length > 0 ? "warning" : "success",
      message: `Produkt importert: ${product.name}`,
      createdProductId: product.id,
      warnings: warnings.length > 0 ? warnings : undefined,
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : "Ukjent feil";
    console.error(`[Bulk Import] Unexpected error:`, {
      url: inputUrl,
      error: errorMessage,
    });
    
    return {
      inputUrl,
      normalizedUrl: inputUrl,
      providerUsed: "unknown",
      status: "error",
      message: "En uventet feil oppstod under import. Prøv igjen senere.",
      warnings: [],
    };
  }
}

export async function importProducts(formData: FormData) {
  const session = await getAuthSession();
  if (!session?.user) {
    return { error: "Unauthorized", results: [] };
  }

  try {
    const urlsText = formData.get("urls") as string;
    const providerName = formData.get("provider") as string | null;
    
    if (!urlsText) {
      return { error: "URL-er er påkrevd", results: [] };
    }

    // Parse URLs from textarea (one per line)
    const urlList = urlsText
      .split("\n")
      .map((url) => url.trim())
      .filter((url) => url.length > 0 && (url.startsWith("http://") || url.startsWith("https://")));

    if (urlList.length === 0) {
      return { error: "Ingen gyldige URL-er funnet", results: [] };
    }

    // Importer alle produkter sekvensielt
    // Continue even if individual URLs fail
    const results: BulkImportResult[] = [];
    
    for (let i = 0; i < urlList.length; i++) {
      const url = urlList[i];
      
      try {
        const result = await importProduct(url, providerName || undefined);
        results.push(result);
      } catch (error) {
        // Log error but continue with next URL
        console.error(`[Bulk Import] Error processing URL ${i + 1}/${urlList.length}:`, {
          url,
          error: error instanceof Error ? error.message : "Ukjent feil",
        });
        
        results.push({
          inputUrl: url,
          normalizedUrl: url,
          providerUsed: "unknown",
          status: "error",
          message: "En uventet feil oppstod under import av denne URL-en.",
          warnings: [],
        });
      }

      // Rate limiting: wait between requests (except for last one)
      if (i < urlList.length - 1) {
        await new Promise((resolve) => setTimeout(resolve, 2000));
      }
    }

    return { results, error: null };
  } catch (error) {
    const message = error instanceof Error ? error.message : "Ukjent feil ved bulk import";
    return { error: message, results: [] };
  }
}

"use client";

import { useEffect, useState } from "react";
import { useRouter, useParams } from "next/navigation";
import { Loader2, Save, AlertCircle, Image as ImageIcon, X, ExternalLink, Download, Check, Plus, Trash2, Sparkles } from "lucide-react";
import Link from "next/link";
import Image from "next/image";
import { AIHelper } from "@/components/admin/AIHelper";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";

interface ProductVariant {
  id?: string;
  name: string;
  price: number;
  compareAtPrice?: number;
  supplierPrice?: number;
  image?: string;
  attributes: Record<string, string>;
  stock: number;
  isActive: boolean;
}

/**
 * Safe numeric parsing: empty, missing or non-numeric values become 0.
 * Guarantees a finite number so NaN never reaches React inputs or math.
 */
const toNumber = (value: unknown): number => {
  if (typeof value === "number") {
    return Number.isFinite(value) ? value : 0;
  }
  if (value === null || value === undefined || value === "") {
    return 0;
  }
  const parsed = parseFloat(String(value));
  return Number.isFinite(parsed) ? parsed : 0;
};

const DEFAULT_FORM = {
  name: "",
  price: 0,
  compareAtPrice: 0,
  supplierPrice: 0,
  supplierUrl: "",
  supplierName: "",
  description: "",
  shortDescription: "",
  category: "Elektronikk",
  images: "[]",
  tags: "[]",
  isActive: true,
};

export default function EditProduct() {
  const router = useRouter();
  const params = useParams();
  const productId = params.id as string;

  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [formData, setFormData] = useState(DEFAULT_FORM);
  const [images, setImages] = useState<string[]>([]);
  const [newImageUrl, setNewImageUrl] = useState("");
  const [scraping, setScraping] = useState(false);
  const [scrapeResult, setScrapeResult] = useState<{
    images?: string[];
    price?: number;
    supplierPrice?: number;
    variants?: Array<{
      name: string;
      price: number;
      attributes: Record<string, string>;
      image?: string;
    }>;
  } | null>(null);
  const [variants, setVariants] = useState<ProductVariant[]>([]);
  const [showVariantForm, setShowVariantForm] = useState(false);
  const [editingVariantIndex, setEditingVariantIndex] = useState<number | null>(null);
  const [variantForm, setVariantForm] = useState<ProductVariant>({
    name: "",
    price: formData.price,
    compareAtPrice: formData.compareAtPrice,
    supplierPrice: formData.supplierPrice,
    image: "",
    attributes: {},
    stock: 10,
    isActive: true,
  });
  const [aiModalOpen, setAiModalOpen] = useState(false);
  const [aiModalType, setAiModalType] = useState<"productDescription" | "seo">("productDescription");

  const parseImagesFromString = (imagesStr: string): string[] => {
    if (!imagesStr) return [];
    try {
      const parsed = JSON.parse(imagesStr);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  };

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch(`/api/admin/products/${productId}`);
        if (!response.ok) {
          throw new Error("Produkt ikke funnet");
        }

        const payload = await response.json();
        // API returns { ok, data }; unwrap the envelope
        const product = payload?.data ?? payload;

        const productImages =
          typeof product.images === "string" ? product.images : JSON.stringify(product.images ?? []);
        const parsedImages = parseImagesFromString(productImages);

        setFormData({
          name: product.name ?? "",
          price: toNumber(product.price),
          compareAtPrice: toNumber(product.compareAtPrice),
          supplierPrice: toNumber(product.supplierPrice),
          supplierUrl: product.supplierUrl ?? "",
          supplierName: product.supplierName ?? "",
          description: product.description ?? "",
          shortDescription: product.shortDescription ?? "",
          category: product.category ?? "Elektronikk",
          images: productImages,
          tags: typeof product.tags === "string" ? product.tags : JSON.stringify(product.tags ?? []),
          isActive: product.isActive ?? true,
        });
        setImages(parsedImages);
        
        // Hent varianter
        const variantsResponse = await fetch(`/api/admin/products/${productId}/variants`);
        if (variantsResponse.ok) {
          const variantsData = await variantsResponse.json();
          const safeVariants: ProductVariant[] = (variantsData.variants || []).map(
            (variant: ProductVariant) => ({
              ...variant,
              price: toNumber(variant.price),
              compareAtPrice:
                variant.compareAtPrice != null ? toNumber(variant.compareAtPrice) : undefined,
              supplierPrice:
                variant.supplierPrice != null ? toNumber(variant.supplierPrice) : undefined,
              stock: toNumber(variant.stock),
            })
          );
          setVariants(safeVariants);
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : "Feil ved lasting av produkt");
      } finally {
        setLoading(false);
      }
    };

    if (productId) {
      fetchProduct();
    }
  }, [productId]);

  const handleAddImage = () => {
    if (newImageUrl.trim()) {
      const updatedImages = [...images, newImageUrl.trim()];
      setImages(updatedImages);
      setFormData({ ...formData, images: JSON.stringify(updatedImages) });
      setNewImageUrl("");
    }
  };

  const handleRemoveImage = (index: number) => {
    const updatedImages = images.filter((_, i) => i !== index);
    setImages(updatedImages);
    setFormData({ ...formData, images: JSON.stringify(updatedImages) });
  };

  const handleScrapeFromUrl = async () => {
    if (!formData.supplierUrl || !formData.supplierUrl.trim()) {
      setError("Leverandør URL er påkrevd for å hente bilder og priser");
      return;
    }

    setScraping(true);
    setError("");
    setScrapeResult(null);

    try {
      const response = await fetch("/api/admin/scrape-product", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url: formData.supplierUrl.trim() }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Kunne ikke hente produktdata");
      }

      const data = await response.json();
      
      // Sett scrapet data
      setScrapeResult({
        images: data.images || [],
        price: data.price || data.suggestedPrice,
        supplierPrice: data.price, // Leverandørpris
        variants: data.variants || [],
      });
    } catch (err) {
      setError(err instanceof Error ? err.message : "Feil ved henting av produktdata");
    } finally {
      setScraping(false);
    }
  };

  const handleUseScrapedPrice = () => {
    if (scrapeResult?.price) {
      setFormData({ ...formData, price: toNumber(scrapeResult.price) });
      if (scrapeResult.supplierPrice) {
        setFormData({
          ...formData,
          price: toNumber(scrapeResult.price),
          supplierPrice: toNumber(scrapeResult.supplierPrice),
        });
      }
    }
  };

  const handleUseScrapedImages = () => {
    if (scrapeResult?.images && scrapeResult.images.length > 0) {
      const updatedImages = [...images, ...scrapeResult.images];
      setImages(updatedImages);
      setFormData({ ...formData, images: JSON.stringify(updatedImages) });
      setScrapeResult(null); // Clear scrape result after using
    }
  };

  const handleAddScrapedImage = (imageUrl: string) => {
    if (!images.includes(imageUrl)) {
      const updatedImages = [...images, imageUrl];
      setImages(updatedImages);
      setFormData({ ...formData, images: JSON.stringify(updatedImages) });
    }
  };

  const handleSave = async () => {
    setSaving(true);
    setError("");

    try {
      // Oppdater produkt
      const response = await fetch(`/api/admin/products/${productId}`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          images: JSON.stringify(images),
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Feil ved oppdatering");
      }

      // Oppdater varianter
      const variantsResponse = await fetch(`/api/admin/products/${productId}/variants`, {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ variants }),
      });

      if (!variantsResponse.ok) {
        const data = await variantsResponse.json();
        throw new Error(data.error || "Feil ved oppdatering av varianter");
      }

      router.push("/admin/products");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Feil ved lagring");
    } finally {
      setSaving(false);
    }
  };

  const handleAddVariant = () => {
    if (!variantForm.name.trim()) {
      setError("Variantnavn er påkrevd");
      return;
    }

    if (editingVariantIndex !== null) {
      // Oppdater eksisterende variant
      const updatedVariants = [...variants];
      updatedVariants[editingVariantIndex] = { ...variantForm };
      setVariants(updatedVariants);
      setEditingVariantIndex(null);
    } else {
      // Legg til ny variant
      setVariants([...variants, { ...variantForm }]);
    }

    // Reset form
    setVariantForm({
      name: "",
      price: formData.price,
      compareAtPrice: formData.compareAtPrice,
      supplierPrice: formData.supplierPrice,
      image: "",
      attributes: {},
      stock: 10,
      isActive: true,
    });
    setShowVariantForm(false);
  };

  const handleEditVariant = (index: number) => {
    setVariantForm({ ...variants[index] });
    setEditingVariantIndex(index);
    setShowVariantForm(true);
  };

  const handleDeleteVariant = async (index: number) => {
    if (!confirm("Er du sikker på at du vil slette denne varianten?")) {
      return;
    }

    const variant = variants[index];
    if (variant.id) {
      // Slett fra backend
      try {
        const response = await fetch(`/api/admin/products/${productId}/variants/${variant.id}`, {
          method: "DELETE",
        });
        if (!response.ok) {
          throw new Error("Kunne ikke slette variant");
        }
      } catch (err) {
        setError(err instanceof Error ? err.message : "Feil ved sletting av variant");
        return;
      }
    }

    // Fjern fra liste
    setVariants(variants.filter((_, i) => i !== index));
  };

  const handleUseScrapedVariants = () => {
    if (scrapeResult?.variants && scrapeResult.variants.length > 0) {
      const newVariants: ProductVariant[] = scrapeResult.variants.map((v) => ({
        name: v.name,
        price: toNumber(v.price),
        compareAtPrice: formData.compareAtPrice,
        supplierPrice: formData.supplierPrice,
        image: v.image || images[0] || "",
        attributes: v.attributes || {},
        stock: 10,
        isActive: true,
      }));
      setVariants([...variants, ...newVariants]);
    }
  };

  const sellingPrice = toNumber(formData.price);
  const supplierPrice = toNumber(formData.supplierPrice);
  const profit = sellingPrice - supplierPrice;
  const profitPercentage = supplierPrice > 0 ? (profit / supplierPrice) * 100 : 0;

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <Loader2 className="animate-spin text-primary" size={32} />
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold">Rediger Produkt</h1>
        <Link
          href="/admin/products"
          className="rounded-lg border border-slate-300 px-4 py-2 hover:bg-slate-50"
        >
          Avbryt
        </Link>
      </div>

      {error && (
        <div className="flex items-center gap-2 rounded-lg bg-red-50 p-4 text-red-600">
          <AlertCircle size={20} />
          <span>{error}</span>
        </div>
      )}

      <div className="rounded-xl bg-white p-6 shadow-sm">
        <div className="grid gap-4 md:grid-cols-2">
          <div>
            <label className="mb-1 block text-sm font-medium">Produktnavn (Norsk)</label>
            <input
              type="text"
              value={formData.name}
              onChange={(e) => setFormData({ ...formData, name: e.target.value })}
              className="w-full rounded-lg border border-slate-300 p-3"
              required
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Kategori</label>
            <select
              value={formData.category}
              onChange={(e) => setFormData({ ...formData, category: e.target.value })}
              className="w-full rounded-lg border border-slate-300 p-3"
            >
              <option>Elektronikk</option>
              <option>Klær</option>
              <option>Hjem</option>
              <option>Sport</option>
            </select>
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Leverandørpris (NOK)</label>
            <input
              type="number"
              value={formData.supplierPrice}
              onChange={(e) => setFormData({ ...formData, supplierPrice: toNumber(e.target.value) })}
              className="w-full rounded-lg border border-slate-300 p-3"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Din Salgspris (NOK)</label>
            <input
              type="number"
              value={formData.price}
              onChange={(e) => setFormData({ ...formData, price: toNumber(e.target.value) })}
              className="w-full rounded-lg border border-slate-300 p-3"
              required
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Før-pris (NOK)</label>
            <input
              type="number"
              value={formData.compareAtPrice}
              onChange={(e) => setFormData({ ...formData, compareAtPrice: toNumber(e.target.value) })}
              className="w-full rounded-lg border border-slate-300 p-3"
            />
          </div>

          <div>
            <label className="mb-1 block text-sm font-medium">Fortjeneste</label>
            <div className="rounded-lg border border-green-300 bg-green-50 p-3 font-medium text-green-700">
              {profit.toFixed(0)} kr ({profitPercentage.toFixed(0)}%)
            </div>
          </div>
        </div>

        {/* Leverandør informasjon */}
        <div className="mt-6 border-t pt-6">
          <h3 className="mb-4 text-lg font-semibold">Leverandør Informasjon</h3>
          <div className="grid gap-4 md:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-medium">Leverandør Navn</label>
              <input
                type="text"
                value={formData.supplierName}
                onChange={(e) => setFormData({ ...formData, supplierName: e.target.value })}
                placeholder="f.eks. Alibaba, Temu, eBay"
                className="w-full rounded-lg border border-slate-300 p-3"
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium">Leverandør URL</label>
              <div className="flex gap-2">
                <input
                  type="url"
                  value={formData.supplierUrl}
                  onChange={(e) => setFormData({ ...formData, supplierUrl: e.target.value })}
                  placeholder="https://www.temu.com/no/... eller https://www.alibaba.com/product-detail/..."
                  className="flex-1 rounded-lg border border-slate-300 p-3"
                />
                {formData.supplierUrl && (
                  <>
                    <button
                      type="button"
                      onClick={handleScrapeFromUrl}
                      disabled={scraping || !formData.supplierUrl.trim()}
                      className="flex items-center gap-2 rounded-lg border border-slate-300 bg-white px-4 py-3 text-primary hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed"
                      title="Hent bilder og priser fra URL"
                    >
                      {scraping ? (
                        <>
                          <Loader2 className="animate-spin" size={18} />
                          Henter...
                        </>
                      ) : (
                        <>
                          <Download size={18} />
                          Hent data
                        </>
                      )}
                    </button>
                    <a
                      href={formData.supplierUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 rounded-lg border border-slate-300 px-4 py-3 text-primary hover:bg-slate-50"
                      title="Åpne i ny fane"
                    >
                      <ExternalLink size={20} />
                    </a>
                  </>
                )}
              </div>
              {formData.supplierUrl && (
                <p className="mt-1 text-xs text-slate-500">
                  {formData.supplierUrl.length > 60 
                    ? formData.supplierUrl.substring(0, 60) + "..." 
                    : formData.supplierUrl}
                </p>
              )}
              
              {/* Vis scrapet data */}
              {scrapeResult && (
                <div className="mt-4 rounded-lg border border-green-200 bg-green-50 p-4">
                  <div className="mb-3 flex items-center justify-between">
                    <h4 className="font-semibold text-green-800">📥 Data hentet fra URL</h4>
                    <button
                      type="button"
                      onClick={() => setScrapeResult(null)}
                      className="text-green-600 hover:text-green-800"
                    >
                      <X size={18} />
                    </button>
                  </div>
                  
                  {/* Pris */}
                  {scrapeResult.price && (
                    <div className="mb-3 flex items-center justify-between rounded-lg bg-white p-3">
                      <div>
                        <p className="text-sm font-medium text-gray-700">Pris funnet</p>
                        <p className="text-lg font-bold text-green-700">
                          {scrapeResult.price.toFixed(0)} kr
                          {scrapeResult.supplierPrice && scrapeResult.supplierPrice !== scrapeResult.price && (
                            <span className="ml-2 text-sm text-gray-500">
                              (Leverandør: {scrapeResult.supplierPrice.toFixed(0)} kr)
                            </span>
                          )}
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={handleUseScrapedPrice}
                        className="flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-medium text-white hover:bg-green-700"
                      >
                        <Check size={16} />
                        Bruk pris
                      </button>
                    </div>
                  )}
                  
                  {/* Bilder */}
                  {scrapeResult.images && scrapeResult.images.length > 0 ? (
                    <div>
                      <div className="mb-2 flex items-center justify-between">
                        <p className="text-sm font-medium text-gray-700">
                          {scrapeResult.images.length} bilde(r) funnet
                        </p>
                        <button
                          type="button"
                          onClick={handleUseScrapedImages}
                          className="flex items-center gap-2 rounded-lg bg-green-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-green-700"
                        >
                          <Check size={14} />
                          Legg til alle
                        </button>
                      </div>
                      <div className="grid grid-cols-3 gap-2">
                        {scrapeResult.images.map((imgUrl, idx) => (
                          <div key={idx} className="group relative">
                            <div className="relative aspect-square overflow-hidden rounded-lg border border-gray-200 bg-gray-100">
                              <Image
                                src={imgUrl}
                                alt={`Scrapet bilde ${idx + 1}`}
                                fill
                                className="object-cover"
                                unoptimized
                                onError={(e) => {
                                  const target = e.target as HTMLImageElement;
                                  target.src = "https://placehold.co/200x200?text=Feil+bilde";
                                }}
                              />
                            </div>
                            <button
                              type="button"
                              onClick={() => handleAddScrapedImage(imgUrl)}
                              className="absolute inset-0 flex items-center justify-center rounded-lg bg-black/50 opacity-0 transition-opacity group-hover:opacity-100"
                            >
                              <Check size={24} className="text-white" />
                            </button>
                          </div>
                        ))}
                      </div>
                    </div>
                  ) : (
                    <div className="rounded-lg bg-yellow-50 p-3 text-sm text-yellow-800">
                      <AlertCircle size={16} className="mr-2 inline" />
                      Ingen bilder funnet. Du kan legge til bilder manuelt nedenfor.
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="mt-6 border-t pt-6">
          <label className="mb-4 block text-sm font-medium">Produktbilder</label>

          {/* Eksisterende bilder */}
          {images.length > 0 && (
            <div className="mb-4 grid grid-cols-2 gap-4 md:grid-cols-3 lg:grid-cols-4">
              {images.map((imageUrl, index) => {
                // Sjekk om URLen ser ut som et faktisk bilde (har bildeendelse eller er fra kjente CDNer)
                const isImageUrl =
                  imageUrl &&
                  typeof imageUrl === "string" &&
                  (imageUrl.match(/\.(jpg|jpeg|png|gif|webp|svg|avif)(\?|$)/i) ||
                    imageUrl.includes("alicdn.com") ||
                    imageUrl.includes("ebayimg.com") ||
                    imageUrl.includes("temu.com") ||
                    imageUrl.includes("placehold.co"));

                const displayUrl = isImageUrl ? imageUrl : "https://placehold.co/600x600?text=Ingen+bilde";

                return (
                  <div key={index} className="group relative">
                    <div className="relative aspect-square overflow-hidden rounded-lg border border-slate-300 bg-slate-100">
                      {isImageUrl ? (
                        <Image
                          src={displayUrl}
                          alt={`Produktbilde ${index + 1}`}
                          fill
                          className="object-cover"
                          unoptimized
                          onError={(e) => {
                            const target = e.target as HTMLImageElement;
                            target.src = "https://placehold.co/600x600?text=Ingen+bilde";
                          }}
                        />
                      ) : (
                        <div className="flex h-full items-center justify-center text-xs text-slate-400">
                          Ikke et bilde
                        </div>
                      )}
                    </div>
                    <button
                      type="button"
                      onClick={() => handleRemoveImage(index)}
                      className="absolute right-2 top-2 rounded-full bg-red-500 p-1.5 text-white opacity-0 transition-opacity group-hover:opacity-100"
                    >
                      <X size={16} />
                    </button>
                  </div>
                );
              })}
            </div>
          )}

          {/* Legg til nytt bilde */}
          <div className="flex gap-2">
            <input
              type="url"
              value={newImageUrl}
              onChange={(e) => setNewImageUrl(e.target.value)}
              onKeyPress={(e) => {
                if (e.key === "Enter") {
                  e.preventDefault();
                  handleAddImage();
                }
              }}
              placeholder="https://example.com/bilde.jpg (eller .png, .webp, osv.)"
              className="flex-1 rounded-lg border border-slate-300 p-3"
            />
            <button
              type="button"
              onClick={handleAddImage}
              disabled={!newImageUrl.trim()}
              className="flex items-center gap-2 rounded-lg bg-primary px-4 py-3 text-white transition hover:bg-primary-dark disabled:opacity-50"
            >
              <ImageIcon size={20} />
              Legg til bilde
            </button>
          </div>
          <p className="mt-2 text-xs text-slate-500">
            Lim inn bildelenke (URL) - må ende med .jpg, .png, .webp, osv. eller være fra Alibaba/eBay/Temu CDN
          </p>
        </div>

        <div className="mt-4">
          <label className="mb-1 block text-sm font-medium">Status</label>
          <label className="flex items-center gap-2">
            <input
              type="checkbox"
              checked={formData.isActive}
              onChange={(e) => setFormData({ ...formData, isActive: e.target.checked })}
              className="rounded border-slate-300"
            />
            <span>Aktivt produkt</span>
          </label>
        </div>

        <div className="mt-4">
          <label className="mb-1 block text-sm font-medium">Kort Beskrivelse</label>
          <input
            type="text"
            value={formData.shortDescription}
            onChange={(e) => setFormData({ ...formData, shortDescription: e.target.value })}
            className="w-full rounded-lg border border-slate-300 p-3"
            maxLength={150}
          />
        </div>

        <div className="mt-4">
          <div className="mb-2 flex items-center justify-between">
            <label className="block text-sm font-medium">Beskrivelse</label>
            <Dialog open={aiModalOpen && aiModalType === "productDescription"} onOpenChange={setAiModalOpen}>
              <DialogTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setAiModalType("productDescription");
                    setAiModalOpen(true);
                  }}
                  className="flex items-center gap-2"
                >
                  <Sparkles size={16} />
                  Generer med AI
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Generer produktbeskrivelse med AI</DialogTitle>
                  <DialogDescription>
                    AI-en vil generere en profesjonell produktbeskrivelse basert på produktnavn, kategori og pris.
                  </DialogDescription>
                </DialogHeader>
                <AIHelper
                  type="productDescription"
                  onResult={(result) => {
                    if (result.description) {
                      setFormData({ ...formData, description: result.description });
                      setAiModalOpen(false);
                    }
                  }}
                  productData={{
                    name: formData.name,
                    category: formData.category,
                    price: formData.price,
                  }}
                />
              </DialogContent>
            </Dialog>
          </div>
          <textarea
            value={formData.description}
            onChange={(e) => setFormData({ ...formData, description: e.target.value })}
            rows={6}
            className="w-full rounded-lg border border-slate-300 p-3"
          />
        </div>

        <div className="mt-6 border-t pt-6">
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold">SEO (Søkemotoroptimalisering)</h3>
            <Dialog open={aiModalOpen && aiModalType === "seo"} onOpenChange={(open) => {
              if (!open) setAiModalOpen(false);
            }}>
              <DialogTrigger asChild>
                <Button
                  type="button"
                  variant="outline"
                  size="sm"
                  onClick={() => {
                    setAiModalType("seo");
                    setAiModalOpen(true);
                  }}
                  className="flex items-center gap-2"
                >
                  <Sparkles size={16} />
                  Generer SEO med AI
                </Button>
              </DialogTrigger>
              <DialogContent className="max-w-2xl">
                <DialogHeader>
                  <DialogTitle>Generer SEO-tittel og beskrivelse med AI</DialogTitle>
                  <DialogDescription>
                    AI-en vil generere optimal SEO-tittel og meta-beskrivelse for søkemotorer.
                  </DialogDescription>
                </DialogHeader>
                <AIHelper
                  type="seo"
                  onResult={(result) => {
                    console.log("SEO result:", result);
                  }}
                  productData={{
                    name: formData.name,
                    category: formData.category,
                    description: formData.description || formData.shortDescription,
                  }}
                />
              </DialogContent>
            </Dialog>
          </div>
          <p className="text-sm text-gray-600 mb-4">
            SEO-felter kan legges til senere. Bruk AI-helper for å generere optimalt innhold.
          </p>
        </div>

        {/* Produktvarianter */}
        <div className="mt-6 border-t pt-6">
          <div className="mb-4 flex items-center justify-between">
            <h3 className="text-lg font-semibold">Produktvarianter</h3>
            <button
              type="button"
              onClick={() => {
                setShowVariantForm(!showVariantForm);
                setEditingVariantIndex(null);
                setVariantForm({
                  name: "",
                  price: formData.price,
                  compareAtPrice: formData.compareAtPrice,
                  supplierPrice: formData.supplierPrice,
                  image: "",
                  attributes: {},
                  stock: 10,
                  isActive: true,
                });
              }}
              className="flex items-center gap-2 rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white hover:bg-brand-dark"
            >
              <Plus size={18} />
              Legg til variant
            </button>
          </div>

          {/* Vis scrapet varianter */}
          {scrapeResult?.variants && scrapeResult.variants.length > 0 && (
            <div className="mb-4 rounded-lg border border-green-200 bg-green-50 p-4">
              <div className="mb-2 flex items-center justify-between">
                <p className="text-sm font-medium text-gray-700">
                  {scrapeResult.variants.length} variant(er) funnet fra URL
                </p>
                <button
                  type="button"
                  onClick={handleUseScrapedVariants}
                  className="flex items-center gap-2 rounded-lg bg-green-600 px-3 py-1.5 text-xs font-medium text-white hover:bg-green-700"
                >
                  <Check size={14} />
                  Legg til alle varianter
                </button>
              </div>
              <div className="space-y-2">
                {scrapeResult.variants.slice(0, 3).map((v, idx) => (
                  <div key={idx} className="rounded-lg bg-white p-2 text-sm">
                    <span className="font-medium">{v.name}</span>
                    {" - "}
                    <span className="text-gray-600">{v.price.toFixed(0)} kr</span>
                    {Object.keys(v.attributes).length > 0 && (
                      <span className="ml-2 text-xs text-gray-500">
                        ({Object.entries(v.attributes).map(([k, v]) => `${k}: ${v}`).join(", ")})
                      </span>
                    )}
                  </div>
                ))}
                {scrapeResult.variants.length > 3 && (
                  <p className="text-xs text-gray-600">... og {scrapeResult.variants.length - 3} flere</p>
                )}
              </div>
            </div>
          )}

          {/* Variant form */}
          {showVariantForm && (
            <div className="mb-4 rounded-lg border border-slate-300 bg-slate-50 p-4">
              <h4 className="mb-3 font-semibold">
                {editingVariantIndex !== null ? "Rediger variant" : "Ny variant"}
              </h4>
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <label className="mb-1 block text-sm font-medium">Navn *</label>
                  <input
                    type="text"
                    value={variantForm.name}
                    onChange={(e) => setVariantForm({ ...variantForm, name: e.target.value })}
                    placeholder="f.eks. Rød - 2m, Large - Blå"
                    className="w-full rounded-lg border border-slate-300 p-2"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium">Pris (NOK)</label>
                  <input
                    type="number"
                    value={variantForm.price}
                    onChange={(e) => setVariantForm({ ...variantForm, price: toNumber(e.target.value) })}
                    className="w-full rounded-lg border border-slate-300 p-2"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium">Før-pris (NOK)</label>
                  <input
                    type="number"
                    value={variantForm.compareAtPrice || ""}
                    onChange={(e) =>
                      setVariantForm({
                        ...variantForm,
                        compareAtPrice: e.target.value === "" ? undefined : toNumber(e.target.value),
                      })
                    }
                    className="w-full rounded-lg border border-slate-300 p-2"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium">Lager</label>
                  <input
                    type="number"
                    value={variantForm.stock}
                    onChange={(e) => setVariantForm({ ...variantForm, stock: Math.trunc(toNumber(e.target.value)) })}
                    className="w-full rounded-lg border border-slate-300 p-2"
                  />
                </div>
                <div className="md:col-span-2">
                  <label className="mb-1 block text-sm font-medium">Bilde URL (valgfritt)</label>
                  <input
                    type="url"
                    value={variantForm.image || ""}
                    onChange={(e) => setVariantForm({ ...variantForm, image: e.target.value })}
                    placeholder="https://example.com/bilde.jpg"
                    className="w-full rounded-lg border border-slate-300 p-2"
                  />
                </div>
              </div>
              <div className="mt-4 flex gap-2">
                <button
                  type="button"
                  onClick={handleAddVariant}
                  className="rounded-lg bg-brand px-4 py-2 text-sm font-medium text-white hover:bg-brand-dark"
                >
                  {editingVariantIndex !== null ? "Oppdater" : "Legg til"}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setShowVariantForm(false);
                    setEditingVariantIndex(null);
                  }}
                  className="rounded-lg border border-slate-300 px-4 py-2 text-sm hover:bg-slate-50"
                >
                  Avbryt
                </button>
              </div>
            </div>
          )}

          {/* Eksisterende varianter */}
          {variants.length > 0 ? (
            <div className="space-y-2">
              {variants.map((variant, index) => (
                <div
                  key={index}
                  className="flex items-center justify-between rounded-lg border border-slate-300 bg-white p-3"
                >
                  <div className="flex-1">
                    <div className="flex items-center gap-3">
                      {variant.image && (
                        <div className="relative h-12 w-12 overflow-hidden rounded border">
                          <Image
                            src={variant.image}
                            alt={variant.name}
                            fill
                            className="object-cover"
                            unoptimized
                            onError={(e) => {
                              const target = e.target as HTMLImageElement;
                              target.src = "https://placehold.co/48x48?text=Ingen";
                            }}
                          />
                        </div>
                      )}
                      <div>
                        <p className="font-medium">{variant.name}</p>
                        <p className="text-sm text-gray-600">
                          {variant.price.toFixed(0)} kr
                          {variant.compareAtPrice && variant.compareAtPrice > variant.price && (
                            <span className="ml-2 line-through text-gray-400">
                              {variant.compareAtPrice.toFixed(0)} kr
                            </span>
                          )}
                          {" · "}
                          Lager: {variant.stock}
                          {Object.keys(variant.attributes).length > 0 && (
                            <span className="ml-2 text-xs text-gray-500">
                              ({Object.entries(variant.attributes).map(([k, v]) => `${k}: ${v}`).join(", ")})
                            </span>
                          )}
                        </p>
                      </div>
                    </div>
                  </div>
                  <div className="flex gap-2">
                    <button
                      type="button"
                      onClick={() => handleEditVariant(index)}
                      className="rounded-lg border border-slate-300 px-3 py-1.5 text-sm hover:bg-slate-50"
                    >
                      Rediger
                    </button>
                    <button
                      type="button"
                      onClick={() => handleDeleteVariant(index)}
                      className="rounded-lg border border-red-300 bg-red-50 px-3 py-1.5 text-sm text-red-600 hover:bg-red-100"
                    >
                      <Trash2 size={16} />
                    </button>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <p className="text-sm text-gray-500">Ingen varianter lagt til ennå. Klikk på "Legg til variant" for å legge til.</p>
          )}
        </div>

        <div className="mt-6 flex gap-3">
          <button
            onClick={handleSave}
            disabled={saving}
            className="flex items-center gap-2 rounded-lg bg-orange-500 px-6 py-3 text-white transition hover:bg-orange-600 disabled:opacity-50"
          >
            {saving ? (
              <>
                <Loader2 className="animate-spin" size={20} />
                Lagrer...
              </>
            ) : (
              <>
                <Save size={20} />
                Lagre endringer
              </>
            )}
          </button>
          <Link
            href="/admin/products"
            className="rounded-lg border border-slate-300 px-6 py-3 hover:bg-slate-50"
          >
            Avbryt
          </Link>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useMemo, useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Download, Loader2, Check, AlertCircle, Save } from "lucide-react";
import toast from "react-hot-toast";
import { isValidTemuUrl, isValidAlibabaUrl } from "@/lib/utils/url-validation";

type Supplier = "Alibaba" | "eBay" | "Temu" | null;
type Provider = "temu" | "alibaba" | null;

interface ImportedProductPayload {
  name?: string;
  price?: number;
  suggestedPrice?: number;
  compareAtPrice?: number;
  description?: string;
  shortDescription?: string;
  category?: string;
  images?: string[];
  tags?: string[];
}

const DEFAULT_FORM = {
  name: "",
  price: 0,
  compareAtPrice: 0,
  description: "",
  shortDescription: "",
  category: "Elektronikk",
  images: "[]",
  tags: "[]",
  supplierPrice: 0,
};

export default function ImportClient() {
  const router = useRouter();
  const [url, setUrl] = useState("");
  const [provider, setProvider] = useState<Provider>(null);
  const [loading, setLoading] = useState(false);
  const [importing, setImporting] = useState(false);
  const [error, setError] = useState("");
  const [productData, setProductData] = useState<ImportedProductPayload | null>(null);
  const [formData, setFormData] = useState(DEFAULT_FORM);

  const detectSupplier = (value: string): Supplier => {
    if (!value) return null;
    const normalized = value.toLowerCase();
    if (normalized.includes("alibaba.com")) return "Alibaba";
    if (normalized.includes("ebay.com") || normalized.includes("ebay.no")) return "eBay";
    if (normalized.includes("temu.com")) return "Temu";
    return null;
  };

  const supplierToEnum = (supplier: Supplier): "alibaba" | "ebay" | "temu" | null => {
    if (!supplier) return null;
    const normalized = supplier.toLowerCase();
    if (normalized === "alibaba") return "alibaba";
    if (normalized === "ebay") return "ebay";
    if (normalized === "temu") return "temu";
    return null;
  };

  const supplier = useMemo(() => detectSupplier(url), [url]);
  
  // Auto-detect provider from URL
  const detectedProvider = useMemo<Provider>(() => {
    if (!url) return null;
    if (isValidTemuUrl(url)) return "temu";
    if (isValidAlibabaUrl(url)) return "alibaba";
    return null;
  }, [url]);

  // Update provider when URL changes (if not manually set)
  useEffect(() => {
    if (detectedProvider && !provider) {
      setProvider(detectedProvider);
    }
  }, [detectedProvider, provider]);

  const isValidUrl = useMemo(() => {
    if (!url) return false;
    return isValidTemuUrl(url) || isValidAlibabaUrl(url);
  }, [url]);

  const profit = useMemo(() => {
    const diff = formData.price - formData.supplierPrice;
    if (!Number.isFinite(diff) || formData.supplierPrice === 0) {
      return { amount: 0, percentage: 0 };
    }
    return {
      amount: diff,
      percentage: (diff / formData.supplierPrice) * 100,
    };
  }, [formData.price, formData.supplierPrice]);

  const handleImport = async () => {
    setLoading(true);
    setError("");

    if (!url || !supplier) {
      setError("Ugyldig URL. Bruk Alibaba, eBay eller Temu.");
      setLoading(false);
      return;
    }

    try {
      console.log(`[Import] Scraping produkt fra ${supplier}: ${url}`);
      
      const response = await fetch("/api/admin/scrape-product", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ url }), // Supplier hentes automatisk fra URL
      });

      const data = await response.json();
      
      if (!response.ok) {
        const errorMsg = data.error || "Feil ved scraping";
        const hintMsg = data.hint || "";
        throw new Error(hintMsg ? `${errorMsg}\n\n${hintMsg}` : errorMsg);
      }

      console.log("[Import] Produkt scrapet:", data);

      setProductData(data);
      setFormData({
        name: data.name ?? "",
        price: data.suggestedPrice ?? 0,
        compareAtPrice: data.compareAtPrice ?? 0,
        description: data.description ?? "",
        shortDescription: data.shortDescription ?? "",
        category: data.category ?? "Elektronikk",
        images: JSON.stringify(data.images ?? []),
        tags: JSON.stringify(data.tags ?? []),
        supplierPrice: data.price ?? 0,
      });
    } catch (err) {
      console.error("[Import] Feil:", err);
      setError(err instanceof Error ? err.message : "Feil ved scraping");
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    setLoading(true);
    setError("");

    try {
      const supplierEnum = supplierToEnum(supplier);
      const response = await fetch("/api/admin/products", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          ...formData,
          supplierUrl: url,
          supplierName: supplierEnum,
          slug: formData.name.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, ""),
        }),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || "Feil ved lagring");
      }

      router.push("/admin/products");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Feil ved lagring");
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setUrl("");
    setProvider(null);
    setProductData(null);
    setFormData(DEFAULT_FORM);
    setError("");
  };

  // Direct import: fetch and save in one step
  const handleDirectImport = async () => {
    if (!url || !isValidUrl) {
      toast.error("Vennligst oppgi en gyldig Temu eller Alibaba URL");
      return;
    }

    setImporting(true);
    setError("");

    try {
      // Use bulk-import endpoint for single product
      const response = await fetch("/api/admin/products/bulk-import", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          urls: [url],
          provider: provider || undefined, // Auto-detect if not set
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        const errorMsg = data.error || "Feil ved import";
        toast.error(errorMsg);
        setError(errorMsg);
        return;
      }

      const results = data.results || [];
      if (results.length === 0) {
        toast.error("Ingen resultat fra import");
        return;
      }

      const result = results[0];

      if (result.status === "error") {
        toast.error(result.message || "Feil ved import av produkt");
        setError(result.message);
        return;
      }

      if (result.status === "warning") {
        toast.success(`Produkt importert med advarsler: ${result.message}`, {
          duration: 4000,
        });
        if (result.warnings && result.warnings.length > 0) {
          console.warn("Import warnings:", result.warnings);
        }
      } else {
        toast.success(result.message || "Produkt importert!");
      }

      // Redirect to product edit page or products list
      if (result.createdProductId) {
        // Redirect to the product edit page if we have the ID
        setTimeout(() => {
          router.push(`/admin/products/edit/${result.createdProductId}`);
        }, 1500);
      } else {
        // Fallback to products list
        setTimeout(() => {
          router.push("/admin/products");
        }, 1500);
      }
    } catch (err) {
      const errorMsg = err instanceof Error ? err.message : "Ukjent feil ved import";
      toast.error(errorMsg);
      setError(errorMsg);
      console.error("[Direct Import] Error:", err);
    } finally {
      setImporting(false);
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold">Importer Produkt</h1>
      </div>

      <div className="rounded-xl bg-white p-6 shadow-sm">
        <div className="mb-6">
          <label className="mb-2 block text-sm font-medium">Produkt URL (Temu/Alibaba)</label>
          
          {/* Provider dropdown (optional, auto-detected if not set) */}
          <div className="mb-3">
            <label className="mb-1 block text-xs text-gray-600">Kilde (valgfritt, autodetekteres)</label>
            <select
              value={provider || ""}
              onChange={(e) => setProvider(e.target.value as Provider || null)}
              className="w-full max-w-xs rounded-lg border border-slate-300 bg-white p-2 text-sm"
            >
              <option value="">Autodetekter fra URL</option>
              <option value="temu">Temu</option>
              <option value="alibaba">Alibaba</option>
            </select>
          </div>

          <div className="flex gap-2 max-sm:flex-col">
            <input
              type="url"
              value={url}
              onChange={(e) => setUrl(e.target.value)}
              placeholder="https://www.temu.com/... eller https://www.alibaba.com/product-detail/..."
              className="flex-1 rounded-lg border border-border p-3 focus:border-primary focus:outline-none"
            />
            <button
              onClick={handleDirectImport}
              disabled={!isValidUrl || importing}
              className="flex items-center justify-center gap-2 rounded-lg bg-green-600 px-6 py-3 font-medium text-white transition hover:bg-green-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {importing ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  Importerer...
                </>
              ) : (
                <>
                  <Save size={20} />
                  Importer produkt
                </>
              )}
            </button>
          </div>
          
          {url && !isValidUrl && (
            <div className="mt-2 flex items-center gap-2 text-amber-600">
              <AlertCircle size={16} />
              <span className="text-sm">URL må være fra Temu eller Alibaba</span>
            </div>
          )}
          
          {error && (
            <div className="mt-2 flex items-center gap-2 text-red-600">
              <AlertCircle size={16} />
              <span className="text-sm">{error}</span>
            </div>
          )}
        </div>

        {/* Legacy: Import and edit flow (keep existing functionality) */}
        <div className="mb-6 border-t pt-6">
          <p className="mb-3 text-sm text-gray-600">
            Eller importer først for å redigere før lagring:
          </p>
          <div className="flex gap-2 max-sm:flex-col">
            <button
              onClick={handleImport}
              disabled={!url || loading || !supplier}
              className="flex items-center justify-center gap-2 rounded-lg bg-primary px-6 py-3 text-white transition hover:bg-primary-dark disabled:opacity-50"
            >
              {loading ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  Henter data...
                </>
              ) : (
                <>
                  <Download size={20} />
                  Hent produktdata
                </>
              )}
            </button>
          </div>
        </div>

        {productData && (
          <div className="space-y-4 border-t pt-6">
            <div className="mb-4 flex items-center gap-2 text-green-600">
              <Check size={20} />
              <span className="font-medium">Produkt hentet fra {supplier}</span>
            </div>

            {/* Vis bilder hvis de finnes */}
            {productData.images && productData.images.length > 0 && (
              <div className="mb-4">
                <label className="mb-2 block text-sm font-medium">Scrapede Bilder ({productData.images.length})</label>
                <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 md:grid-cols-4">
                  {JSON.parse(formData.images || "[]").slice(0, 8).map((img: string, idx: number) => (
                    <div key={idx} className="relative aspect-square overflow-hidden rounded-lg border border-slate-200">
                      <img
                        src={img}
                        alt={`Produktbilde ${idx + 1}`}
                        className="h-full w-full object-cover"
                        onError={(e) => {
                          (e.target as HTMLImageElement).src = "https://placehold.co/300x300?text=Bilde+feilet";
                        }}
                      />
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="mb-1 block text-sm font-medium">Produktnavn (Norsk)</label>
                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  className="w-full rounded-lg border border-slate-300 p-3"
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium">Kategori</label>
                <select
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  className="w-full rounded-lg border border-slate-300 p-3"
                >
                  <option>Elektronikk</option>
                  <option>Klær</option>
                  <option>Hjem</option>
                  <option>Sport</option>
                </select>
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium">Leverandørpris (NOK)</label>
                <input
                  type="number"
                  value={formData.supplierPrice}
                  onChange={(e) => setFormData({ ...formData, supplierPrice: parseFloat(e.target.value) || 0 })}
                  className="w-full cursor-not-allowed rounded-lg border border-slate-300 bg-slate-100 p-3"
                  readOnly
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium">Din Salgspris (NOK)</label>
                <input
                  type="number"
                  value={formData.price}
                  onChange={(e) => setFormData({ ...formData, price: parseFloat(e.target.value) || 0 })}
                  className="w-full rounded-lg border border-slate-300 p-3"
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium">Før-pris (NOK)</label>
                <input
                  type="number"
                  value={formData.compareAtPrice}
                  onChange={(e) =>
                    setFormData({ ...formData, compareAtPrice: parseFloat(e.target.value) || 0 })
                  }
                  className="w-full rounded-lg border border-slate-300 p-3"
                />
              </div>

              <div>
                <label className="mb-1 block text-sm font-medium">Fortjeneste</label>
                <div className="rounded-lg border border-primary bg-primary/10 p-3 font-medium text-primary">
                  {profit.amount.toFixed(0)} kr ({profit.percentage.toFixed(0)}%)
                </div>
              </div>
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium">Kort Beskrivelse</label>
              <input
                type="text"
                value={formData.shortDescription}
                onChange={(e) => setFormData({ ...formData, shortDescription: e.target.value })}
                className="w-full rounded-lg border border-slate-300 p-3"
                maxLength={150}
              />
            </div>

            <div>
              <label className="mb-1 block text-sm font-medium">Beskrivelse</label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData({ ...formData, description: e.target.value })}
                rows={6}
                className="w-full rounded-lg border border-slate-300 p-3"
              />
            </div>

            <div className="flex flex-col gap-3 md:flex-row">
              <button
                onClick={handleSave}
                disabled={loading}
                className="flex-1 rounded-lg bg-primary py-3 text-white hover:bg-primary-dark disabled:opacity-50"
              >
                {loading ? "Lagrer..." : "Lagre Produkt"}
              </button>
              <button
                onClick={resetForm}
                className="rounded-lg border border-slate-300 px-6 py-3 hover:bg-slate-50"
              >
                Avbryt
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState, useEffect, useCallback } from "react";
import { Loader2, Upload, Check, X, AlertCircle, ExternalLink, Save, Trash2 } from "lucide-react";
import Link from "next/link";
import {
  isValidTemuUrl,
  isValidAlibabaUrl,
  isAlibabaProductUrl,
  normalizeUrl,
} from "@/lib/utils/url-validation";
import type { ImportEditableField } from "@/lib/import/types";
import { getEditedFieldLabels } from "@/lib/import/field-labels";
import { runQualityCheck } from "@/lib/import/quality-check";
import { BUYER_APPROVED_SCORE, BUYER_REVIEW_MIN_SCORE } from "@/lib/import/buyer-policy";
import toast from "react-hot-toast";
import {
  ProductImportPreview,
  type ProductImportData,
} from "@/components/admin/import/ProductImportPreview";

type ImportStage = "scraping" | "generating" | "pricing" | "seo" | "done";

const IMPORT_STAGE_LABELS: Record<ImportStage, string> = {
  scraping: "Skraper produktdata...",
  generating: "Genererer innhold med AI...",
  pricing: "Beregner priser...",
  seo: "Optimaliserer SEO...",
  done: "Fullført",
};

/** Client-side stage progression while the pipeline request runs. */
const IMPORT_STAGE_TIMINGS: Array<{ stage: ImportStage; afterMs: number }> = [
  { stage: "generating", afterMs: 4000 },
  { stage: "pricing", afterMs: 9000 },
  { stage: "seo", afterMs: 11000 },
];

interface ProductPreview {
  url: string;
  status: "pending" | "loading" | "success" | "error";
  stage?: ImportStage;
  data?: ProductImportData;
  editedFields?: Partial<Record<ImportEditableField, boolean>>;
  error?: string;
}

type Provider = "temu" | "alibaba";

const STORAGE_KEY_PREFIX = "bulk-import-urls";

function getStorageKey(provider: Provider): string {
  return `${STORAGE_KEY_PREFIX}-${provider}`;
}

function loadUrlsFromStorage(provider: Provider): string {
  if (typeof window === "undefined") return "";

  try {
    const stored = localStorage.getItem(getStorageKey(provider));
    return stored || "";
  } catch (error) {
    console.warn("[Bulk Import] Failed to load URLs from storage:", error);
    return "";
  }
}

function saveUrlsToStorage(provider: Provider, urls: string): void {
  if (typeof window === "undefined") return;

  try {
    localStorage.setItem(getStorageKey(provider), urls);
  } catch (error) {
    console.warn("[Bulk Import] Failed to save URLs to storage:", error);
  }
}

function mapPipelineToImportData(pipeline: Record<string, unknown>): ProductImportData {
  return {
    name: String(pipeline.name || ""),
    originalName: String(pipeline.originalTitle || ""),
    description: String(pipeline.description || ""),
    originalDescription: String(pipeline.originalDescription || ""),
    price: Number(pipeline.originalPrice || 0),
    originalPrice: Number(pipeline.originalPrice || 0),
    suggestedPrice: Number(pipeline.suggestedPrice || 0),
    compareAtPrice: Number(pipeline.compareAtPrice || 0),
    shortDescription: String(pipeline.shortDescription || ""),
    images: Array.isArray(pipeline.images) ? (pipeline.images as string[]) : [],
    variants: Array.isArray(pipeline.variants)
      ? (pipeline.variants as ProductImportData["variants"])
      : undefined,
    category: String(pipeline.category || "Hjem & Fritid"),
    subcategory: typeof pipeline.subcategory === "string" ? pipeline.subcategory : null,
    tags: Array.isArray(pipeline.tags) ? (pipeline.tags as string[]) : [],
    slug: String(pipeline.slug || ""),
    metaTitle: String(pipeline.metaTitle || ""),
    metaDescription: String(pipeline.metaDescription || ""),
    deliveryTime: String(pipeline.deliveryTime || "5–12 virkedager"),
    specs: (pipeline.specs as Record<string, string>) || {},
    supplier: String(pipeline.supplier || "temu"),
    aiGenerated: Boolean(pipeline.aiGenerated),
    aiWarning: pipeline.aiWarning ? String(pipeline.aiWarning) : undefined,
    highlightedFeatures: Array.isArray(pipeline.highlightedFeatures)
      ? (pipeline.highlightedFeatures as string[])
      : undefined,
  };
}

export default function TemuImportClient() {
  const [mounted, setMounted] = useState(false);
  const [provider, setProvider] = useState<Provider>("temu");
  const [urls, setUrls] = useState("");
  const [products, setProducts] = useState<ProductPreview[]>([]);
  const [importing, setImporting] = useState(false);
  const [saving, setSaving] = useState(false);
  const [improvingIndex, setImprovingIndex] = useState<number | null>(null);
  const [isLoadingFromStorage, setIsLoadingFromStorage] = useState(false);

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!mounted) return;

    setIsLoadingFromStorage(true);
    const storedUrls = loadUrlsFromStorage(provider);
    setUrls(storedUrls);
    setProducts([]);
    setTimeout(() => setIsLoadingFromStorage(false), 100);
  }, [provider, mounted]);

  useEffect(() => {
    if (isLoadingFromStorage) return;
    if (!urls.trim()) return;

    const timeoutId = setTimeout(() => {
      saveUrlsToStorage(provider, urls);
    }, 500);

    return () => clearTimeout(timeoutId);
  }, [urls, provider, isLoadingFromStorage]);

  const validateUrl = (url: string, currentProvider: Provider): boolean => {
    if (currentProvider === "temu") {
      return isValidTemuUrl(url);
    }
    if (currentProvider === "alibaba") {
      return isValidAlibabaUrl(url);
    }
    return false;
  };

  const handleLoadUrls = () => {
    setIsLoadingFromStorage(true);
    const storedUrls = loadUrlsFromStorage(provider);
    if (!storedUrls.trim()) {
      const providerName = provider === "temu" ? "Temu" : "Alibaba";
      alert(`Ingen lagrede ${providerName}-URLs funnet.`);
      setIsLoadingFromStorage(false);
      return;
    }
    setUrls(storedUrls);
    setTimeout(() => setIsLoadingFromStorage(false), 100);
  };

  const handleParse = () => {
    const urlList = urls
      .split("\n")
      .map((url) => url.trim())
      .filter((url) => {
        if (url.length === 0) return false;
        if (!url.startsWith("http://") && !url.startsWith("https://")) return false;
        return validateUrl(url, provider);
      });

    if (provider === "alibaba") {
      const invalidUrls = urlList.filter((url) => !isAlibabaProductUrl(url));
      if (invalidUrls.length > 0 && urlList.length > 0) {
        console.warn(
          "Noen URLs ser ikke ut som produkt-URLs (mangler /product-detail/). Fortsetter likevel..."
        );
      }
    }

    const normalizedUrlList = urlList.map((url) => normalizeUrl(url));

    if (urlList.length === 0) {
      const providerName = provider === "temu" ? "Temu" : "Alibaba";
      alert(`Ingen gyldige ${providerName}-URLs funnet!`);
      return;
    }

    setProducts(
      normalizedUrlList.map((url) => ({
        url,
        status: "pending",
        editedFields: {},
      }))
    );

    saveUrlsToStorage(provider, normalizedUrlList.join("\n"));
  };

  const setProductStage = useCallback((index: number, stage: ImportStage) => {
    setProducts((prev) =>
      prev.map((p, idx) => (idx === index && p.status === "loading" ? { ...p, stage } : p))
    );
  }, []);

  const handleImportAll = async () => {
    setImporting(true);

    for (let i = 0; i < products.length; i++) {
      const product = products[i];

      if (product.status === "success" || product.status === "loading") {
        continue;
      }

      setProducts((prev) =>
        prev.map((p, idx) =>
          idx === i ? { ...p, status: "loading", stage: "scraping" } : p
        )
      );

      // Advance the visible stage while the single pipeline request runs
      const stageTimers = IMPORT_STAGE_TIMINGS.map(({ stage, afterMs }) =>
        setTimeout(() => setProductStage(i, stage), afterMs)
      );

      try {
        const response = await fetch("/api/admin/import/pipeline", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ url: product.url, provider }),
        });

        if (!response.ok) {
          const errorData = await response.json();
          throw new Error(errorData.error || "Feil ved import");
        }

        const pipelineData = await response.json();
        const formattedData = mapPipelineToImportData(pipelineData);

        setProducts((prev) =>
          prev.map((p, idx) =>
            idx === i
              ? {
                  ...p,
                  status: "success",
                  stage: "done",
                  data: formattedData,
                  editedFields: {},
                }
              : p
          )
        );

        if (i < products.length - 1) {
          await new Promise((resolve) => setTimeout(resolve, 3000));
        }
      } catch (error: unknown) {
        const message = error instanceof Error ? error.message : "Ukjent feil";
        setProducts((prev) =>
          prev.map((p, idx) =>
            idx === i ? { ...p, status: "error", stage: undefined, error: message } : p
          )
        );
      } finally {
        stageTimers.forEach(clearTimeout);
      }
    }

    setImporting(false);
  };

  const updateProductField = useCallback(
    (index: number, field: ImportEditableField, value: string | number | string[] | null) => {
      setProducts((prev) =>
        prev.map((product, idx) => {
          if (idx !== index || !product.data) return product;

          const nextData = { ...product.data };
          const nextEdited = { ...(product.editedFields || {}) };

          switch (field) {
            case "name":
              nextData.name = String(value);
              break;
            case "description":
              nextData.description = String(value);
              break;
            case "shortDescription":
              nextData.shortDescription = String(value);
              break;
            case "suggestedPrice":
              nextData.suggestedPrice = Number(value) || 0;
              break;
            case "compareAtPrice":
              nextData.compareAtPrice = value === null ? 0 : Number(value) || 0;
              break;
            case "category":
              nextData.category = String(value);
              break;
            case "tags":
              nextData.tags = Array.isArray(value) ? value : [];
              break;
            case "slug":
              nextData.slug = String(value);
              break;
            case "metaTitle":
              nextData.metaTitle = String(value);
              break;
            case "metaDescription":
              nextData.metaDescription = String(value);
              break;
            default:
              return product;
          }

          nextEdited[field] = true;

          return {
            ...product,
            data: nextData,
            editedFields: nextEdited,
          };
        })
      );
    },
    []
  );

  const updateProductImages = useCallback((index: number, images: string[]) => {
    setProducts((prev) =>
      prev.map((product, idx) =>
        idx === index && product.data
          ? { ...product, data: { ...product.data, images } }
          : product
      )
    );
  }, []);

  const updateProductSubcategory = useCallback((index: number, subcategory: string | null) => {
    setProducts((prev) =>
      prev.map((product, idx) =>
        idx === index && product.data
          ? { ...product, data: { ...product.data, subcategory } }
          : product
      )
    );
  }, []);

  const handleImproveWithAI = useCallback(
    async (index: number, forceOverwrite: boolean) => {
      const product = products[index];
      if (!product?.data) return;

      const editedFields = product.editedFields || {};
      const editedKeys = (
        Object.entries(editedFields) as [ImportEditableField, boolean][]
      )
        .filter(([, edited]) => edited)
        .map(([field]) => field);

      if (forceOverwrite && editedKeys.length > 0) {
        const labels = getEditedFieldLabels(editedFields).join(", ");
        if (
          !confirm(
            `Dette erstatter alle manuelle endringer (${labels}).\n\nEr du sikker på at du vil overskrive?`
          )
        ) {
          return;
        }
      } else if (!forceOverwrite && editedKeys.length > 0) {
        const labels = getEditedFieldLabels(editedFields).join(", ");
        if (
          !confirm(
            `Manuelt redigerte felt beholdes: ${labels}.\n\nVil du forbedre øvrige felt med AI?`
          )
        ) {
          return;
        }
      }

      setImprovingIndex(index);

      try {
        const response = await fetch("/api/admin/import/improve", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            product: product.data,
            preserveFields: forceOverwrite ? [] : editedKeys,
          }),
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          throw new Error(errorData.error || "AI-forbedring feilet");
        }

        const result = await response.json();
        const updates = result.updates || {};

        setProducts((prev) =>
          prev.map((item, idx) => {
            if (idx !== index || !item.data) return item;

            const nextData = { ...item.data };
            const nextEdited: Partial<Record<ImportEditableField, boolean>> = forceOverwrite
              ? {}
              : { ...(item.editedFields || {}) };

            if (updates.name !== undefined) {
              nextData.name = updates.name;
              delete nextEdited.name;
            }
            if (updates.description !== undefined) {
              nextData.description = updates.description;
              delete nextEdited.description;
            }
            if (updates.shortDescription !== undefined) {
              nextData.shortDescription = updates.shortDescription;
              delete nextEdited.shortDescription;
            }
            if (updates.category !== undefined) {
              nextData.category = updates.category;
              delete nextEdited.category;
            }
            if (updates.tags !== undefined) {
              nextData.tags = updates.tags;
              delete nextEdited.tags;
            }
            if (updates.slug !== undefined) {
              nextData.slug = updates.slug;
              delete nextEdited.slug;
            }
            if (updates.metaTitle !== undefined) {
              nextData.metaTitle = updates.metaTitle;
              delete nextEdited.metaTitle;
            }
            if (updates.metaDescription !== undefined) {
              nextData.metaDescription = updates.metaDescription;
              delete nextEdited.metaDescription;
            }
            if (updates.suggestedPrice !== undefined) {
              nextData.suggestedPrice = updates.suggestedPrice;
              delete nextEdited.suggestedPrice;
            }
            if (updates.compareAtPrice !== undefined) {
              nextData.compareAtPrice = updates.compareAtPrice;
              delete nextEdited.compareAtPrice;
            }
            if (updates.highlightedFeatures !== undefined) {
              nextData.highlightedFeatures = updates.highlightedFeatures;
            }

            nextData.aiGenerated = result.aiGenerated ?? true;
            nextData.aiWarning = result.warning;

            return {
              ...item,
              data: nextData,
              editedFields: nextEdited,
            };
          })
        );
      } catch (error) {
        const message = error instanceof Error ? error.message : "Ukjent feil";
        alert(`Kunne ikke forbedre produkt: ${message}`);
      } finally {
        setImprovingIndex(null);
      }
    },
    [products]
  );

  const extractSupplierId = (url: string, currentProvider: Provider) => {
    if (currentProvider === "temu") {
      const match = url.match(/goods\.html\?goods_id=(\d+)/);
      return match ? match[1] : url.split("/").pop()?.split("?")[0] || "";
    }
    if (currentProvider === "alibaba") {
      const match = url.match(/product-detail\/(\d+)/);
      return match ? match[1] : url.split("/").pop()?.split(".")[0] || "";
    }
    return "";
  };

  const handleSaveAll = async () => {
    const successfulProducts = products.filter((p) => p.status === "success" && p.data);

    if (successfulProducts.length === 0) {
      alert("Ingen produkter å lagre!");
      return;
    }

    // Buyer decision levels: REJECTED hard-blocks; REVIEW needs confirmation; APPROVED passes
    const qualityIssues: string[] = [];
    const blockedProducts: string[] = [];
    const reviewProducts: string[] = [];
    for (const product of successfulProducts) {
      const data = product.data!;
      const result = runQualityCheck({
        name: data.name,
        description: data.description,
        originalTitle: data.originalName,
        images: data.images,
        suggestedPrice: data.suggestedPrice,
        costNOK: data.originalPrice,
        category: data.category,
        subcategory: data.subcategory,
        slug: data.slug,
        metaTitle: data.metaTitle,
        metaDescription: data.metaDescription,
        tags: data.tags,
        specs: data.specs,
        variantsCount: data.variants?.length ?? 0,
      });

      if (result.buyerDecision === "rejected" || !result.canImport) {
        const failed = result.checks
          .filter((check) => !check.ok && check.blocking)
          .map((check) => `${check.label}: ${check.detail ?? "feilet"}`)
          .join("; ");
        blockedProducts.push(
          `"${data.name || product.url}" (${result.overallScore.toFixed(1)}/10 · REJECTED) — ${failed || "avvist av kjøpspolicy"}`
        );
        continue;
      }

      if (result.buyerDecision === "review") {
        reviewProducts.push(
          `"${data.name || product.url}" (${result.overallScore.toFixed(1)}/10 · REVIEW)`
        );
      }

      if (!result.passed) {
        const failed = result.checks
          .filter((check) => !check.ok)
          .map((check) => check.label)
          .join(", ");
        qualityIssues.push(`"${data.name || product.url}": ${failed}`);
      }
    }

    if (blockedProducts.length > 0) {
      toast.error(
        `${blockedProducts.length} produkt(er) REJECTED (score under ${BUYER_REVIEW_MIN_SCORE} eller absolute butikkregler).`,
        { duration: 6000 }
      );
      alert(
        `Import blokkert for REJECTED-produkter:\n\n${blockedProducts.join(
          "\n\n"
        )}\n\nAbsolute regler (klær, voksen, kopi/varemerke, medisin, kosttilskudd, sikkerhetskritiske barneprodukter) og score under ${BUYER_REVIEW_MIN_SCORE} kan ikke importeres.\n\nREVIEW (${BUYER_REVIEW_MIN_SCORE}–${BUYER_APPROVED_SCORE}) kan fortsatt vurderes manuelt.`
      );
      return;
    }

    if (reviewProducts.length > 0) {
      const proceedReview = confirm(
        `${reviewProducts.length} produkt(er) er i REVIEW-sonen (score ${BUYER_REVIEW_MIN_SCORE}–${BUYER_APPROVED_SCORE} eller andre advarsler):\n\n${reviewProducts.join(
          "\n"
        )}\n\nPolicyen anbefaler forsiktighet, men du kan importere hvis du mener produktet passer.\n\nVil du fortsette?`
      );
      if (!proceedReview) return;
    }

    if (qualityIssues.length > 0) {
      const proceed = confirm(
        `Kvalitetssjekken fant mangler ved ${qualityIssues.length} produkt(er):\n\n${qualityIssues.join(
          "\n"
        )}\n\nVil du lagre likevel?`
      );
      if (!proceed) return;
    }

    if (!confirm(`Er du sikker på at du vil lagre ${successfulProducts.length} produkter?`)) {
      return;
    }

    setSaving(true);

    let savedCount = 0;
    let errorCount = 0;

    for (const product of successfulProducts) {
      try {
        const data = product.data!;

        // Persist specs, including the detected subcategory
        const specsToSave: Record<string, string> = {
          ...data.specs,
          ...(data.subcategory ? { Underkategori: data.subcategory } : {}),
        };

        // Include the subcategory as a searchable tag
        const tagsToSave = data.subcategory
          ? Array.from(new Set([...data.tags, data.subcategory.toLowerCase()]))
          : data.tags;

        const response = await fetch("/api/admin/products", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            name: data.name,
            slug: data.slug,
            description: data.description,
            shortDescription: data.shortDescription,
            price: Math.round(data.suggestedPrice),
            compareAtPrice: data.compareAtPrice ? Math.round(data.compareAtPrice) : null,
            supplierPrice: Math.round(data.originalPrice),
            images: JSON.stringify(data.images),
            tags: JSON.stringify(tagsToSave),
            category: data.category,
            metaTitle: data.metaTitle,
            metaDescription: data.metaDescription,
            specs: specsToSave,
            supplierUrl: product.url,
            supplierName: data.supplier || provider,
            supplierProductId: extractSupplierId(product.url, provider),
            sku: `${provider.toUpperCase()}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            skipTitleImprovement: true,
            isActive: true,
          }),
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          throw new Error(errorData.error || "Feil ved lagring");
        }

        const savedProduct = await response.json();
        const productId = savedProduct.id;

        const variantsToSave =
          data.variants && data.variants.length > 0
            ? data.variants
            : [
                {
                  name: "Standard",
                  price: Math.round(data.suggestedPrice),
                  compareAtPrice: data.compareAtPrice ? Math.round(data.compareAtPrice) : null,
                  image: data.images[0] || null,
                  attributes: {},
                  stock: null as number | null,
                  sku: null as string | null,
                },
              ];

        // Save variants individually so one failing variant doesn't
        // block the whole product
        let variantErrors = 0;
        for (const variant of variantsToSave) {
          try {
            const variantResponse = await fetch(`/api/admin/products/${productId}/variants`, {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({
                name: variant.name || "Standard",
                price: Math.round(variant.price || data.suggestedPrice),
                compareAtPrice: variant.compareAtPrice
                  ? Math.round(variant.compareAtPrice)
                  : null,
                supplierPrice: Math.round(data.originalPrice),
                image: variant.image || data.images[0] || null,
                attributes: variant.attributes || {},
                // Only send supplier stock when it exists; API defaults otherwise
                ...(typeof variant.stock === "number" ? { stock: variant.stock } : {}),
                ...(variant.sku ? { sku: variant.sku } : {}),
                isActive: true,
              }),
            });

            if (!variantResponse.ok) {
              const errorText = await variantResponse.text();
              console.warn(
                `[Import] Variant "${variant.name}" feilet:`,
                errorText || variantResponse.status
              );
              variantErrors++;
            }
          } catch (variantError) {
            console.warn(`[Import] Variant "${variant.name}" feilet:`, variantError);
            variantErrors++;
          }
        }

        if (variantErrors === variantsToSave.length) {
          throw new Error("Ingen varianter kunne lagres");
        }

        savedCount++;
      } catch (error) {
        console.error("Error saving product:", error);
        errorCount++;
      }

      await new Promise((resolve) => setTimeout(resolve, 500));
    }

    setSaving(false);

    if (savedCount > 0) {
      alert(
        `✅ ${savedCount} produkter lagret!${errorCount > 0 ? `\n⚠️ ${errorCount} produkter feilet.` : ""}`
      );
      window.location.href = "/admin/products";
    } else {
      alert("❌ Kunne ikke lagre produkter. Sjekk konsollen for feil.");
    }
  };

  const removeProduct = (index: number) => {
    setProducts((prev) => prev.filter((_, idx) => idx !== index));
  };

  const retryProduct = async (index: number) => {
    setProducts((prev) =>
      prev.map((p, idx) =>
        idx === index ? { ...p, status: "pending", error: undefined, editedFields: {} } : p
      )
    );
    await handleImportAll();
  };

  const successCount = products.filter((p) => p.status === "success").length;
  const errorCount = products.filter((p) => p.status === "error").length;
  const loadingCount = products.filter((p) => p.status === "loading").length;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-dark">AI Produktimport</h1>
          <p className="mt-1 text-gray-medium">
            Importer produkter fra Temu eller Alibaba med AI-generert innhold
          </p>
        </div>
        <Link
          href="/admin/products"
          className="rounded-lg border border-gray-border px-4 py-2 text-sm font-medium hover:bg-gray-light"
        >
          ← Tilbake til produkter
        </Link>
      </div>

      <div className="rounded-xl border border-gray-border bg-white p-6 shadow-sm">
        <div className="mb-4">
          <label className="mb-2 block text-sm font-medium text-dark">Kilde</label>
          <select
            value={provider}
            onChange={(e) => {
              const newProvider = e.target.value as Provider;
              saveUrlsToStorage(provider, urls);
              setProvider(newProvider);
            }}
            className="w-full rounded-lg border border-gray-border bg-white px-4 py-2 text-sm focus:border-brand focus:outline-none focus:ring-2 focus:ring-brand/20 sm:w-auto"
          >
            <option value="temu">Temu</option>
            <option value="alibaba">Alibaba</option>
          </select>
        </div>
        <label className="mb-2 block text-sm font-medium text-dark">
          Produkt URLs (én per linje)
        </label>
        <textarea
          value={urls}
          onChange={(e) => setUrls(e.target.value)}
          placeholder={
            provider === "temu"
              ? "https://www.temu.com/goods.html?goods_id=123456789"
              : "https://www.alibaba.com/product-detail/123456789.html"
          }
          rows={8}
          className="w-full rounded-lg border border-gray-border p-3 font-mono text-sm focus:border-brand focus:outline-none focus:ring-2 focus:ring-brand/20"
        />
        <div className="mt-4 flex gap-3">
          <button
            onClick={handleLoadUrls}
            className="flex items-center gap-2 rounded-lg bg-gray-600 px-6 py-3 text-white transition-colors hover:bg-gray-700"
          >
            <Upload size={20} />
            Last URLs
          </button>
          <button
            onClick={handleParse}
            disabled={!mounted || urls.trim().length === 0 || isLoadingFromStorage}
            className="flex items-center gap-2 rounded-lg bg-dark px-6 py-3 text-white transition-colors hover:bg-dark-secondary disabled:cursor-not-allowed disabled:opacity-50"
          >
            <Check size={20} />
            Parse URLs ({mounted ? urls.split("\n").filter((u) => u.trim()).length : 0})
          </button>
          {products.length > 0 && (
            <button
              onClick={handleImportAll}
              disabled={importing || loadingCount > 0}
              className="flex items-center gap-2 rounded-lg bg-brand px-6 py-3 text-white transition-colors hover:bg-brand-dark disabled:cursor-not-allowed disabled:opacity-50"
            >
              {importing ? (
                <>
                  <Loader2 className="animate-spin" size={20} />
                  Importerer...
                </>
              ) : (
                <>
                  <Check size={20} />
                  Importer Alle ({products.length})
                </>
              )}
            </button>
          )}
        </div>
      </div>

      {products.length > 0 && (
        <div className="grid grid-cols-4 gap-4">
          <div className="rounded-lg border border-gray-border bg-white p-4">
            <div className="text-2xl font-bold text-dark">{products.length}</div>
            <div className="text-sm text-gray-medium">Totalt</div>
          </div>
          <div className="rounded-lg border border-green-500 bg-white p-4">
            <div className="text-2xl font-bold text-green-600">{successCount}</div>
            <div className="text-sm text-gray-medium">Ferdig</div>
          </div>
          <div className="rounded-lg border border-yellow-500 bg-white p-4">
            <div className="text-2xl font-bold text-yellow-600">{loadingCount}</div>
            <div className="text-sm text-gray-medium">Laster</div>
          </div>
          <div className="rounded-lg border border-red-500 bg-white p-4">
            <div className="text-2xl font-bold text-red-600">{errorCount}</div>
            <div className="text-sm text-gray-medium">Feil</div>
          </div>
        </div>
      )}

      {products.length > 0 && (
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <h2 className="text-xl font-bold text-dark">
              Produkter ({successCount}/{products.length} ferdig)
            </h2>
            {successCount > 0 && (
              <button
                onClick={handleSaveAll}
                disabled={saving}
                className="flex items-center gap-2 rounded-lg bg-brand px-6 py-3 text-white transition-colors hover:bg-brand-dark disabled:cursor-not-allowed disabled:opacity-50"
              >
                {saving ? (
                  <>
                    <Loader2 className="animate-spin" size={20} />
                    Lagrer...
                  </>
                ) : (
                  <>
                    <Save size={20} />
                    Lagre {successCount} Produkter
                  </>
                )}
              </button>
            )}
          </div>

          {products.map((product, index) => (
            <div
              key={index}
              className="rounded-xl border-l-4 bg-white p-6 shadow-sm"
              style={{
                borderColor:
                  product.status === "success"
                    ? "#00C853"
                    : product.status === "error"
                      ? "#e53935"
                      : product.status === "loading"
                        ? "#FFC107"
                        : "#ccc",
              }}
            >
              <div className="mb-4 flex items-start justify-between">
                <div className="flex-1">
                  <div className="mb-2 flex items-center gap-2">
                    <a
                      href={product.url}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="flex items-center gap-1 text-sm text-brand hover:underline"
                    >
                      <ExternalLink size={14} />
                      URL #{index + 1}
                    </a>
                    <span
                      className={`rounded px-2 py-1 text-xs font-medium ${
                        product.status === "success"
                          ? "bg-green-100 text-green-700"
                          : product.status === "error"
                            ? "bg-red-100 text-red-700"
                            : product.status === "loading"
                              ? "bg-yellow-100 text-yellow-700"
                              : "bg-gray-100 text-gray-700"
                      }`}
                    >
                      {product.status === "success"
                        ? "✓ Ferdig"
                        : product.status === "error"
                          ? "✗ Feil"
                          : product.status === "loading"
                            ? "⏳ Laster..."
                            : "⏸ Vent"}
                    </span>
                  </div>
                  <div className="break-all font-mono text-xs text-gray-medium">{product.url}</div>
                </div>
                <div className="flex gap-2">
                  {product.status === "error" && (
                    <button
                      onClick={() => retryProduct(index)}
                      className="rounded p-2 text-brand hover:bg-brand-light"
                      title="Prøv igjen"
                    >
                      <Check size={18} />
                    </button>
                  )}
                  <button
                    onClick={() => removeProduct(index)}
                    className="rounded p-2 text-red-600 hover:bg-red-50"
                    title="Fjern"
                  >
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>

              {product.status === "loading" && (
                <div className="space-y-2">
                  <div className="flex items-center gap-2 text-gray-medium">
                    <Loader2 className="animate-spin" size={16} />
                    <span className="font-medium text-dark">
                      {IMPORT_STAGE_LABELS[product.stage || "scraping"]}
                    </span>
                  </div>
                  <div className="flex items-center gap-1">
                    {(["scraping", "generating", "pricing", "seo"] as ImportStage[]).map(
                      (stage, stageIdx) => {
                        const stages: ImportStage[] = ["scraping", "generating", "pricing", "seo"];
                        const currentIdx = stages.indexOf(product.stage || "scraping");
                        return (
                          <div
                            key={stage}
                            className={`h-1.5 flex-1 rounded-full transition-colors ${
                              stageIdx < currentIdx
                                ? "bg-brand"
                                : stageIdx === currentIdx
                                  ? "animate-pulse bg-brand/60"
                                  : "bg-gray-200"
                            }`}
                            title={IMPORT_STAGE_LABELS[stage]}
                          />
                        );
                      }
                    )}
                  </div>
                </div>
              )}

              {product.status === "error" && (
                <div className="flex items-center gap-2 rounded bg-red-50 p-3 text-red-600">
                  <AlertCircle size={16} />
                  <span className="text-sm">{product.error}</span>
                </div>
              )}

              {product.status === "success" && product.data && (
                <ProductImportPreview
                  data={product.data}
                  editedFields={product.editedFields || {}}
                  improving={improvingIndex === index}
                  onFieldChange={(field, value) => updateProductField(index, field, value)}
                  onImprove={(forceOverwrite) => handleImproveWithAI(index, forceOverwrite)}
                  onImagesChange={(images) => updateProductImages(index, images)}
                  onSubcategoryChange={(subcategory) =>
                    updateProductSubcategory(index, subcategory)
                  }
                />
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

/**
 * Manual test file for URL storage functionality
 * 
 * To test manually:
 * 1. Open browser console
 * 2. Run the test functions below
 * 3. Verify localStorage keys and values
 */

// Test helper functions
function getStorageKey(provider: 'temu' | 'alibaba'): string {
  return `bulk-import-urls-${provider}`;
}

function loadUrlsFromStorage(provider: 'temu' | 'alibaba'): string {
  if (typeof window === 'undefined') return '';
  
  try {
    const stored = localStorage.getItem(getStorageKey(provider));
    return stored || '';
  } catch (error) {
    console.warn('[Bulk Import] Failed to load URLs from storage:', error);
    return '';
  }
}

function saveUrlsToStorage(provider: 'temu' | 'alibaba', urls: string): void {
  if (typeof window === 'undefined') return;
  
  try {
    localStorage.setItem(getStorageKey(provider), urls);
    console.log(`✅ Saved ${urls.split('\n').filter(u => u.trim()).length} URLs for ${provider}`);
  } catch (error) {
    console.warn('[Bulk Import] Failed to save URLs to storage:', error);
  }
}

