                  : product.status === 'failed'
                  ? 'border-red-500'
                  : product.status === 'checking'
                  ? 'border-blue-500'
                  : 'border-gray-border'
              }`}
            >
              {/* PRODUCT HEADER */}
              <div className="flex items-start justify-between mb-4">
