                    <p className="text-sm text-gray-medium">{product.slug}</p>
                    <div className="flex items-center gap-2 mt-2">
                      {product.status === 'passed' && (
                        <span className="flex items-center gap-1 text-green-600 text-sm">
                          <CheckCircle2 size={16} />
                          Godkjent
                        </span>
                      )}
                      {product.status === 'fixed' && (
                        <span className="flex items-center gap-1 text-green-600 text-sm">
                          <CheckCircle2 size={16} />
                          Fikset
                        </span>
                      )}
                      {product.status === 'failed' && (
                        <span className="flex items-center gap-1 text-red-600 text-sm">
                          <AlertCircle size={16} />
                          {product.issues.length} Problem(er)
                        </span>
                      )}
                      {product.status === 'checking' && (
                        <span className="flex items-center gap-1 text-blue-600 text-sm">
                          <RefreshCw className="animate-spin" size={16} />
                          Sjekker...
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* VARIANTS */}
              {product.variants && product.variants.length > 0 && (
                <div className="space-y-3 mb-4">
                  <h4 className="font-medium text-sm text-dark">
                    Varianter ({product.variants.length})
                  </h4>
                  {product.variants.map((variant, vIdx) => (
                    <div key={vIdx} className="rounded-lg border border-gray-border p-4">
                      <div className="flex items-center gap-2 mb-3">
                        {variant.type === 'color' && <Palette size={16} className="text-gray-medium" />}
                        {variant.type === 'size' && <Settings size={16} className="text-gray-medium" />}
                        <span className="font-medium text-sm capitalize text-dark">
                          {variant.name}
                        </span>
                        <span className="text-xs text-gray-medium">
                          ({variant.options.length} alternativer)
                        </span>
                      </div>

                      <div className="grid grid-cols-6 gap-3">
                        {variant.options.map((option, oIdx) => (
                          <div
                            key={oIdx}
                            className="rounded-lg border border-gray-border p-2 text-center"
                          >
                            {option.image && (
                              <div className="relative h-12 w-12 mx-auto mb-2 overflow-hidden rounded border border-gray-border">
                                <Image
                                  src={option.image}
                                  alt={option.value}
                                  fill
                                  className="object-cover"
                                  sizes="48px"
                                />
                              </div>
                            )}
                            {!option.image && option.colorCode && (
                              <div
                                className="h-8 w-8 mx-auto mb-2 rounded-full border border-gray-border"
                                style={{ backgroundColor: option.colorCode }}
                              />
                            )}
                            {!option.image && !option.colorCode && (
                              <div className="h-8 w-8 mx-auto mb-2 rounded-full border border-gray-border bg-gray-light" />
                            )}
                            <div className="text-xs font-medium text-dark">{option.value}</div>
                            {option.price && (
                              <div className="text-xs text-gray-medium mt-1">
                                +{option.price} kr
                              </div>
                            )}
                          </div>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              )}

              {/* ISSUES */}
              {product.issues && product.issues.length > 0 && (
                <div className="mt-4 space-y-2">
                  <h4 className="font-medium text-sm text-red-600">
                    Problem funnet:
                  </h4>
                  {product.issues.map((issue, iIdx) => (
                    <div
                      key={iIdx}
                      className={`rounded-lg p-3 text-sm ${
                        issue.severity === 'critical'
                          ? 'bg-red-50 text-red-700 border border-red-200'
                          : issue.severity === 'warning'
                          ? 'bg-yellow-50 text-yellow-700 border border-yellow-200'
                          : 'bg-blue-50 text-blue-700 border border-blue-200'
                      }`}
                    >
                      <div className="font-medium">{issue.message}</div>
                      <div className="text-xs mt-1 opacity-75">
                        💡 {issue.suggestion}
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { nanoid } from "nanoid";
import { CartStatus } from "@prisma/client";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { email, items, storeId } = body;

    if (!items) {
      return NextResponse.json({ error: "items is required" }, { status: 400 });
    }

    const token = nanoid(16);

    const cart = await prisma.abandonedCart.create({
      data: {
        email: email || null,
        items,
        storeId: storeId || null,
        token,
        status: CartStatus.ACTIVE,
      },
    });

    return NextResponse.json({ id: cart.id, token: cart.token });
  } catch (error: any) {
    console.error("abandoned-cart capture error", error);
    return NextResponse.json({ error: error.message || "capture failed" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { logError, logInfo } from "@/lib/utils/logger";

/**
 * AI Helper API for Admin
 * 
 * Generates product descriptions, SEO content, and marketing copy using OpenAI.
 * 
 * IMPORTANT: Set OPENAI_API_KEY in Vercel environment variables for this to work.
 * 
 * If OpenAI SDK is not installed, this uses fetch() directly to OpenAI API.
 * To use the official SDK instead, install: npm install openai
 */

interface AIRequest {
  type: "productDescription" | "seo" | "heroCopy" | "categoryCopy" | "emailTemplate";
  payload: {
    // ProductDescription
    name?: string;
    category?: string;
    price?: number;
    tone?: "nøytral" | "entusiastisk" | "teknisk";
    toneOfVoice?: "nøytral" | "entusiastisk" | "teknisk"; // Legacy support
    notes?: string;
    useCase?: string; // Legacy support
    description?: string;
    shortDescription?: string;
    // SEO
    pageType?: "product" | "category" | "frontpage" | "other";
    // CategoryCopy
    categoryName?: string;
    productsHint?: string;
    // HeroCopy
    campaignName?: string;
    focus?: string;
    discountInfo?: string;
    productTypes?: string; // Legacy support
    discount?: number; // Legacy support
    // EmailTemplate
    templateType?: "welcome" | "campaign" | "newsletter";
    audienceDescription?: string;
    offerDescription?: string;
  };
}

export async function POST(req: Request) {
  try {
    // Admin auth check
    const session = await getServerSession(authOptions);
    if (!session || !session.user) {
      return NextResponse.json(
        { ok: false, error: "Ikke autentisert" },
        { status: 401 }
      );
    }

    const body: AIRequest = await req.json();
    const { type, payload } = body;

    const apiKey = process.env.OPENAI_API_KEY;
    if (!apiKey) {
      logError(new Error("OPENAI_API_KEY not set"), "[api/admin/ai]");
      return NextResponse.json(
        {
          ok: false,
          error: "OpenAI API-nøkkel ikke konfigurert. Sett OPENAI_API_KEY i Vercel environment variables.",
        },
        { status: 500 }
      );
    }

    let prompt = "";
    const systemPrompt = "Du er en ekspert på produktbeskrivelser og markedsføring for norske nettbutikker. Skriv alltid på norsk.";

    switch (type) {
      case "productDescription": {
        const { name, category, price, tone = "nøytral", toneOfVoice, notes, useCase } = payload;
        const finalTone = tone || toneOfVoice || "nøytral";
        const extraNotes = notes || useCase || "";
        prompt = `Skriv en profesjonell produktbeskrivelse for følgende produkt:

Navn: ${name || "Ikke spesifisert"}
Kategori: ${category || "Ikke spesifisert"}
Pris: ${price ? `${price} kr` : "Ikke spesifisert"}
${extraNotes ? `Stikkord/bruksområde: ${extraNotes}` : ""}

Tone: ${finalTone}

Skriv:
1. En kort, fengende innledning (1-2 setninger)
2. En hovedbeskrivelse (3-5 setninger) som fremhever produktets hovedfunksjoner og fordeler
3. En liste med 3-5 bullet points med nøkkelfordeler

Formatér svaret som JSON:
{
  "description": "hovedbeskrivelsen her",
  "bullets": ["fordel 1", "fordel 2", "fordel 3"]
}`;
        break;
      }

      case "seo": {
        const { name, category, description, shortDescription, pageType = "product" } = payload;
        const pageTypeText = 
          pageType === "product" ? "produktside" :
          pageType === "category" ? "kategoriside" :
          pageType === "frontpage" ? "forside" : "side";
        const desc = description || shortDescription || "Ikke spesifisert";
        prompt = `Generer SEO-optimalisert innhold for en ${pageTypeText}:

Navn/tittel: ${name || "Ikke spesifisert"}
Kategori: ${category || "Ikke spesifisert"}
Beskrivelse: ${desc}

Generer:
1. En SEO-tittel (50-60 tegn, inkluder produktnavn og kategori)
2. En meta-beskrivelse (140-160 tegn, fengende og informativ)

Formatér svaret som JSON:
{
  "title": "SEO-tittel her",
  "description": "Meta-beskrivelse her"
}`;
        break;
      }

      case "heroCopy": {
        const { campaignName, focus, discountInfo, productTypes, discount } = payload;
        const focusText = focus || productTypes || "Elektronikk";
        const discountText = discountInfo || (discount ? `${discount}% rabatt` : "");
        prompt = `Skriv hero-tekst for en kampanje:

Kampanjenavn: ${campaignName || "Ukens tilbud"}
Fokus: ${focusText}
Rabattinfo: ${discountText || "Ikke spesifisert"}

Generer:
1. En fengende hovedtittel (headline, maks 60 tegn)
2. En undertekst (subheadline, maks 120 tegn)
3. Primær CTA-tekst (maks 20 tegn, f.eks. "Se tilbud" eller "Kjøp nå")
4. Sekundær CTA-tekst (valgfritt, maks 20 tegn, f.eks. "Se alle produkter")

Formatér svaret som JSON:
{
  "headline": "Hovedtittel her",
  "subheadline": "Undertekst her",
  "ctaPrimary": "Primær CTA her",
  "ctaSecondary": "Sekundær CTA her (valgfritt)"
}`;
        break;
      }

      case "categoryCopy": {
        const { categoryName, productsHint, tone = "nøytral" } = payload;
        prompt = `Skriv kategori-tekst for følgende kategori:

Kategorinavn: ${categoryName || "Ikke spesifisert"}
Produkter i kategorien: ${productsHint || "Ikke spesifisert"}
Tone: ${tone}

Generer:
1. En kort introduksjonstekst (2-3 setninger) som beskriver kategorien
2. En kort blurb (1 setning) som kan brukes i kort visning

Formatér svaret som JSON:
{
  "intro": "Introduksjonstekst her",
  "shortBlurb": "Kort blurb her"
}`;
        break;
      }

      case "emailTemplate": {
        const { templateType, audienceDescription, offerDescription } = payload;
        const templateName = 
          templateType === "welcome" ? "velkomst-e-post" :
          templateType === "campaign" ? "kampanje-e-post" :
          templateType === "newsletter" ? "nyhetsbrev" : "e-post";
        
        prompt = `Skriv en ${templateName} for en norsk nettbutikk:

Målgruppe: ${audienceDescription || "Generell kundebase"}
Tilbud/tema: ${offerDescription || "Ikke spesifisert"}

Generer:
1. En fengende emnelinje (subject, maks 50 tegn)
2. En preheader-tekst (maks 100 tegn, vises i e-postklienter)
3. E-postinnhold i HTML-format (bodyHtml) med:
   - En hilsen
   - Hovedbudskapet
   - En klar call-to-action
   - En avslutning
   
Bruk enkel HTML: <h1>, <p>, <a>, <strong>. Ingen kompleks styling.

Formatér svaret som JSON:
{
  "subject": "Emnelinje her",
  "preheader": "Preheader-tekst her",
  "bodyHtml": "<h1>Tittel</h1><p>Innhold...</p><a href='#'>CTA</a>"
}`;
        break;
      }

      default:
        return NextResponse.json(
          { ok: false, error: "Ugyldig type" },
          { status: 400 }
        );
    }

    // Call OpenAI API using fetch (no SDK required)
    const response = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${apiKey}`,
      },
      body: JSON.stringify({
        model: "gpt-4o-mini", // Cost-effective model
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: prompt },
        ],
        temperature: 0.7,
        max_tokens: 1000,
      }),
    });

    if (!response.ok) {
      const errorData = await response.json().catch(() => ({}));
      logError(
        new Error(`OpenAI API error: ${response.status} ${JSON.stringify(errorData)}`),
        "[api/admin/ai]"
      );
      return NextResponse.json(
        {
          ok: false,
          error: `OpenAI API feil: ${errorData.error?.message || "Ukjent feil"}`,
        },
        { status: response.status }
      );
    }

    const data = await response.json();
    const content = data.choices[0]?.message?.content;

    if (!content) {
      return NextResponse.json(
        { ok: false, error: "Ingen respons fra AI" },
        { status: 500 }
      );
    }

    // Parse JSON response
    let result;
    try {
      result = JSON.parse(content);
    } catch (parseError) {
      // If not valid JSON, wrap in description field
      result = { description: content };
    }

    logInfo(`AI generated ${type} successfully`, "[api/admin/ai]");

    return NextResponse.json({
      ok: true,
      result,
    });
  } catch (error: any) {
    logError(error, "[api/admin/ai]");
    return NextResponse.json(
      {
        ok: false,
        error: error?.message || "Ukjent feil ved AI-generering",
      },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { getEmailEnvStatus, sendOrderConfirmation } from "@/lib/email";
import { prisma } from "@/lib/prisma";

export async function POST(
  request: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== "admin") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id: orderId } = await context.params;

    if (!orderId || orderId.trim() === "") {
      return NextResponse.json({ error: "Invalid order ID" }, { status: 400 });
    }

    const env = getEmailEnvStatus();
    console.log("[retry-email] env", {
      orderId: orderId.trim(),
      apiKeyDetected: env.apiKeyDetected ? "yes" : "no",
      emailFrom: env.emailFrom,
      adminEmailSet: env.adminEmailSet,
    });

    const result = await sendOrderConfirmation(orderId.trim());

    const order = await prisma.order.findUnique({
      where: { id: orderId.trim() },
      select: {
        customerEmailStatus: true,
        customerEmailLastError: true,
        customer: { select: { email: true } },
      },
    });

    if (!result.success) {
      return NextResponse.json(
        {
          error: result.error || "Failed to send email",
          message: `Kunne ikke sende e-post: ${result.error}`,
          diagnostics: {
            apiKeyDetected: env.apiKeyDetected,
            emailFrom: env.emailFrom,
            recipient: order?.customer?.email ?? null,
            finalDatabaseStatus: order?.customerEmailStatus ?? null,
          },
        },
        { status: 500 }
      );
    }

    return NextResponse.json({
      success: true,
      message: "Ordrebekreftelse sendt til kunde",
      diagnostics: {
        apiKeyDetected: env.apiKeyDetected,
        emailFrom: env.emailFrom,
        recipient: order?.customer?.email ?? null,
        finalDatabaseStatus: order?.customerEmailStatus ?? null,
      },
    });
  } catch (error: any) {
    console.error("Error retrying email:", error);
    return NextResponse.json(
      { error: error.message || "Failed to retry email" },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import {
  OrderStatus,
  PaymentStatus,
  Prisma,
  SupplierOrderStatus,
  FulfillmentStatus,
} from "@prisma/client";
import { z } from "zod";
import { logSupplierEvent } from "@/lib/dropshipping/supplier-events";
import Stripe from "stripe";
import { restoreStockForOrder } from "@/lib/orders/inventory";

const updateOrderSchema = z.object({
  status: z.nativeEnum(OrderStatus).optional(), // Deprecated, kept for backward compatibility
  fulfillmentStatus: z.nativeEnum(FulfillmentStatus).optional(), // Single source of truth
  paymentStatus: z.nativeEnum(PaymentStatus).optional(),
  trackingNumber: z.string().optional().nullable(),
  trackingUrl: z.string().optional().nullable(),
  shippingCarrier: z.string().optional().nullable(),
  supplierOrderStatus: z.nativeEnum(SupplierOrderStatus).optional(),
  notes: z.string().optional().nullable(),
  internalNotes: z.string().optional().nullable(),
});

// GET: Hent ordre detaljer
export async function GET(
  request: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  try {
    // Sjekk autentisering
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== "admin") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id: orderId } = await context.params;

    if (!orderId || orderId.trim() === "") {
      return NextResponse.json({ error: "Invalid order ID" }, { status: 400 });
    }

    const order = await prisma.order.findUnique({
      where: { id: orderId.trim() },
      include: {
        customer: true,
        orderItems: {
          include: {
            product: true,
          },
        },
      },
    });

    if (!order) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    // Parse items fra JSON hvis det finnes
    let items: any[] = [];
    try {
      if (typeof order.items === "string") {
        const parsed = JSON.parse(order.items);
        items = Array.isArray(parsed) ? parsed : [];
      } else if (order.items && Array.isArray(order.items)) {
        items = order.items;
      }
    } catch {
      // Hvis parsing feiler, bruk orderItems
      items = order.orderItems.map((item) => ({
        productId: item.productId,
        name: item.product.name,
        price: item.price,
        quantity: item.quantity,
      }));
    }

    // Parse shipping address
    let shippingAddress = {};
    try {
      if (typeof order.shippingAddress === "string") {
        shippingAddress = JSON.parse(order.shippingAddress);
      } else if (order.shippingAddress) {
        shippingAddress = order.shippingAddress;
      }
    } catch {
      shippingAddress = {};
    }

    const noteSetting = await prisma.setting.findUnique({
      where: { key: `order_internal_notes:${orderId.trim()}` },
    });
    const resolvedNotes =
      typeof noteSetting?.value === "string"
        ? noteSetting.value
        : noteSetting?.value != null
          ? String(noteSetting.value)
          : (order as any).internalNotes || null;

    return NextResponse.json({
      ...order,
      items,
      shippingAddress,
      internalNotes: resolvedNotes,
      notes: resolvedNotes,
    });
  } catch (error) {
    console.error("Error fetching order:", error);
    return NextResponse.json(
      { error: "Failed to fetch order" },
      { status: 500 }
    );
  }
}

// PATCH: Oppdater ordre
export async function PATCH(
  request: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  try {
    // Sjekk autentisering
    const session = await getServerSession(authOptions);
    if (!session || session.user.role !== "admin") {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id: orderId } = await context.params;

    if (!orderId || orderId.trim() === "") {
      return NextResponse.json({ error: "Invalid order ID" }, { status: 400 });
    }

    const body = await request.json();
    const validatedData = updateOrderSchema.parse(body);

    // Hent eksisterende ordre
    const existingOrder = await prisma.order.findUnique({
      where: { id: orderId.trim() },
    });

    if (!existingOrder) {
      return NextResponse.json({ error: "Order not found" }, { status: 404 });
    }

    const wasShippedBefore = existingOrder.fulfillmentStatus === "SHIPPED";
    const oldFulfillmentStatus = existingOrder.fulfillmentStatus;
    const oldSupplierStatus = existingOrder.supplierOrderStatus;
    const oldPaymentStatus = existingOrder.paymentStatus;

    // Real Stripe refund when marking as refunded
    if (
      validatedData.paymentStatus === "refunded" &&
      oldPaymentStatus !== "refunded" &&
      existingOrder.paymentIntentId
    ) {
      let stripeSecretKey = process.env.STRIPE_SECRET_KEY?.trim() || "";
      stripeSecretKey = stripeSecretKey.replace(/^["']+|["']+$/g, "").trim();
      if (!stripeSecretKey) {
        return NextResponse.json(
          { error: "Kan ikke refundere: Stripe er ikke konfigurert" },
          { status: 500 }
        );
      }
      const stripe = new Stripe(stripeSecretKey, {
        apiVersion: "2025-02-24.acacia",
      });
      try {
        await stripe.refunds.create({
          payment_intent: existingOrder.paymentIntentId,
          reason: "requested_by_customer",
          metadata: {
            orderId: existingOrder.id,
            orderNumber: existingOrder.orderNumber,
          },
        });
      } catch (refundErr: any) {
        console.error("Stripe refund failed:", refundErr);
        return NextResponse.json(
          {
            error: `Stripe-refusjon feilet: ${refundErr?.message || "ukjent feil"}`,
          },
          { status: 502 }
        );
      }
    }

    // Map fulfillmentStatus to legacy status for backward compatibility
    const { notes, internalNotes, ...rest } = validatedData;
    const updateData: Prisma.OrderUpdateInput = { ...rest };
    if (validatedData.fulfillmentStatus) {
      // Map fulfillmentStatus to legacy status
      const statusMap: Record<FulfillmentStatus, OrderStatus> = {
        NEW: "pending",
        ORDERED_FROM_SUPPLIER: "processing",
        SHIPPED: "shipped",
        DELIVERED: "delivered",
        CANCELLED: "cancelled",
      };
      updateData.status = statusMap[validatedData.fulfillmentStatus];
    }
    const noteValue = internalNotes !== undefined ? internalNotes : notes;
    // Persist notes (Setting key until Prisma client regen picks up Order.internalNotes)
    if (noteValue !== undefined) {
      const settingValue: Prisma.InputJsonValue | typeof Prisma.JsonNull =
        noteValue === null ? Prisma.JsonNull : noteValue;
      await prisma.setting.upsert({
        where: { key: `order_internal_notes:${orderId.trim()}` },
        create: {
          key: `order_internal_notes:${orderId.trim()}`,
          value: settingValue,
        },
        update: { value: settingValue },
      });
      try {
        await prisma.$executeRawUnsafe(
          `UPDATE "Order" SET "internalNotes" = $1 WHERE id = $2`,
          noteValue,
          orderId.trim()
        );
      } catch {
        /* column may lag in some envs — Setting is source of truth for UI */
      }
    }

    // Oppdater ordre
    const updatedOrder = await prisma.order.update({
      where: { id: orderId.trim() },
      data: updateData,
      include: {
        customer: true,
        orderItems: {
          include: {
            product: true,
          },
        },
      },
    });

    const noteSetting = await prisma.setting.findUnique({
      where: { key: `order_internal_notes:${orderId.trim()}` },
    });
    const resolvedNotes =
      typeof noteSetting?.value === "string"
        ? noteSetting.value
        : noteSetting?.value != null
          ? String(noteSetting.value)
          : null;

    // Restore inventory when refunding a previously paid order
    if (
      validatedData.paymentStatus === "refunded" &&
      oldPaymentStatus === "paid"
    ) {
      await restoreStockForOrder(updatedOrder.id).catch((err) =>
        console.error("Stock restore after refund failed:", err)
      );
    }

    // Hvis fulfillmentStatus endres til SHIPPED -> send shipping email
    const isNowShipped = updatedOrder.fulfillmentStatus === "SHIPPED";

    if (isNowShipped && !wasShippedBefore) {
      const trackingNumber =
        validatedData.trackingNumber ?? updatedOrder.trackingNumber ?? "";
      const trackingUrl =
        validatedData.trackingUrl ??
        updatedOrder.trackingUrl ??
        (trackingNumber ? `https://www.17track.net/en#nums=${trackingNumber}` : "");

      // Fire and forget
      import("@/lib/email").then(({ sendShippingNotification }) => {
        sendShippingNotification(
          updatedOrder.id,
          trackingNumber || "Sporingsnummer ikke tilgjengelig",
          trackingUrl || ""
        ).catch((err) => console.error("Failed to send shipped email:", err));
      });
    }

    // Log supplier status change if changed (internal note only)
    if (
      validatedData.supplierOrderStatus &&
      validatedData.supplierOrderStatus !== oldSupplierStatus
    ) {
      await logSupplierEvent({
        orderId: updatedOrder.id,
        oldStatus: oldSupplierStatus || SupplierOrderStatus.PENDING,
        newStatus: validatedData.supplierOrderStatus,
      });
    }

    // Log fulfillment status change if changed
    if (
      validatedData.fulfillmentStatus &&
      validatedData.fulfillmentStatus !== oldFulfillmentStatus
    ) {
      console.log(`Order ${updatedOrder.orderNumber} fulfillment status changed: ${oldFulfillmentStatus} → ${validatedData.fulfillmentStatus}`);
    }

    // Parse items for response
    let items: any[] = [];
    try {
      if (typeof updatedOrder.items === "string") {
        const parsed = JSON.parse(updatedOrder.items);
        items = Array.isArray(parsed) ? parsed : [];
      } else if (updatedOrder.items && Array.isArray(updatedOrder.items)) {
        items = updatedOrder.items;
      }
    } catch {
      items = updatedOrder.orderItems.map((item) => ({
        productId: item.productId,
        name: item.product.name,
        price: item.price,
        quantity: item.quantity,
      }));
    }

    // Parse shipping address
    let shippingAddress = {};
    try {
      if (typeof updatedOrder.shippingAddress === "string") {
        shippingAddress = JSON.parse(updatedOrder.shippingAddress);
      } else if (updatedOrder.shippingAddress) {
        shippingAddress = updatedOrder.shippingAddress;
      }
    } catch {
      shippingAddress = {};
    }

    return NextResponse.json({
      ...updatedOrder,
      items,
      shippingAddress,
      internalNotes: resolvedNotes,
      notes: resolvedNotes,
      message: "Order updated successfully",
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      return NextResponse.json(
        { error: "Invalid request data", details: error.issues },
        { status: 400 }
      );
    }

    console.error("Error updating order:", error);
    return NextResponse.json(
      { error: "Failed to update order" },
      { status: 500 }
    );
  }
}

