import { NextRequest, NextResponse } from "next/server";
import { getServerSession } from "next-auth";
import { authOptions } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { FulfillmentStatus, OrderStatus } from "@prisma/client";
import { z } from "zod";

const bodySchema = z.object({
  action: z.enum(["mark_ordered", "mark_shipped"]),
  /** If omitted, applies to all matching paid+NEW for mark_ordered */
  ids: z.array(z.string()).optional(),
});

/**
 * Bulk fulfillment so Rob never clicks the same status button N times.
 */
export async function POST(req: NextRequest) {
  const session = await getServerSession(authOptions);
  if (!session || session.user.role !== "admin") {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const parsed = bodySchema.parse(await req.json());
    let ids = parsed.ids?.filter(Boolean) || [];

    if (parsed.action === "mark_ordered" && ids.length === 0) {
      const paidNew = await prisma.order.findMany({
        where: { paymentStatus: "paid", fulfillmentStatus: "NEW" },
        select: { id: true },
        take: 200,
      });
      ids = paidNew.map((o) => o.id);
    }

    if (ids.length === 0) {
      return NextResponse.json({ ok: true, updated: 0, message: "Ingenting å oppdatere" });
    }

    if (ids.length > 200) {
      return NextResponse.json({ error: "Maks 200 ordrer per bulk" }, { status: 400 });
    }

    const fulfillmentStatus: FulfillmentStatus =
      parsed.action === "mark_ordered" ? "ORDERED_FROM_SUPPLIER" : "SHIPPED";
    const legacyStatus: OrderStatus =
      parsed.action === "mark_ordered" ? "processing" : "shipped";

    const result = await prisma.order.updateMany({
      where: { id: { in: ids } },
      data: {
        fulfillmentStatus,
        status: legacyStatus,
        ...(parsed.action === "mark_ordered"
          ? { supplierOrderStatus: "SENT_TO_SUPPLIER" as const }
          : {}),
      },
    });

    return NextResponse.json({
      ok: true,
      updated: result.count,
      action: parsed.action,
      message:
        parsed.action === "mark_ordered"
          ? `${result.count} ordre markert som bestilt hos leverandør`
          : `${result.count} ordre markert som sendt`,
    });
  } catch (error: any) {
    if (error?.name === "ZodError") {
      return NextResponse.json({ error: "Ugyldig forespørsel" }, { status: 400 });
    }
    console.error("orders bulk:", error);
    return NextResponse.json({ error: "Bulk-oppdatering feilet" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { requireAdminSession } from '@/lib/api-auth';
import { improveTitle } from '@/lib/utils/improve-product-title';
import { safeQuery } from '@/lib/safeQuery';
import { logError } from '@/lib/utils/logger';

export async function GET(
  req: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminSession();
  if (!auth.ok) return auth.response;

  try {
    const { id } = await context.params;
    const product = await safeQuery(
      () =>
        prisma.product.findUnique({
          where: { id },
          include: {
            variants: true,
          },
        }),
      null,
      'admin:product:get'
    );

    if (!product) {
      return NextResponse.json({ ok: false, error: 'Product not found' }, { status: 404 });
    }

    return NextResponse.json({ ok: true, data: product });
  } catch (error) {
    logError(error, '[api/admin/products/[id]] GET');
    return NextResponse.json(
      { ok: false, error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function PATCH(
  req: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminSession();
  if (!auth.ok) return auth.response;

  try {
    const { id } = await context.params;
    const body = await req.json();
    const { images, name, skipTitleImprovement, ...otherFields } = body;

    const updateData: any = { ...otherFields };
    if (images) {
      updateData.images = images;
    }

    // Inline admin edits can skip auto-title cleanup
    if (name) {
      updateData.name = skipTitleImprovement ? String(name).trim() : improveTitle(name);
    }

    const product = await prisma.product.update({
      where: { id },
      data: updateData,
    });

    return NextResponse.json({ ok: true, data: product });
  } catch (error) {
    logError(error, '[api/admin/products/[id]] PATCH');
    return NextResponse.json(
      { ok: false, error: 'Internal server error' },
      { status: 500 }
    );
  }
}

export async function DELETE(
  req: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  const auth = await requireAdminSession();
  if (!auth.ok) return auth.response;

  try {
    const { id } = await context.params;
    
    // Check if product exists
    const product = await safeQuery(
      () =>
        prisma.product.findUnique({
          where: { id },
          include: {
            variants: true,
            orderItems: true,
          },
        }),
      null,
      'admin:product:delete'
    );

    if (!product) {
      return NextResponse.json(
        { ok: false, error: 'Produkt ikke funnet' },
        { status: 404 }
      );
    }

    // Check if product has associated orders
    if (product.orderItems.length > 0) {
      return NextResponse.json(
        { ok: false, error: 'Kan ikke slette produkt som har tilknyttede ordre. Deaktiver produktet i stedet.' },
        { status: 400 }
      );
    }

    // Delete variants first (cascade)
    if (product.variants.length > 0) {
      await prisma.productVariant.deleteMany({
        where: { productId: id },
      });
    }

    // Delete the product
    await prisma.product.delete({
      where: { id },
    });

    return NextResponse.json(
      { ok: true, message: 'Produkt slettet' },
      { status: 200 }
    );
  } catch (error) {
    logError(error, '[api/admin/products/[id]] DELETE');
    return NextResponse.json(
      { ok: false, error: error instanceof Error ? error.message : 'Kunne ikke slette produkt' },
      { status: 500 }
    );
  }
}

import { NextResponse, NextRequest } from "next/server";
