export async function POST(
  req: Request,
  context: { params: Promise<{ id: string }> }
) {
  const session = await getAuthSession();
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await context.params;
    const variantData = await req.json();

    // Valider påkrevde felt
    if (!variantData.name || variantData.price === undefined) {
      return NextResponse.json(
        { error: "Navn og pris er påkrevd for variant" },
        { status: 400 }
      );
    }

    // Normalize color attributes (all supplier colors are allowed)
    let validatedAttributes = variantData.attributes || {};
    try {
      validatedAttributes = validateVariantAttributes(validatedAttributes);
    } catch (error) {
      return NextResponse.json(
        { error: error instanceof Error ? error.message : "Ugyldig farge" },
        { status: 400 }
      );
    }

    // Opprett variant
    const variant = await prisma.productVariant.create({
      data: {
        productId: id,
        name: variantData.name,
        sku: variantData.sku ? String(variantData.sku) : null,
        price: Number(variantData.price) || 0,
        compareAtPrice: variantData.compareAtPrice ? Number(variantData.compareAtPrice) : null,
        supplierPrice: variantData.supplierPrice ? Number(variantData.supplierPrice) : null,
        image: variantData.image || null,
        attributes: validatedAttributes,
        stock: variantData.stock ?? 10,
        isActive: variantData.isActive !== undefined ? variantData.isActive : true,
      },
    });

    return NextResponse.json(variant, { status: 201 });
  } catch (error) {
    console.error("Error creating variant:", error);
    const message = error instanceof Error ? error.message : "Feil ved oppretting av variant";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

export async function PUT(
  req: Request,
  context: { params: Promise<{ id: string }> }
) {
  const session = await getAuthSession();
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { id } = await context.params;
    const { variants } = await req.json();

    if (!Array.isArray(variants)) {
      return NextResponse.json({ error: "Variants må være en array" }, { status: 400 });
    }

    // Slett alle eksisterende varianter
    await prisma.productVariant.deleteMany({
      where: { productId: id },
    });

    // Validate all variants before creating
    const validatedVariants = variants.map((variant: any) => {
      let validatedAttributes = variant.attributes || {};
      try {
        validatedAttributes = validateVariantAttributes(validatedAttributes);
      } catch (error) {
        throw new Error(
          `Variant "${variant.name}": ${error instanceof Error ? error.message : "Ugyldig farge"}`
        );
      }
      return {
        ...variant,
        attributes: validatedAttributes,
      };
    });

    // Opprett nye varianter
    const createdVariants = await Promise.all(
      validatedVariants.map((variant: any) =>
        prisma.productVariant.create({
          data: {
            productId: id,
            name: variant.name,
            price: Number(variant.price) || 0,
            compareAtPrice: variant.compareAtPrice ? Number(variant.compareAtPrice) : null,
            supplierPrice: variant.supplierPrice ? Number(variant.supplierPrice) : null,
            image: variant.image || null,
            attributes: variant.attributes || {},
            stock: variant.stock || 0,
            isActive: variant.isActive !== undefined ? variant.isActive : true,
          },
        })
      )
    );

    return NextResponse.json({ variants: createdVariants });
  } catch (error) {
    console.error("Error updating variants:", error);
    const message = error instanceof Error ? error.message : "Feil ved oppdatering av varianter";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthSession } from '@/lib/auth';
import { safeQuery } from '@/lib/safeQuery';
import { calculateCompareAtPrice, calculateSuggestedRetailPrice } from '@/lib/import/pricing';

export async function POST(req: Request) {
  try {
    const session = await getAuthSession();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { productId } = await req.json();

    if (!productId) {
      return NextResponse.json({ error: 'Product ID is required' }, { status: 400 });
    }

    const product = await safeQuery(
      () =>
        prisma.product.findUnique({
          where: { id: productId },
        }),
      null,
      'admin:auto-fix-variants'
    );

    if (!product) {
      return NextResponse.json({ error: 'Product not found' }, { status: 404 });
    }

    let images: string[] = [];
    try {
      images = typeof product.images === 'string' ? JSON.parse(product.images) : (product.images || []);
    } catch {
      images = [];
    }

    const updates: any = {};

    // Fix 1: Ensure at least 1 image
    if (!images || images.length === 0) {
      updates.images = JSON.stringify([
        'https://placehold.co/600x600/e2e8f0/64748b?text=' + encodeURIComponent(product.name.substring(0, 50)),
      ]);
    }

    // Fix 2: Ensure compareAtPrice is higher than price
    if (product.compareAtPrice && product.compareAtPrice <= product.price) {
      updates.compareAtPrice = calculateCompareAtPrice(product.price);
    }

    // Fix 3: Ensure reasonable price margins (dynamic pricing curve)
    if (product.supplierPrice && product.supplierPrice >= product.price) {
      updates.price = calculateSuggestedRetailPrice(product.supplierPrice);
    }

    // Fix 4: Auto-generate description if missing
    if (!product.description || product.description.length < 50) {
      updates.description = `${product.name} er et premium produkt i kategorien ${product.category || 'Elektronikk'}. 

Dette produktet tilbyr høy kvalitet og god verdi for pengene. 

Perfekt for både hjemmebruk og profesjonell bruk. 

Rask levering og god kundeservice inkludert.`;
    }

    // Fix 5: Auto-generate short description
    if (!product.shortDescription) {
      updates.shortDescription = `Premium ${(product.category || 'Elektronikk').toLowerCase()} med høy kvalitet og god pris.`;
    }

    // Apply fixes
    if (Object.keys(updates).length > 0) {
      await prisma.product.update({
        where: { id: productId },
        data: updates,
      });
    }

    return NextResponse.json({ 
      success: true, 
      fixesApplied: Object.keys(updates).length,
      fixes: Object.keys(updates),
    });
  } catch (error: any) {
    console.error('Error auto-fixing variants:', error);
    return NextResponse.json(
      { error: error.message || 'Error auto-fixing variants' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getAuthSession } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import slugify from "slugify";
import { improveTitle } from "@/lib/utils/improve-product-title";
import { safeQuery } from "@/lib/safeQuery";
import { DEFAULT_STORE_ID } from "@/lib/store";
import { getProviderRegistry } from "@/lib/providers/server-only";
import type { BulkImportResult } from "@/lib/providers";
import { SupplierName } from "@prisma/client";
import { sanitizeDescriptionWithFallback } from "@/lib/import/sanitizeDescription";
import {
  calculateCompareAtPrice,
  calculateSuggestedRetailPrice,
  convertPriceToNOK,
} from "@/lib/import/pricing";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

function generateId(): string {
  return Math.random().toString(36).substring(2, 10) + Date.now().toString(36).substring(2, 6);
}

/**
 * Map provider name string to SupplierName enum value
 * Returns null if provider name doesn't match any known supplier
 */
function mapProviderToSupplierName(providerName: string): SupplierName | null {
  const normalized = providerName.toLowerCase().trim();
  
  // Map known provider names to SupplierName enum values
  if (normalized === "alibaba") {
    return SupplierName.alibaba;
  }
  if (normalized === "ebay") {
    return SupplierName.ebay;
  }
  if (normalized === "temu") {
    return SupplierName.temu;
  }
  
  // Unknown provider
  return null;
}

async function importProduct(
  inputUrl: string,
  providerName?: string
): Promise<BulkImportResult> {
  const registry = getProviderRegistry();
  const warnings: string[] = [];
  
  try {
    // Auto-detect provider if not specified
    const provider = registry.getProviderForUrl(inputUrl, providerName);
    
    if (!provider) {
      const detectedProviders = registry.getAllProviders().map(p => p.getName()).join(", ");
      return {
        inputUrl,
        normalizedUrl: inputUrl,
        providerUsed: "none",
        status: "error",
        message: `Ustøttet leverandør. Støttede: ${detectedProviders}`,
        warnings,
      };
    }

    const providerUsed = provider.getName();

    // Normalize URL
    const normalizedUrl = provider.normalizeUrl(inputUrl);

    // Fetch raw product data
    let rawProduct;
    try {
      rawProduct = await provider.fetchProduct(normalizedUrl);
    } catch (error) {
      // Log detailed error server-side
      const errorMessage = error instanceof Error ? error.message : "Ukjent feil";
      console.error(`[Bulk Import] Error fetching product from ${providerUsed}:`, {
        url: normalizedUrl,
        error: errorMessage,
        stack: error instanceof Error ? error.stack : undefined,
      });
      
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "error",
        message: "Kunne ikke hente produktdata. Sjekk at URL-en er korrekt og at produktet eksisterer.",
        warnings,
      };
    }

    // Check for warnings in raw product metadata
    if (rawProduct.metadata?.warnings && Array.isArray(rawProduct.metadata.warnings)) {
      warnings.push(...rawProduct.metadata.warnings);
    }

    // Map to our product format
    const data = provider.mapToProduct(rawProduct, normalizedUrl);

    // Sjekk om produktet allerede eksisterer (bruk normalisert URL)
    const existing = await safeQuery(
      () =>
        prisma.product.findFirst({
          where: {
            supplierUrl: normalizedUrl,
          },
        }),
      null,
      "admin:bulk-import:existing"
    );

    if (existing) {
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "warning",
        message: `Produktet eksisterer allerede: ${existing.name}`,
        warnings: [...warnings, "Produktet ble ikke opprettet fordi det allerede finnes i databasen"],
      };
    }

    // Forbered data
    const baseImages = data.images || [];
    
    // Sanitize description to remove supplier references
    const rawDescription = data.description || "";
    const description = sanitizeDescriptionWithFallback(
      rawDescription,
      "Dette produktet er en del av vårt utvalg av elektronikk og tilbehør. Vi leverer kvalitetsprodukter med fokus på funksjonalitet og verdi."
    );
    const shortDescription = description.substring(0, 150) + (description.length > 150 ? "..." : "");

    // Håndter varianter
    const hasVariants = data.variants && data.variants.length > 1;
    const variants = data.variants || [];

    // CRITICAL: Collect ALL images from product AND variants
    // This ensures all variant images are available in the product's images array
    const allImagesSet = new Set<string>();
    
    // Add base product images
    baseImages.forEach((img: string) => {
      if (img && img.startsWith('http') && !img.includes('placeholder')) {
        allImagesSet.add(img);
      }
    });
    
    // Add variant images
    variants.forEach((variant: any) => {
      if (variant.image && 
          variant.image.startsWith('http') && 
          !variant.image.includes('placeholder') &&
          !variant.image.includes('placehold.co')) {
        allImagesSet.add(variant.image);
      }
    });
    
    // Convert to array, ensuring variant images are first (they're usually more specific)
    const variantImages = variants
      .map((v: any) => v.image)
      .filter((img: string) => img && img.startsWith('http') && !img.includes('placeholder'));
    
    const images = [
      ...variantImages.filter((img: string, idx: number, arr: string[]) => arr.indexOf(img) === idx), // Unique variant images first
      ...Array.from(allImagesSet).filter(img => !variantImages.includes(img)) // Then other images
    ];
    
    console.log(`[Bulk Import] Collected ${images.length} total images (${baseImages.length} base + ${variantImages.length} variant images)`);

    // Bestem kategori
    let category = "Elektronikk";
    const titleLower = data.title.toLowerCase();
    if (titleLower.includes("phone") || titleLower.includes("iphone") || titleLower.includes("mobil")) {
      category = "Mobil & Tilbehør";
    } else if (
      titleLower.includes("computer") ||
      titleLower.includes("laptop") ||
      titleLower.includes("pc") ||
      titleLower.includes("tastatur") ||
      titleLower.includes("keyboard")
    ) {
      category = "Datamaskiner";
    } else if (titleLower.includes("tv") || titleLower.includes("speaker") || titleLower.includes("høyttaler")) {
      category = "TV & Lyd";
    } else if (titleLower.includes("game") || titleLower.includes("gaming")) {
      category = "Gaming";
    } else if (titleLower.includes("home") || titleLower.includes("hjem")) {
      category = "Hjem & Fritid";
    }

    // Base price (laveste variant pris eller hovedpris)
    let basePrice = variants.length > 0 ? Math.min(...variants.map((v) => v.price)) : data.price.amount;

    // If price is 0 or missing, use a default estimated price
    if (!basePrice || basePrice === 0) {
      basePrice = 9.99; // Default estimated price in USD for Temu products
    }

    // Konverter pris til NOK og bruk den dynamiske priskurven
    const baseSupplierPriceNok = Math.round(convertPriceToNOK(basePrice, "USD"));
    const baseSellingPriceNok = calculateSuggestedRetailPrice(baseSupplierPriceNok);
    const baseCompareAtPriceNok = calculateCompareAtPrice(baseSellingPriceNok);

    // Forbedre produkt-tittel automatisk
    const improvedTitle = improveTitle(data.title);
    
    // Generer unik SKU og slug basert på forbedret tittel
    const sku = `${providerUsed.toUpperCase()}-${generateId().toUpperCase()}`;
    const slugBase = slugify(improvedTitle, { lower: true, strict: true });
    const slug = `${slugBase}-${generateId().substring(0, 4)}`;

    // Opprett produkt med varianter
    // CRITICAL: Set storeId to DEFAULT_STORE_ID so products appear in frontend
    let product;
    try {
      product = await prisma.product.create({
        data: {
          name: improvedTitle,
          slug,
          description: description || shortDescription,
          shortDescription,
          price: baseSellingPriceNok,
          compareAtPrice: baseCompareAtPriceNok,
          supplierPrice: baseSupplierPriceNok,
          images: JSON.stringify(images),
          tags: data.specs ? JSON.stringify(Object.keys(data.specs).slice(0, 10)) : JSON.stringify([]),
          category,
          sku,
          isActive: true,
          storeId: DEFAULT_STORE_ID, // Set storeId so products appear in frontend
          supplierUrl: normalizedUrl,
          supplierName: mapProviderToSupplierName(providerUsed),
        variants: hasVariants
          ? {
              create: variants.map((variant, index) => {
                const variantSupplierPriceNok = Math.round(convertPriceToNOK(variant.price, "USD"));
                const variantSellingPriceNok = calculateSuggestedRetailPrice(variantSupplierPriceNok);
                const variantCompareAtPriceNok = calculateCompareAtPrice(variantSellingPriceNok);

                return {
                  name: variant.name,
                  sku: `${sku}-V${index + 1}`,
                  price: variantSellingPriceNok,
                  compareAtPrice: variantCompareAtPriceNok,
                  supplierPrice: variantSupplierPriceNok,
                  image: variant.image || null,
                  attributes: variant.attributes || {},
                  stock: variant.stock || 0,
                  isActive: true,
                };
              }),
            }
          : undefined,
      },
        include: {
          variants: true,
        },
      });
    } catch (dbError) {
      // Log detailed database error server-side
      console.error(`[Bulk Import] Database error creating product:`, {
        url: normalizedUrl,
        provider: providerUsed,
        error: dbError instanceof Error ? dbError.message : "Ukjent database-feil",
        stack: dbError instanceof Error ? dbError.stack : undefined,
      });
      
      return {
        inputUrl,
        normalizedUrl,
        providerUsed,
        status: "error",
        message: "Kunne ikke lagre produktet i databasen. Prøv igjen senere.",
        warnings,
      };
    }

    // Check for warnings (e.g., missing images, low price, etc.)
    if (images.length === 0) {
      warnings.push("Ingen bilder funnet for produktet");
    }
    if (basePrice < 1) {
      warnings.push("Pris ser ut til å være ugyldig eller manglende");
    }

    return {
      inputUrl,
      normalizedUrl,
      providerUsed,
      status: warnings.length > 0 ? "warning" : "success",
      message: `Produkt importert: ${product.name}`,
      createdProductId: product.id,
      warnings: warnings.length > 0 ? warnings : undefined,
    };
  } catch (error) {
    // Log detailed error server-side
    const errorMessage = error instanceof Error ? error.message : "Ukjent feil";
    console.error(`[Bulk Import] Unexpected error:`, {
      url: inputUrl,
      error: errorMessage,
      stack: error instanceof Error ? error.stack : undefined,
    });
    
    return {
      inputUrl,
      normalizedUrl: inputUrl,
      providerUsed: "unknown",
      status: "error",
      message: "En uventet feil oppstod under import. Prøv igjen senere.",
      warnings,
    };
  }
}

export async function POST(req: Request) {
  const session = await getAuthSession();
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { urls, provider } = await req.json();

    // Validate request body
    if (!Array.isArray(urls) || urls.length === 0) {
      return NextResponse.json({ error: "URL-er er påkrevd (array)" }, { status: 400 });
    }

    // Validate provider if specified
    if (provider && typeof provider !== "string") {
      return NextResponse.json({ error: "Provider må være en string" }, { status: 400 });
    }

    if (provider && !["temu", "alibaba"].includes(provider.toLowerCase())) {
      return NextResponse.json({ error: `Ustøttet provider: ${provider}. Støttede: temu, alibaba` }, { status: 400 });
    }

    // Validate all URLs
    const invalidUrls: string[] = [];
    for (const url of urls) {
      if (typeof url !== "string" || (!url.startsWith("http://") && !url.startsWith("https://"))) {
        invalidUrls.push(url);
      }
    }

    if (invalidUrls.length > 0) {
      return NextResponse.json({ 
        error: `Ugyldige URL-er funnet: ${invalidUrls.slice(0, 3).join(", ")}${invalidUrls.length > 3 ? "..." : ""}` 
      }, { status: 400 });
    }

    // Import all products sequentially (to avoid overload)
    // Continue even if individual URLs fail
    const results: BulkImportResult[] = [];
    
    for (let i = 0; i < urls.length; i++) {
      const url = urls[i];
      
      try {
        // Auto-detect provider per URL if not specified
        const result = await importProduct(url, provider);
        results.push(result);
      } catch (error) {
        // Log error but continue with next URL
        console.error(`[Bulk Import] Error processing URL ${i + 1}/${urls.length}:`, {
          url,
          error: error instanceof Error ? error.message : "Ukjent feil",
          stack: error instanceof Error ? error.stack : undefined,
        });
        
        // Add error result
        results.push({
          inputUrl: url,
          normalizedUrl: url,
          providerUsed: "unknown",
          status: "error",
          message: "En uventet feil oppstod under import av denne URL-en.",
          warnings: [],
        });
      }

      // Rate limiting: wait between requests (except for last one)
      if (i < urls.length - 1) {
        await new Promise((resolve) => setTimeout(resolve, 2000));
      }
    }

    // Return results
    return NextResponse.json({ results });
  } catch (error) {
    // Log detailed error server-side
    console.error("[Bulk Import] Fatal error:", {
      error: error instanceof Error ? error.message : "Ukjent feil",
      stack: error instanceof Error ? error.stack : undefined,
    });
    
    const message = error instanceof Error ? error.message : "Ukjent feil ved bulk import";
    return NextResponse.json({ error: message }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthSession } from '@/lib/auth';
import { safeQuery } from '@/lib/safeQuery';

export async function POST(req: Request) {
  try {
    const session = await getAuthSession();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const { productId } = await req.json();

    if (!productId) {
      return NextResponse.json({ error: 'Product ID is required' }, { status: 400 });
    }

    const product = await safeQuery(
      () =>
        prisma.product.findUnique({
          where: { id: productId },
          include: {
            variants: true,
          },
        }),
      null,
      'admin:check-variants'
    );

    if (!product) {
      return NextResponse.json({ error: 'Product not found' }, { status: 404 });
    }

    const issues: Array<{
      type: string;
      severity: 'critical' | 'warning' | 'info';
      message: string;
      suggestion: string;
    }> = [];

    // Parse images and tags
    let images: string[] = [];
    let tags: string[] = [];

    try {
      images = typeof product.images === 'string' ? JSON.parse(product.images) : (product.images || []);
    } catch {
      images = [];
    }

    try {
      tags = typeof product.tags === 'string' ? JSON.parse(product.tags) : (product.tags || []);
    } catch {
      tags = [];
    }

    // Check 1: Images exist
    if (!images || images.length === 0) {
      issues.push({
        type: 'missing_image',
        severity: 'critical',
        message: 'Produktet mangler bilder',
        suggestion: 'Last opp minst 1 bilde for produktet',
      });
    }

    // Check 2: Minimum number of images
    if (images && images.length < 3) {
      issues.push({
        type: 'missing_image',
        severity: 'warning',
        message: `Bare ${images.length} bilde(r). Anbefaler minst 3 bilder.`,
        suggestion: 'Last opp flere produktbilder for bedre konvertering',
      });
    }

    // Check 3: Variant detection (from database variants or tags)
    const hasVariants = product.variants && product.variants.length > 0;
    
    const hasColorVariants = hasVariants
      ? product.variants.some(v => {
          const attrs = (v.attributes as Record<string, string>) || {};
          return Object.keys(attrs).some(k => 
            k.toLowerCase().includes('color') || 
            k.toLowerCase().includes('farge')
          );
        })
      : tags.some((tag: string) =>
          ['rød', 'blå', 'grønn', 'svart', 'hvit', 'gul', 'rosa', 'lilla', 'red', 'blue', 'green', 'black', 'white', 'yellow', 'pink', 'purple'].some(color =>
            tag.toLowerCase().includes(color)
          )
        );

    const hasSizeVariants = hasVariants
      ? product.variants.some(v => {
          const attrs = (v.attributes as Record<string, string>) || {};
          return Object.keys(attrs).some(k => 
            k.toLowerCase().includes('size') || 
            k.toLowerCase().includes('størrelse')
          );
        })
      : tags.some((tag: string) =>
          ['xs', 's', 'm', 'l', 'xl', 'xxl', 'small', 'medium', 'large'].some(size =>
            tag.toLowerCase() === size
          )
        );

    // Check 4: Color variants should have images
    if (hasColorVariants && images.length < 2) {
      issues.push({
        type: 'wrong_color',
        severity: 'warning',
        message: 'Produktet har fargevarianter men kun 1 bilde',
        suggestion: 'Last opp ett bilde per fargevariant',
      });
    }

    // Check 5: Variants without images
    if (hasVariants) {
      const variantsWithoutImages = product.variants.filter(v => !v.image);
      if (variantsWithoutImages.length > 0) {
        issues.push({
          type: 'missing_image',
          severity: 'warning',
          message: `${variantsWithoutImages.length} variant(er) mangler bilde`,
          suggestion: 'Legg til bilde for hver variant',
        });
      }
    }

    // Check 6: Price validation
    if (product.price <= 0) {
      issues.push({
        type: 'mismatched_price',
        severity: 'critical',
        message: 'Ugyldig pris (0 kr eller negativt)',
        suggestion: 'Sett riktig salgspris',
      });
    }

    if (product.compareAtPrice && product.compareAtPrice <= product.price) {
      issues.push({
        type: 'mismatched_price',
        severity: 'warning',
        message: 'Før-pris er lavere enn salgspris',
        suggestion: 'Før-pris skal være høyere enn salgspris',
      });
    }

    // Check 7: Supplier price vs selling price
    if (product.supplierPrice && product.supplierPrice >= product.price) {
      issues.push({
        type: 'mismatched_price',
        severity: 'critical',
        message: 'Leverandørpris er høyere enn salgspris (du taper penger!)',
        suggestion: 'Øk salgsprisen eller finn billigere leverandør',
      });
    }

    // Check 8: Description quality
    if (!product.description || product.description.length < 50) {
      issues.push({
        type: 'missing_image',
        severity: 'info',
        message: 'Kort eller manglende produktbeskrivelse',
        suggestion: 'Skriv en detaljert beskrivelse (minst 50 tegn)',
      });
    }

    // Check 9: Variant names consistency
    if (hasVariants && product.variants.length > 1) {
      const variantNames = product.variants.map(v => v.name).filter(Boolean);
      const uniqueNames = new Set(variantNames);
      if (variantNames.length !== uniqueNames.size) {
        issues.push({
          type: 'duplicate',
          severity: 'warning',
          message: 'Noen varianter har samme navn',
          suggestion: 'Gi hver variant et unikt navn',
        });
      }
    }

    return NextResponse.json({ issues });
  } catch (error: any) {
    console.error('Error checking variants:', error);
    return NextResponse.json(
      { error: error.message || 'Error checking variants' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { getAuthSession } from "@/lib/auth";
import { updateAllProducts } from "@/scripts/auto-match-variant-images";
import { fixAllProducts } from "@/scripts/fix-all-product-variants";

export const dynamic = "force-dynamic";

/**
 * API route to fix product variants and images
 * POST /api/admin/products/fix-variants
 * Body: { action: 'match-images' | 'fix-all' | 'both' }
 */
export async function POST(req: Request) {
  const session = await getAuthSession();
  if (!session?.user) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const { action = 'both' } = await req.json();

    const results: any = {
      success: true,
      action,
      timestamp: new Date().toISOString(),
    };

    if (action === 'match-images' || action === 'both') {
      console.log('[Fix Variants API] Running image matching...');
      // Note: updateAllProducts logs to console, we'll capture summary
      await updateAllProducts();
      results.imageMatching = { completed: true };
    }

    if (action === 'fix-all' || action === 'both') {
      console.log('[Fix Variants API] Running full fix...');
      await fixAllProducts();
      results.fullFix = { completed: true };
    }

    return NextResponse.json(results);
  } catch (error) {
    console.error("[Fix Variants API] Error:", error);
    const message = error instanceof Error ? error.message : "Ukjent feil";
    return NextResponse.json(
      { error: message, success: false },
      { status: 500 }
    );
  }
}

import { NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthSession } from '@/lib/auth';
import { safeQuery } from '@/lib/safeQuery';

export async function GET() {
  try {
    const session = await getAuthSession();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const products = await safeQuery(
      () =>
        prisma.product.findMany({
          orderBy: { createdAt: 'desc' },
          include: {
            variants: true,
          },
        }),
      [],
      'admin:variant-check'
    );

    const formattedProducts = products.map(product => {
      let images: string[] = [];
      let tags: string[] = [];

      try {
        images = typeof product.images === 'string' ? JSON.parse(product.images) : (product.images || []);
      } catch {
        images = [];
      }

      try {
        tags = typeof product.tags === 'string' ? JSON.parse(product.tags) : (product.tags || []);
      } catch {
        tags = [];
      }

      // Group variants by type (color, size, etc.)
      const variantsByType: Record<string, Array<{
        value: string;
        image?: string;
        colorCode?: string;
        price?: number;
      }>> = {};

      // Process database variants
      if (product.variants && product.variants.length > 0) {
        product.variants.forEach((variant) => {
          // Extract variant type from attributes
          const attributes = variant.attributes as Record<string, string> || {};
          const variantType = Object.keys(attributes)[0] || 'standard';
          const variantValue = Object.values(attributes)[0] || variant.name;

          if (!variantsByType[variantType]) {
            variantsByType[variantType] = [];
          }

          variantsByType[variantType].push({
            value: variantValue,
            image: variant.image || undefined,
            colorCode: variantType === 'color' || variantType === 'farge' ? getColorCode(variantValue) : undefined,
            price: variant.price ? Number(variant.price) : undefined,
          });
        });
      }

      // Also detect potential variants from tags (fallback)
      const colorVariants = tags.filter((tag: string) =>
        ['rød', 'blå', 'grønn', 'svart', 'hvit', 'gul', 'rosa', 'lilla', 'red', 'blue', 'green', 'black', 'white', 'yellow', 'pink', 'purple'].some(c =>
          tag.toLowerCase().includes(c)
        )
      );

      const sizeVariants = tags.filter((tag: string) =>
        ['xs', 's', 'm', 'l', 'xl', 'xxl'].includes(tag.toLowerCase())
      );

      const variants = [];

      // Add color variants from database
      if (variantsByType['color'] || variantsByType['farge']) {
        const colorVars = variantsByType['color'] || variantsByType['farge'] || [];
        if (colorVars.length > 0) {
          variants.push({
            type: 'color',
            name: 'Farge',
            options: colorVars,
          });
        }
      } else if (colorVariants.length > 0) {
        // Fallback: use tags
        variants.push({
          type: 'color',
          name: 'Farge',
          options: colorVariants.map((color: string, idx: number) => ({
            value: color,
            image: images[idx] || images[0],
            colorCode: getColorCode(color),
          })),
        });
      }

      // Add size variants from database
      if (variantsByType['size'] || variantsByType['størrelse']) {
        const sizeVars = variantsByType['size'] || variantsByType['størrelse'] || [];
        if (sizeVars.length > 0) {
          variants.push({
            type: 'size',
            name: 'Størrelse',
            options: sizeVars,
          });
        }
      } else if (sizeVariants.length > 0) {
        // Fallback: use tags
        variants.push({
          type: 'size',
          name: 'Størrelse',
          options: sizeVariants.map((size: string) => ({
            value: size.toUpperCase(),
          })),
        });
      }

      return {
        id: product.id,
        name: product.name,
        slug: product.slug,
        images: images || [],
        variants: variants,
        issues: [] as Array<{
          type: string;
          severity: 'critical' | 'warning' | 'info';
          message: string;
          suggestion: string;
        }>,
        status: 'unchecked' as const,
      };
    });

    return NextResponse.json({ products: formattedProducts });
  } catch (error: any) {
    console.error('Error loading products:', error);
    return NextResponse.json(
      { error: error.message || 'Error loading products' },
      { status: 500 }
    );
  }
}

function getColorCode(colorName: string): string {
  const colorMap: Record<string, string> = {
    rød: '#ef4444',
    red: '#ef4444',
    blå: '#3b82f6',
    blue: '#3b82f6',
    grønn: '#10b981',
    green: '#10b981',
    svart: '#1f2937',
    black: '#1f2937',
    hvit: '#f3f4f6',
    white: '#f3f4f6',
    gul: '#fbbf24',
    yellow: '#fbbf24',
    rosa: '#ec4899',
    pink: '#ec4899',
    lilla: '#a855f7',
    purple: '#a855f7',
  };

  const normalizedColor = colorName.toLowerCase().trim();

  for (const [key, value] of Object.entries(colorMap)) {
    if (normalizedColor.includes(key)) {
      return value;
    }
  }

  return '#94a3b8'; // Default gray
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { getAuthSession } from '@/lib/auth';

export async function PATCH(
  req: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  const session = await getAuthSession();
  if (!session?.user) {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { id } = await context.params;
    const body = await req.json();
    const { image, ...otherFields } = body;

    const updateData: any = { ...otherFields };
    if (image !== undefined) {
      updateData.image = image;
    }

    const variant = await prisma.productVariant.update({
      where: { id },
      data: updateData,
    });

    return NextResponse.json(variant);
  } catch (error) {
    console.error('Error updating variant:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

export async function POST(req: Request) {
  try {
    const body = await req.json();
    const { code, ip, userAgent } = body;
    if (!code) return NextResponse.json({ error: "code required" }, { status: 400 });

    const affiliate = await prisma.affiliate.findUnique({ where: { code } });
    if (!affiliate) return NextResponse.json({ error: "affiliate not found" }, { status: 404 });

    const click = await prisma.affiliateClick.create({
      data: {
        affiliateId: affiliate.id,
        ip: ip || null,
        userAgent: userAgent || null,
      },
    });

    return NextResponse.json({ success: true, clickId: click.id });
  } catch (error: any) {
    return NextResponse.json({ error: error.message || "failed" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { requireAdminSession, requireInternalToken } from "@/lib/api-auth";

export async function POST(req: Request) {
  const internalDenied = requireInternalToken(req);
  const admin = await requireAdminSession();
  if (internalDenied && !admin.ok) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const body = await req.json();
    const { code, orderId, commissionAmount } = body;
    if (!code || !orderId) {
      return NextResponse.json({ error: "code and orderId required" }, { status: 400 });
    }

    // Never trust client-supplied commission in production paths — look up affiliate rate later.
    // For now require auth and clamp amount.
    const amount = Math.max(0, Number(commissionAmount ?? 0));
    if (!Number.isFinite(amount) || amount > 100_000) {
      return NextResponse.json({ error: "Invalid commissionAmount" }, { status: 400 });
    }

    const affiliate = await prisma.affiliate.findUnique({ where: { code } });
    if (!affiliate) return NextResponse.json({ error: "affiliate not found" }, { status: 404 });

    await prisma.affiliateOrder.create({
      data: {
        affiliateId: affiliate.id,
        orderId,
        commissionAmount: amount,
      },
    });

    return NextResponse.json({ success: true });
  } catch (error: any) {
    return NextResponse.json({ error: error.message || "failed" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import Stripe from "stripe";
import { prisma } from "@/lib/prisma";
import { nanoid } from "nanoid";
import { PaymentMethod, OrderStatus, PaymentStatus, FulfillmentStatus } from "@prisma/client";
import { getStoreIdFromHeadersServer } from "@/lib/store-server";
import { safeQuery } from "@/lib/safeQuery";
import { includedVatFromGross } from "@/lib/pricing/tax";
import {
  computeShippingCost,
  normalizeShippingMethod,
  shippingMethodLabel,
} from "@/lib/checkout/shipping";
import { canPurchaseQuantity } from "@/lib/checkout/stock-policy";

// Stripe instance vil bli opprettet med validert key i POST handler

export async function POST(req: Request) {
  try {
    // Validate payload early (before Stripe client setup) so callers get clear 400s
    let earlyBody: any = null;
    try {
      earlyBody = await req.json();
    } catch {
      return NextResponse.json({ error: "Ugyldig forespørsel" }, { status: 400 });
    }
    if (!earlyBody?.customer?.email || typeof earlyBody.customer.email !== "string") {
      return NextResponse.json({ error: "E-postadresse er påkrevd" }, { status: 400 });
    }
    if (!earlyBody?.items || !Array.isArray(earlyBody.items) || earlyBody.items.length === 0) {
      return NextResponse.json({ error: "Handlekurven er tom" }, { status: 400 });
    }

    console.log("📥 Payment intent request received");
    const storeId = await getStoreIdFromHeadersServer();
    
    // Sjekk og valider Stripe keys
    let stripeSecretKey = process.env.STRIPE_SECRET_KEY?.trim() || "";
    
    // Remove extra quotes if present
    stripeSecretKey = stripeSecretKey.replace(/^["']+|["']+$/g, "").trim();
    
    if (!stripeSecretKey) {
      console.error("❌ STRIPE_SECRET_KEY is not set in environment variables");
      return NextResponse.json(
        { error: "Betalingssystemet er ikke konfigurert. Kontakt kundeservice." },
        { status: 500 }
      );
    }

    // Valider at Stripe key har riktig format
    if (!stripeSecretKey.startsWith("sk_test_") && !stripeSecretKey.startsWith("sk_live_")) {
      console.error("❌ STRIPE_SECRET_KEY has invalid format:", {
        keyLength: stripeSecretKey.length,
        firstChars: stripeSecretKey.substring(0, 15),
        hasWhitespace: /\s/.test(stripeSecretKey),
      });
      return NextResponse.json(
        { 
          error: "Betalingssystemet er ikke konfigurert. Kontakt kundeservice.",
        },
        { status: 500 }
      );
    }

    // Log key info for debugging (uten å vise hele key-en)
    console.log("🔑 Stripe key validation:", {
      keyLength: stripeSecretKey.length,
      startsWith: stripeSecretKey.substring(0, 7),
      isTest: stripeSecretKey.startsWith("sk_test_"),
      isLive: stripeSecretKey.startsWith("sk_live_"),
    });

    // Opprett Stripe instance med validert key
    const stripe = new Stripe(stripeSecretKey, {
      apiVersion: "2025-02-24.acacia",
    });

    const { items, customer, discountCode, affiliateCode, shippingMethod: shippingMethodRaw } =
      earlyBody;
    const shippingMethod = normalizeShippingMethod(shippingMethodRaw);

    console.log("📦 Creating order with:", {
      itemsCount: items.length,
      customerEmail: customer.email,
    });

    // Opprett eller finn kunde
    let dbCustomer = await prisma.customer.findFirst({
      where: { email: customer.email, storeId },
    });

    if (!dbCustomer) {
      dbCustomer = await prisma.customer.create({
        data: {
          storeId,
          email: customer.email,
          name: customer.name || customer.fullName,
          phone: customer.phone || null,
          addresses: JSON.stringify([
            {
              address: customer.address || customer.address1,
              zip: customer.zip || customer.zipCode,
              city: customer.city,
            },
          ]),
        },
      });
    }

    // Hent produkter for å verifisere priser og stokk — never trust client totals
    const productIds = items.map((item: any) => String(item.productId || ""));
    const products = await safeQuery(
      () =>
        prisma.product.findMany({
          where: { id: { in: productIds }, storeId, isActive: true },
          include: { variants: true },
        }),
      [],
      "checkout:products"
    );

    const orderItemsData = [];
    const orderItemsCreate = [];
    let subtotal = 0;

    for (const item of items) {
      const product = products.find((p) => p.id === item.productId);
      if (!product) {
        return NextResponse.json(
          { error: `Et produkt i handlekurven er ikke lenger tilgjengelig` },
          { status: 400 }
        );
      }

      let variant = null;
      if (item.variantId) {
        variant = product.variants.find((v) => v.id === item.variantId && v.isActive !== false);
        if (!variant) {
          return NextResponse.json(
            { error: `En produktvariant er ikke lenger tilgjengelig` },
            { status: 400 }
          );
        }
      }

      const quantity = Math.floor(Number(item.quantity) || 0);
      const stock = variant ? variant.stock : product.stock;
      const purchase = canPurchaseQuantity({
        isActive: product.isActive !== false,
        stock,
        quantity,
      });
      if (!purchase.ok) {
        return NextResponse.json(
          { error: `${purchase.error}: «${product.name}»` },
          { status: 400 }
        );
      }

      const itemPrice = Number(variant ? variant.price : product.price);
      const variantName = item.variantName || variant?.name || null;
      const variantId = item.variantId || null;
      subtotal += itemPrice * quantity;

      orderItemsData.push({
        productId: item.productId,
        productName: product.name,
        variantId,
        variantName,
        price: itemPrice,
        quantity,
      });

      orderItemsCreate.push({
        productId: item.productId,
        variantId,
        variantName,
        quantity,
        price: itemPrice,
      });
    }

    // Server-side shipping (ignore client shippingCost / total)
    const shippingCost = computeShippingCost(subtotal, shippingMethod);
    let discountAmount = 0;
    let appliedDiscountCode: string | null = null;
    if (discountCode) {
      const now = new Date();
      const dc = await prisma.discountCode.findFirst({ where: { code: discountCode, storeId } });
      if (dc && dc.isActive !== false && (!dc.expiresAt || dc.expiresAt > now)) {
        appliedDiscountCode = dc.code;
        const percent = dc.percentOff ? dc.percentOff / 100 : 0;
        const amount = dc.amountOff ?? 0;
        const computed = subtotal * percent + amount;
        discountAmount = Math.max(0, Math.min(computed, subtotal));
      }
    }

    const grossBeforeDiscount = subtotal + shippingCost;
    const orderTotal = Math.max(0, grossBeforeDiscount - discountAmount);
    const tax = includedVatFromGross(orderTotal);

    // Opprett ordre med OrderItems
    const order = await prisma.order.create({
      data: {
        storeId,
        orderNumber: `ORD-${nanoid(8).toUpperCase()}`,
        customerId: dbCustomer.id,
        items: JSON.stringify(orderItemsData),
        subtotal,
        shippingCost,
        tax,
        total: orderTotal,
        shippingAddress: JSON.stringify({
          name: customer.name || customer.fullName,
          address: customer.address || customer.address1,
          zip: customer.zip || customer.zipCode,
          city: customer.city,
          shippingMethod: shippingMethodLabel(shippingMethod, shippingCost),
        }),
        paymentMethod: PaymentMethod.stripe,
        paymentStatus: PaymentStatus.pending,
        status: OrderStatus.pending,
        fulfillmentStatus: FulfillmentStatus.NEW,
        customerEmailStatus: "NOT_SENT",
        orderItems: {
          create: orderItemsCreate,
        },
      },
    });

    // Affiliate (kobler ordre til affiliateCode hvis gitt)
    if (affiliateCode) {
      const aff = await prisma.affiliate.findFirst({ where: { code: affiliateCode, storeId } });
      if (aff) {
        const commission = (aff.ratePercent / 100) * orderTotal;
        await prisma.affiliateOrder.create({
          data: {
            affiliateId: aff.id,
            orderId: order.id,
            commissionAmount: Math.max(0, commission),
          },
        });
      }
    }

    // Opprett Stripe PaymentIntent
    const amountCents = Math.round(orderTotal * 100);
    console.log("💳 Creating Stripe PaymentIntent with:", {
      amount: amountCents,
      currency: "nok",
      orderNumber: order.orderNumber,
      discountAmount,
      discountCode: appliedDiscountCode,
    });
    
    let paymentIntent;
    try {
      paymentIntent = await stripe.paymentIntents.create({
        amount: amountCents,
        currency: "nok",
        receipt_email: customer.email,
        metadata: {
          orderId: order.id,
          orderNumber: order.orderNumber,
          discountCode: appliedDiscountCode || "",
        },
      });
      console.log("✅ PaymentIntent created:", paymentIntent.id);
    } catch (stripeError: any) {
      console.error("❌ Stripe error details:", {
        type: stripeError.type,
        code: stripeError.code,
        message: stripeError.message,
        statusCode: stripeError.statusCode,
        raw: stripeError.raw ? {
          type: stripeError.raw.type,
          code: stripeError.raw.code,
          message: stripeError.raw.message,
        } : undefined,
      });

      // Gi mer hjelpsomme feilmeldinger basert på feiltype
      let errorMessage = "Ukjent feil ved opprettelse av betaling";
      let hint = "";
      
      if (stripeError.type === "StripeAuthenticationError" || stripeError.code === "api_key_expired" || stripeError.code === "invalid_api_key") {
        errorMessage = `Ugyldig Stripe API key. Stripe avviser key-en.`;
        hint = `Dette kan bety:
1. Key-en er feil kopiert (mangler tegn eller har ekstra tegn)
2. Key-en er fra feil Stripe konto
3. Key-en er utløpt eller deaktivert
4. Key-en har whitespace eller linjeskift

Løsning:
- Gå til Stripe Dashboard → Developers → API Keys
- Kopier Secret key på nytt (klikk "Reveal test key")
- Lim inn i .env uten mellomrom eller linjeskift
- Restart dev serveren (Ctrl+C og npm run dev)`;
      } else if (stripeError.type === "StripeInvalidRequestError") {
        errorMessage = `Stripe feil: ${stripeError.message}`;
      } else {
        errorMessage = `Stripe feil: ${stripeError.message || errorMessage}`;
      }

      // Returner mer detaljert feil til frontend
      return NextResponse.json(
        {
          error: errorMessage,
          hint: hint,
          stripeError: process.env.NODE_ENV === "development" ? {
            type: stripeError.type,
            code: stripeError.code,
            message: stripeError.message,
          } : undefined,
        },
        { status: 500 }
      );
    }

    // Oppdater ordre med paymentIntentId
    await prisma.order.update({
      where: { id: order.id },
      data: { paymentIntentId: paymentIntent.id },
    });

    console.log("✅ Payment intent created successfully for order:", order.orderNumber);
    return NextResponse.json({
      clientSecret: paymentIntent.client_secret,
      orderId: order.id,
      orderNumber: order.orderNumber,
      total: orderTotal,
      shippingCost,
      tax,
    });
  } catch (error: any) {
    console.error("❌ Error creating payment intent:", {
      message: error.message,
      stack: error.stack,
      name: error.name,
    });
    
    // Returner mer detaljert feilmelding
    const errorMessage = error.message || "Noe gikk galt ved opprettelse av betaling";
    return NextResponse.json(
      {
        error: errorMessage,
        details: process.env.NODE_ENV === "development" ? error.stack : undefined,
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";
import { logError, logInfo } from "@/lib/utils/logger";
import { requireDebugAccess } from "@/lib/api-auth";

/**
 * Debug route to inspect ALL products in database
 */
export async function GET(req: Request) {
  const denied = requireDebugAccess(req);
  if (denied) return denied;

  try {
    // Total count
    const total = await prisma.product.count();
    
    // Count by storeId
    let byStoreId: Array<{ storeId: string | null; _count: { _all: number } }> = [];
    try {
      const groupResult = await prisma.product.groupBy({
        by: ["storeId"],
        _count: { _all: true },
      });
      byStoreId = groupResult.map((item) => ({
        storeId: item.storeId,
        _count: { _all: item._count._all },
      }));
    } catch (e) {
      logError(e, "[api/debug/products-all] groupBy failed, using manual aggregation");
      const all = await prisma.product.findMany({
        select: { storeId: true },
      });
      const map = new Map<string | null, number>();
      for (const row of all) {
        const key = row.storeId ?? "null";
        map.set(key, (map.get(key) ?? 0) + 1);
      }
      byStoreId = Array.from(map.entries()).map(([storeId, count]) => ({
        storeId,
        _count: { _all: count },
      }));
    }

    // Count by isActive
    const activeCount = await prisma.product.count({ where: { isActive: true } });
    const inactiveCount = await prisma.product.count({ where: { isActive: false } });

    // Count by supplierName (to identify Temu products)
    let bySupplier: Array<{ supplierName: string | null; _count: { _all: number } }> = [];
    try {
      const groupResult = await prisma.product.groupBy({
        by: ["supplierName"],
        _count: { _all: true },
      });
      bySupplier = groupResult.map((item) => ({
        supplierName: item.supplierName,
        _count: { _all: item._count._all },
      }));
    } catch (e) {
      // Fallback if groupBy fails
      const all = await prisma.product.findMany({
        select: { supplierName: true },
      });
      const map = new Map<string | null, number>();
      for (const row of all) {
        const key = row.supplierName ?? "null";
        map.set(key, (map.get(key) ?? 0) + 1);
      }
      bySupplier = Array.from(map.entries()).map(([supplierName, count]) => ({
        supplierName,
        _count: { _all: count },
      }));
    }

    // Get sample products from each storeId
    const samplesByStore: Record<string, any[]> = {};
    for (const store of byStoreId) {
      const storeId = store.storeId ?? "null";
      const samples = await prisma.product.findMany({
        where: { storeId: store.storeId },
        select: {
          id: true,
          name: true,
          category: true,
          storeId: true,
          isActive: true,
          supplierName: true,
          supplierUrl: true,
          createdAt: true,
        },
        take: 10,
        orderBy: { createdAt: "desc" },
      });
      samplesByStore[storeId] = samples;
    }

    // Get ALL products without filters (first 50 for inspection)
    const allProductsSample = await prisma.product.findMany({
      select: {
        id: true,
        name: true,
        category: true,
        storeId: true,
        isActive: true,
        supplierName: true,
        supplierUrl: true,
        createdAt: true,
      },
      take: 50,
      orderBy: { createdAt: "desc" },
    });

    // Count Temu products specifically
    const temuCount = await prisma.product.count({
      where: {
        OR: [
          { supplierName: "temu" },
          { supplierUrl: { contains: "temu", mode: "insensitive" } },
          { sku: { startsWith: "TEMU-" } },
        ],
      },
    });

    logInfo(`Found ${total} total products (${activeCount} active, ${inactiveCount} inactive, ${temuCount} Temu)`, "[api/debug/products-all]");

    return NextResponse.json({
      ok: true,
      summary: {
        total,
        active: activeCount,
        inactive: inactiveCount,
        temu: temuCount,
      },
      byStoreId: byStoreId.map((s) => ({
        storeId: s.storeId,
        count: s._count._all,
      })),
      bySupplier: bySupplier.map((s) => ({
        supplierName: s.supplierName,
        count: s._count._all,
      })),
      samplesByStore,
      allProductsSample: allProductsSample.slice(0, 20), // Limit to 20 for readability
      recommendation: total <= 12 
        ? "Very few products found. Temu products may not be in this database."
        : total > 50 && temuCount === 0
        ? "Many products found but no Temu products. Check supplierName field."
        : "Products found. Check samplesByStore to see distribution.",
    });
  } catch (error: any) {
    logError(error, "[api/debug/products-all]");
    return NextResponse.json(
      {
        ok: false,
        error: error?.message ?? "Unknown error",
      },
      { status: 500 }
    );
  }
}

