import { decrementStockForOrder } from "@/lib/orders/inventory";
import { includedVatFromGross } from "@/lib/pricing/tax";

// Stripe instance vil bli opprettet med validert key

export async function POST(req: Request) {
  const body = await req.text();
  const headersList = await headers();
  const signature = headersList.get("stripe-signature");

  if (!signature) {
    return NextResponse.json({ error: "Missing signature" }, { status: 400 });
  }

  // Sjekk og valider Stripe keys
  // Clean and validate Stripe keys
  let stripeSecretKey = process.env.STRIPE_SECRET_KEY?.trim() || "";
  let webhookSecret = process.env.STRIPE_WEBHOOK_SECRET?.trim() || "";
  
  // Remove extra quotes if present
  stripeSecretKey = stripeSecretKey.replace(/^["']+|["']+$/g, "").trim();
  webhookSecret = webhookSecret.replace(/^["']+|["']+$/g, "").trim();

  if (!stripeSecretKey) {
    console.error("❌ STRIPE_SECRET_KEY is not set in environment variables");
    return NextResponse.json(
      { error: "Betalingssystemet er ikke konfigurert." },
      { status: 500 }
    );
  }

  if (!webhookSecret) {
    console.error("❌ STRIPE_WEBHOOK_SECRET is not set in environment variables");
    return NextResponse.json(
      { error: "Betalingssystemet er ikke konfigurert." },
      { status: 500 }
    );
  }

  // Valider at Stripe secret key har riktig format
  if (!stripeSecretKey.startsWith("sk_test_") && !stripeSecretKey.startsWith("sk_live_")) {
    console.error("❌ STRIPE_SECRET_KEY has invalid format");
    return NextResponse.json(
      {
        error: "Betalingssystemet er ikke konfigurert.",
      },
      { status: 500 }
    );
  }

  // Opprett Stripe instance med validert key
  const stripe = new Stripe(stripeSecretKey, {
    apiVersion: "2025-02-24.acacia",
  });

  let event: Stripe.Event;

  try {
    event = stripe.webhooks.constructEvent(
      body,
      signature,
      webhookSecret
    );
  } catch (err: any) {
    console.error("Webhook signature verification failed:", err.message);
    return NextResponse.json({ error: `Webhook Error: ${err.message}` }, { status: 400 });
  }

  try {
    switch (event.type) {
      case "checkout.session.completed":
        const session = event.data.object as Stripe.Checkout.Session;
        const sessionOrderId = session.metadata?.orderId;
        
        // Prevent duplicate orders: check if order already exists by session ID
        let existingOrder = await prisma.order.findFirst({
          where: { stripeSessionId: session.id },
        });

        if (existingOrder) {
          const wasUnpaid = existingOrder.paymentStatus !== "paid";
          // Order already exists, just update it
          await prisma.order.update({
            where: { id: existingOrder.id },
            data: {
              paymentStatus: "paid",
              status: "pending", // Keep for backward compatibility
              fulfillmentStatus: "NEW", // Single source of truth
              paymentIntentId: session.payment_intent as string || undefined,
              customerEmail: session.customer_email || undefined,
            },
          });
          if (wasUnpaid) {
            await decrementStockForOrder(existingOrder.id).catch((err) =>
              console.error("❌ Stock decrement failed:", err)
            );
          }
          console.log("✅ Checkout session completed - updated existing order:", existingOrder.id);
          
          // Send emails (non-blocking, updates status in DB)
          sendOrderConfirmation(existingOrder.id).then((result) => {
            if (!result.success) {
              console.error("❌ Failed to send order confirmation:", result.error);
            }
          }).catch((err) => {
            console.error("❌ Error in sendOrderConfirmation:", err);
          });
          
          sendAdminNotification(existingOrder.id).then((result) => {
            if (!result.success) {
              console.error("❌ Failed to send admin notification:", result.error);
            }
          }).catch((err) => {
            console.error("❌ Error in sendAdminNotification:", err);
          });
          break;
        }

        if (sessionOrderId) {
          // Update order with session ID and mark as paid
          existingOrder = await prisma.order.findUnique({
            where: { id: sessionOrderId },
          });

          if (existingOrder) {
            const wasUnpaid = existingOrder.paymentStatus !== "paid";
            await prisma.order.update({
              where: { id: sessionOrderId },
              data: {
                paymentStatus: "paid",
                status: "pending", // Keep for backward compatibility
                fulfillmentStatus: "NEW", // Single source of truth
                paymentIntentId: session.payment_intent as string || undefined,
                stripeSessionId: session.id,
                customerEmail: session.customer_email || undefined,
              },
            });

            if (wasUnpaid) {
              await decrementStockForOrder(sessionOrderId).catch((err) =>
                console.error("❌ Stock decrement failed:", err)
              );
            }

            // Get order for risk evaluation
            const order = await prisma.order.findUnique({
              where: { id: sessionOrderId },
              include: { customer: true },
            });

            if (order) {
              const dropshipCfg = getDropshippingConfig();
              const sendAnywayOnHighRisk = dropshipCfg.sendAnywayOnHighRisk ?? false;

              // Risk evaluation
              const risk = await evaluateOrderRisk(sessionOrderId);
              await prisma.order.update({
                where: { id: sessionOrderId },
                data: {
                  riskScore: risk.riskScore,
                  isFlaggedForReview: risk.isFlagged,
                } as any,
              });

              // Send emails (non-blocking, updates status in DB)
              sendOrderConfirmation(sessionOrderId).then((result) => {
                if (!result.success) {
                  console.error("❌ Failed to send order confirmation:", result.error);
                }
              }).catch((err) => {
                console.error("❌ Error in sendOrderConfirmation:", err);
              });
              
              sendAdminNotification(sessionOrderId).then((result) => {
                if (!result.success) {
                  console.error("❌ Failed to send admin notification:", result.error);
                }
              }).catch((err) => {
                console.error("❌ Error in sendAdminNotification:", err);
              });

              // Manual fulfillment: DO NOT automatically send to supplier
              // Admin will manually process orders
              console.log("✅ Checkout session completed for order (manual fulfillment):", sessionOrderId);
            }
          }
        } else {
          // No orderId in metadata and no existing order - create order from session
          // This handles cases where checkout was created directly via Stripe Checkout
          try {
            // Retrieve full session with line items
            const fullSession = await stripe.checkout.sessions.retrieve(session.id, {
              expand: ['line_items', 'line_items.data.price.product', 'customer'],
            });

            if (!fullSession.line_items?.data || fullSession.line_items.data.length === 0) {
              console.warn("⚠️ Checkout session has no line items, cannot create order");
              break;
            }

            // Extract customer info
            const customerEmail = session.customer_email || (fullSession.customer_details?.email);
            const customerName = fullSession.customer_details?.name || "Kunde";
            const shippingAddress = fullSession.shipping_details?.address;

            if (!customerEmail) {
              console.warn("⚠️ Checkout session has no customer email, cannot create order");
              break;
            }

            // Get or create customer
            const storeId = await getStoreIdFromHeadersServer().catch(() => null);
            let customer = await prisma.customer.findFirst({
              where: { email: customerEmail, storeId: storeId || undefined },
            });

            if (!customer) {
              customer = await prisma.customer.create({
                data: {
                  storeId: storeId || undefined,
                  email: customerEmail,
                  name: customerName,
                  phone: fullSession.customer_details?.phone || null,
                  addresses: shippingAddress ? JSON.stringify([{
                    address: shippingAddress.line1 || "",
                    address2: shippingAddress.line2 || "",
                    zip: shippingAddress.postal_code || "",
                    city: shippingAddress.city || "",
                    country: shippingAddress.country || "NO",
                  }]) : undefined,
                },
              });
            }

            // Build order items from line items
            const orderItemsData: any[] = [];
            const orderItemsCreate: any[] = [];
            let subtotal = 0;

            for (const lineItem of fullSession.line_items.data) {
              const productId = lineItem.price?.metadata?.productId || lineItem.price?.product as string;
              const productName = lineItem.description || "Produkt";
              const quantity = lineItem.quantity || 1;
              const unitPrice = (lineItem.price?.unit_amount || 0) / 100; // Convert from cents
              const lineTotal = unitPrice * quantity;
              subtotal += lineTotal;

              orderItemsData.push({
                productId: productId || "unknown",
                name: productName,
                quantity,
                price: unitPrice,
              });

              // Try to find product in database
              if (productId && productId !== "unknown") {
                const product = await prisma.product.findUnique({
                  where: { id: productId },
                });

                if (product) {
                  orderItemsCreate.push({
                    productId: product.id,
                    quantity,
                    price: unitPrice,
                  });
                }
              }
            }

            const shippingCost = (fullSession.shipping_cost?.amount_total || 0) / 100;
            const total = (fullSession.amount_total || 0) / 100;
            const tax = includedVatFromGross(total);

            // Create order
            const { nanoid } = await import("nanoid");
            const newOrder = await prisma.order.create({
              data: {
                storeId: storeId || undefined,
                orderNumber: `ORD-${nanoid(8).toUpperCase()}`,
                customerId: customer.id,
                items: JSON.stringify(orderItemsData),
                subtotal: subtotal,
                shippingCost: shippingCost,
                tax,
                total: total,
                shippingAddress: shippingAddress ? JSON.stringify({
                  name: customerName,
                  address: shippingAddress.line1 || "",
                  address2: shippingAddress.line2 || "",
                  zip: shippingAddress.postal_code || "",
                  city: shippingAddress.city || "",
                  country: shippingAddress.country || "NO",
                }) : JSON.stringify({}),
                paymentMethod: "stripe",
                paymentStatus: "paid",
                status: "pending", // Keep for backward compatibility
                fulfillmentStatus: "NEW", // Single source of truth
                paymentIntentId: session.payment_intent as string || undefined,
                stripeSessionId: session.id,
                customerEmail: customerEmail,
                customerEmailStatus: "NOT_SENT", // Will be updated by email function
                orderItems: orderItemsCreate.length > 0 ? {
                  create: orderItemsCreate,
                } : undefined,
              },
            });

            console.log("✅ Created order from checkout session (manual fulfillment):", newOrder.id);

            await decrementStockForOrder(newOrder.id).catch((err) =>
              console.error("❌ Stock decrement failed:", err)
            );

            // Send emails (non-blocking, updates status in DB)
            // IMPORTANT: Order creation succeeded, so we return 200 even if emails fail
            sendOrderConfirmation(newOrder.id).then((result) => {
              if (!result.success) {
                console.error("❌ Failed to send order confirmation:", result.error);
              }
            }).catch((err) => {
              console.error("❌ Error in sendOrderConfirmation:", err);
            });
            
            sendAdminNotification(newOrder.id).then((result) => {
              if (!result.success) {
                console.error("❌ Failed to send admin notification:", result.error);
              }
            }).catch((err) => {
              console.error("❌ Error in sendAdminNotification:", err);
            });
          } catch (createError: any) {
            console.error("❌ Error creating order from checkout session:", createError);
            // Don't throw - webhook should still return success to Stripe
          }
        }
        break;

      case "payment_intent.succeeded":
        const paymentIntent = event.data.object as Stripe.PaymentIntent;
        const orderId = paymentIntent.metadata.orderId;

        if (orderId) {
          const dropshipCfg = getDropshippingConfig();
          const sendAnywayOnHighRisk = dropshipCfg.sendAnywayOnHighRisk ?? false;
          const prior = await prisma.order.findUnique({ where: { id: orderId } });
          const wasUnpaid = prior?.paymentStatus !== "paid";

          // Oppdater ordre status
          await prisma.order.update({
            where: { id: orderId },
            data: {
              paymentStatus: "paid",
              status: "processing", // Keep for backward compatibility
              fulfillmentStatus: "NEW", // Single source of truth - manual fulfillment
            },
          });

          if (wasUnpaid) {
            await decrementStockForOrder(orderId).catch((err) =>
              console.error("❌ Stock decrement failed:", err)
            );
          }

          // Risk-evaluering før vi sender til leverandør
          const risk = await evaluateOrderRisk(orderId);
          await prisma.order.update({
            where: { id: orderId },
            data: {
              riskScore: risk.riskScore,
              isFlaggedForReview: risk.isFlagged,
            } as any,
          });

          // Send e-poster (non-blocking, updates status in DB)
          sendOrderConfirmation(orderId).then((result) => {
            if (!result.success) {
              console.error("❌ Failed to send order confirmation:", result.error);
            }
          }).catch((err) => {
            console.error("❌ Error in sendOrderConfirmation:", err);
          });

          sendAdminNotification(orderId).then((result) => {
            if (!result.success) {
              console.error("❌ Failed to send admin notification:", result.error);
            }
          }).catch((err) => {
            console.error("❌ Error in sendAdminNotification:", err);
          });

          // Manual fulfillment: DO NOT automatically send to supplier
          // Admin will manually process orders
          console.log("✅ Payment succeeded for order (manual fulfillment):", orderId);
        }
        break;

      case "payment_intent.payment_failed":
        const failedPayment = event.data.object as Stripe.PaymentIntent;
        const failedOrderId = failedPayment.metadata.orderId;

        if (failedOrderId) {
          await prisma.order.update({
            where: { id: failedOrderId },
            data: {
              paymentStatus: "failed",
              status: "cancelled",
            },
          });

          // AutomationLog model ikke tilgjengelig i schema
          // await prisma.automationLog.create({
          //   data: {
          //     type: "order",
          //     orderId: failedOrderId,
          //     action: "failed",
          //     error: failedPayment.last_payment_error?.message || "Payment failed",
          //   },
          // });
        }
        break;

      default:
        console.log(`Unhandled event type: ${event.type}`);
    }

    return NextResponse.json({ received: true });
  } catch (error: any) {
    console.error("Error processing webhook:", error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { z } from "zod";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { loadStripe } from "@stripe/stripe-js";
import { Elements, PaymentElement, useStripe, useElements } from "@stripe/react-stripe-js";
import { useCart } from "@/lib/cart-context";
import { formatCurrency } from "@/lib/format";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import Link from "next/link";
import { SITE_CONFIG } from "@/lib/site";

// Håndter Stripe publishable key med ekstra anførselstegn
const getStripeKey = () => {
  let key = process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY?.trim() || "";
  // Fjern ekstra anførselstegn hvis de er der
  key = key.replace(/^["']+|["']+$/g, "").trim();
  return key || null;
};

const stripePromise = getStripeKey() ? loadStripe(getStripeKey()!) : null;

const infoSchema = z.object({
  email: z.string().email("Ugyldig e-post"),
  fullName: z.string().min(2, "Navn er påkrevd"),
  phone: z.string().optional().refine((val) => !val || val.length >= 8, {
    message: "Telefonnummer må være minst 8 siffer",
  }),
});

const addressSchema = z.object({
  address1: z.string().min(3, "Adresse er påkrevd"),
  address2: z.string().optional(),
  zipCode: z.string().min(4, "Postnummer er påkrevd"),
  city: z.string().min(2, "By er påkrevd"),
  country: z.string().default("NO"),
});

type InfoData = z.infer<typeof infoSchema>;
type AddressData = {
  address1: string;
  address2?: string;
  zipCode: string;
  city: string;
  country: string;
};

function CheckoutForm({ clientSecret }: { clientSecret: string }) {
  const stripe = useStripe();
  const elements = useElements();
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!stripe || !elements) {
      setError("Stripe er ikke klar. Vent litt...");
      return;
    }

    setLoading(true);
    setError("");

    const { error: submitError } = await stripe.confirmPayment({
      elements,
      confirmParams: {
        return_url: `${window.location.origin}/order-confirmation`,
      },
    });

    if (submitError) {
      setError(submitError.message || "Noe gikk galt ved betaling");
      setLoading(false);
    }
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-6">
      <PaymentElement />
      
      {error && (
        <div className="rounded-lg bg-red-50 p-3 text-sm text-red-600">
          {error}
        </div>
      )}

      <Button
        type="submit"
        disabled={!stripe || loading}
        className="w-full"
      >
        {loading ? "Behandler..." : "Betal nå"}
      </Button>
    </form>
  );
}

export default function CheckoutPage() {
  const [step, setStep] = useState(1);
  const [shippingMethod, setShippingMethod] = useState<"standard" | "express">("standard");
  const [paymentMethod, setPaymentMethod] = useState("card");
  const [clientSecret, setClientSecret] = useState<string | null>(null);
  const [orderId, setOrderId] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [discountCode, setDiscountCode] = useState("");
  const [discountAmount, setDiscountAmount] = useState(0);
  const [discountMessage, setDiscountMessage] = useState<string | null>(null);
  const [affiliateCode, setAffiliateCode] = useState<string | null>(null);
  const [stripeKeyStatus, setStripeKeyStatus] = useState<"checking" | "ok" | "missing">("checking");
  const router = useRouter();
  const { items, total, clearCart } = useCart();

  // Verifiser Stripe keys ved mount
  useEffect(() => {
    let publishableKey = process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY?.trim() || "";
    
    // Fjern ekstra anførselstegn hvis de er der (f.eks. ""pk_test_..."")
    // Dette skjer hvis man har ekstra anførselstegn i .env filen
    publishableKey = publishableKey.replace(/^["']+|["']+$/g, "");
    publishableKey = publishableKey.trim();
    
    // Debug logging for development
    if (process.env.NODE_ENV === "development") {
      console.log("🔍 Checking Stripe keys:", {
        hasKey: !!publishableKey,
        keyLength: publishableKey?.length || 0,
        firstChars: publishableKey?.substring(0, 20) || "undefined",
      });
    }
    
    if (publishableKey && (publishableKey.startsWith("pk_test_") || publishableKey.startsWith("pk_live_"))) {
      setStripeKeyStatus("ok");
      console.log("✅ Stripe publishable key found:", publishableKey.substring(0, 20) + "...");
    } else {
      setStripeKeyStatus("missing");
      console.error("❌ NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY is missing or invalid");
      console.error("Expected format: pk_test_... or pk_live_...");
      
      if (!publishableKey) {
        console.error("💡 Troubleshooting:");
        console.error("1. Sjekk at .env filen er i prosjektets rotmappe (dropshipping-upgrade/.env)");
        console.error("2. Sjekk at variabelen heter EXAKT: NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY");
        console.error("3. RESTART dev serveren (Ctrl+C og npm run dev) - Next.js leser .env kun ved oppstart!");
        console.error("4. Sjekk at det ikke er mellomrom eller linjeskift i key-en");
        console.error("5. Sjekk at du har ÉTT sett anførselstegn rundt key-en: \"pk_test_...\"");
      } else {
        console.error(`💡 Key-en finnes men har feil format. Startet med: "${publishableKey.substring(0, 15)}"`);
        console.error("   Forventet format: pk_test_... eller pk_live_...");
        console.error("   💡 Tips: Sjekk om du har ekstra anførselstegn i .env filen");
        console.error("   Riktig: NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY=\"pk_test_...\"");
        console.error("   Feil: NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY=\"\"pk_test_...\"\"");
      }
    }
  }, []);

  const infoForm = useForm<InfoData>({
    resolver: zodResolver(infoSchema),
  });

  const addressForm = useForm({
    resolver: zodResolver(addressSchema),
    defaultValues: { country: "NO" },
  });

  const shippingCost = shippingMethod === "standard" ? (total >= 500 ? 0 : 99) : 199;
  const grandTotal = Math.max(0, total + shippingCost - discountAmount);

  useEffect(() => {
    if (items.length === 0) {
      router.push("/cart");
      return;
    }
  }, [items, router]);

  // Show friendly error if cart is empty
  if (items.length === 0) {
    return (
      <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8 py-12 text-center">
        <h1 className="mb-4 text-2xl font-bold text-gray-900">Handlekurven er tom</h1>
        <p className="mb-6 text-gray-600">Du må legge til produkter i handlekurven før du kan gå til kassen.</p>
        <Link
          href="/products"
          className="inline-block rounded-lg bg-green-600 px-6 py-3 font-semibold text-white hover:bg-green-700 transition-colors"
        >
          Se produkter
        </Link>
      </div>
    );
  }

  // Hent affiliateCode fra cookie hvis satt
  useEffect(() => {
    if (typeof document === "undefined") return;
    const match = document.cookie.split("; ").find((row) => row.startsWith("affiliateCode="));
    if (match) {
      setAffiliateCode(match.split("=")[1] || null);
    }
  }, []);

  const handleInfoSubmit = async (data: InfoData) => {
    setStep(2);
  };

  const handleAddressSubmit = async (data: any) => {
    // Ensure country is set
    const addressData: AddressData = {
      ...data,
      country: data.country || "NO",
    };
    setStep(3);
  };

  const applyDiscount = async () => {
    setDiscountMessage(null);
    setDiscountAmount(0);
    const code = discountCode.trim();
    if (!code) return;
    try {
      const res = await fetch("/api/discounts/validate", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code }),
      });
      const data = await res.json();
      if (!data.valid) {
        setDiscountMessage("Rabattkode er ugyldig eller utløpt.");
        setDiscountAmount(0);
        return;
      }
      const percent = data.percentOff ? data.percentOff / 100 : 0;
      const amount = data.amountOff ?? 0;
      const computed = total * percent + amount;
      const capped = Math.max(0, Math.min(computed, total));
      setDiscountAmount(capped);
      setDiscountMessage(`Rabattkode aktivert: -${capped.toFixed(0)} kr`);
    } catch (e) {
      setDiscountMessage("Kunne ikke validere rabattkode.");
    }
  };

  const handleShippingMethod = () => {
    setStep(4);
  };

  const handlePaymentMethod = async () => {
    // Sjekk Stripe keys
    if (stripeKeyStatus === "missing" || !process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY) {
      const errorMsg =
        "Stripe er ikke konfigurert. NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY mangler i .env filen.\n\n" +
        "Vennligst legg til:\n" +
        "NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY=pk_test_...\n" +
        "STRIPE_SECRET_KEY=sk_test_...";
      setError(errorMsg);
      console.error("❌ NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY is not set");
      return;
    }

    if (paymentMethod !== "card") {
      // For andre betalingsmetoder, gå direkte til bekreftelse
      // Dette kan utvides senere
      clearCart();
      router.push("/order-confirmation");
      return;
    }

    // For Stripe (card payment)
    setLoading(true);
    setError(null);

    try {
      const infoData = infoForm.getValues();
      const addressData = addressForm.getValues();


      // Valider at vi har all nødvendig data
      if (!infoData.email || !infoData.fullName) {
        throw new Error("Manglende kundeinformasjon");
      }
      if (!addressData.address1 || !addressData.zipCode || !addressData.city) {
        throw new Error("Manglende leveringsadresse");
      }
      if (items.length === 0) {
        throw new Error("Handlekurven er tom");
      }

      const response = await fetch("/api/checkout/create-payment-intent", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          items,
          customer: {
            email: infoData.email,
            name: infoData.fullName,
            fullName: infoData.fullName,
            phone: infoData.phone,
            address: addressData.address1,
            address1: addressData.address1,
            address2: addressData.address2,
            zip: addressData.zipCode,
            zipCode: addressData.zipCode,
            city: addressData.city,
            country: addressData.country,
          },
          total: grandTotal,
          shippingCost,
          shippingMethod,
          discountCode: discountCode.trim() || undefined,
          affiliateCode: affiliateCode || undefined,
        }),
      });

      const data = await response.json();

      if (!response.ok) {
        console.error("❌ API Error:", {
          status: response.status,
          statusText: response.statusText,
          error: data.error,
          details: data.details,
        });
        throw new Error(
          data.error || `Kunne ikke opprette betaling (${response.status}: ${response.statusText})`
        );
      }

      if (!data.clientSecret) {
        console.error("❌ No clientSecret in response:", data);
        throw new Error(
          data.error || "Mottok ikke betalingsnøkkel fra server. Prøv igjen eller kontakt kundeservice."
        );
      }


      setClientSecret(data.clientSecret);
      setOrderId(data.orderId);
      setStep(5); // Gå til Stripe PaymentElement
      setError(null);
    } catch (error: any) {
      console.error("❌ Error creating payment intent:", {
        message: error.message,
        stack: error.stack,
        name: error.name,
      });
      setError(
        `Feil ved opprettelse av betaling: ${error.message || "Noe gikk galt. Prøv igjen."}`
      );
    } finally {
      setLoading(false);
    }
  };

  if (items.length === 0) {
    return null;
  }

  return (
    <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8 py-6 sm:py-8 lg:py-10">
      <h1 className="mb-6 text-2xl sm:text-3xl font-bold text-gray-900">Checkout</h1>
      <div className="mb-8 flex flex-wrap items-center gap-2 sm:gap-4 text-xs sm:text-sm font-medium">
        {["Informasjon", "Levering", "Leveringsmetode", "Betaling", "Bekreftelse"].map((label, index) => (
          <div key={label} className="flex items-center gap-2">
            <span
              className={`flex h-8 w-8 items-center justify-center rounded-full border-2 font-semibold transition-all ${
                step > index + 1
                  ? "border-green-600 bg-green-600 text-white"
                  : step === index + 1
                    ? "border-green-600 bg-green-50 text-green-600"
                    : "border-gray-300 bg-white text-gray-400"
              }`}
            >
              {index + 1}
            </span>
            <span className={`hidden sm:inline ${step === index + 1 ? "text-green-600 font-semibold" : step > index + 1 ? "text-gray-600" : "text-gray-400"}`}>{label}</span>
          </div>
        ))}
      </div>

      <div className="grid gap-6 lg:gap-8 lg:grid-cols-[1.2fr,0.8fr]">
        <div className="space-y-6">
          {/* Rabattkode */}
          <div className="rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm space-y-3">
            <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Rabattkode</h2>
            <p className="text-sm text-gray-600">Har du en kode? Legg den inn her.</p>
            <div className="flex gap-2">
              <Input
                value={discountCode}
                onChange={(e) => setDiscountCode(e.target.value)}
                placeholder="Rabattkode"
                className="flex-1"
              />
              <Button type="button" onClick={applyDiscount} className="bg-green-600 hover:bg-green-700 text-white">
                Aktiver
              </Button>
            </div>
            {discountMessage && <p className="text-sm text-green-700 font-medium">{discountMessage}</p>}
          </div>
          {step === 1 && (
            <form
              className="rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm space-y-4"
              onSubmit={infoForm.handleSubmit(handleInfoSubmit)}
            >
              <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Kundeinformasjon</h2>
              <Input
                type="email"
                placeholder="E-post *"
                {...infoForm.register("email")}
              />
              {infoForm.formState.errors.email && (
                <p className="text-sm text-danger">{infoForm.formState.errors.email.message}</p>
              )}
              <Input
                type="text"
                placeholder="Fullt navn *"
                {...infoForm.register("fullName")}
              />
              {infoForm.formState.errors.fullName && (
                <p className="text-sm text-danger">{infoForm.formState.errors.fullName.message}</p>
              )}
              <Input
                type="tel"
                placeholder="Telefon"
                {...infoForm.register("phone")}
              />
              <Button type="submit" className="w-full bg-green-600 hover:bg-green-700 text-white">
                Fortsett til levering
              </Button>
            </form>
          )}

          {step === 2 && (
            <form
              className="rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm space-y-4"
              onSubmit={addressForm.handleSubmit(handleAddressSubmit)}
            >
              <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Leveringsadresse</h2>
              <Input
                type="text"
                placeholder="Adresse *"
                {...addressForm.register("address1")}
              />
              {addressForm.formState.errors.address1 && (
                <p className="text-sm text-danger">{addressForm.formState.errors.address1.message}</p>
              )}
              <Input
                type="text"
                placeholder="Adresselinje 2 (valgfritt)"
                {...addressForm.register("address2")}
              />
              <div className="grid gap-4 md:grid-cols-2">
                <div>
                  <Input
                    type="text"
                    placeholder="Postnummer *"
                    {...addressForm.register("zipCode")}
                  />
                  {addressForm.formState.errors.zipCode && (
                    <p className="text-sm text-danger">{addressForm.formState.errors.zipCode.message}</p>
                  )}
                </div>
                <div>
                  <Input
                    type="text"
                    placeholder="By *"
                    {...addressForm.register("city")}
                  />
                  {addressForm.formState.errors.city && (
                    <p className="text-sm text-danger">{addressForm.formState.errors.city.message}</p>
                  )}
                </div>
              </div>
              <select
                className="w-full rounded-lg border px-3 py-2"
                {...addressForm.register("country")}
              >
                <option value="NO">Norge</option>
                <option value="SE">Sverige</option>
                <option value="DK">Danmark</option>
              </select>
              <Button type="submit" className="w-full bg-green-600 hover:bg-green-700 text-white">
                Fortsett til leveringsmetode
              </Button>
            </form>
          )}

          {step === 3 && (
            <div className="space-y-4 rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm">
              <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Leveringsmetode</h2>
              <div className="space-y-3">
                <label className="flex cursor-pointer items-center gap-3 rounded-2xl border p-4">
                  <input
                    type="radio"
                    checked={shippingMethod === "standard"}
                    onChange={() => setShippingMethod("standard")}
                  />
                  <div>
                    <p className="font-semibold text-slate-900">
                      Standard (5-7 dager) - Gratis over 500 kr
                    </p>
                    <p className="text-sm text-secondary">Sendes med Posten</p>
                  </div>
                </label>
                <label className="flex cursor-pointer items-center gap-3 rounded-2xl border p-4">
                  <input
                    type="radio"
                    checked={shippingMethod === "express"}
                    onChange={() => setShippingMethod("express")}
                  />
                  <div>
                    <p className="font-semibold text-slate-900">Express (2-3 dager) - 99 kr</p>
                    <p className="text-sm text-secondary">Prioritert levering</p>
                  </div>
                </label>
              </div>
              <Button className="w-full bg-green-600 hover:bg-green-700 text-white" onClick={handleShippingMethod}>
                Fortsett til betaling
              </Button>
            </div>
          )}

          {step === 4 && (
            <div className="space-y-4 rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm">
              <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Betaling</h2>
              
              {error && (
                <div className="rounded-lg bg-red-50 p-4 text-sm text-red-600 whitespace-pre-line">
                  {error}
                </div>
              )}

              {stripeKeyStatus === "missing" && (
                <div className="rounded-lg bg-yellow-50 p-4 text-sm text-yellow-600">
                  ⚠️ Stripe er ikke konfigurert. NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY mangler i .env filen.
                </div>
              )}

              <div className="space-y-3">
                {[
                  { value: "card", label: "Kort (Visa/Mastercard)", available: true },
                  { value: "vipps", label: "Vipps", available: false },
                  { value: "klarna", label: "Klarna", available: false },
                ].map((option) => (
                  <label
                    key={option.value}
                    className={`flex cursor-pointer items-center gap-3 rounded-2xl border p-4 ${
                      !option.available ? "opacity-50 cursor-not-allowed" : ""
                    }`}
                  >
                    <input
                      type="radio"
                      checked={paymentMethod === option.value}
                      onChange={() => option.available && setPaymentMethod(option.value)}
                      disabled={!option.available}
                    />
                    <span className="font-semibold text-slate-900">
                      {option.label}
                      {!option.available && " (Kommer snart)"}
                    </span>
                  </label>
                ))}
              </div>
              <Button
                className="w-full bg-green-600 hover:bg-green-700 text-white disabled:opacity-50"
                onClick={handlePaymentMethod}
                disabled={loading || stripeKeyStatus === "missing" || paymentMethod !== "card"}
              >
                {loading ? (
                  <>
                    <span className="mr-2">⏳</span>
                    Oppretter betaling...
                  </>
                ) : (
                  "Fortsett til betalingsformular"
                )}
              </Button>
            </div>
          )}

          {step === 5 && clientSecret && (
            <div className="rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm">
              <h2 className="mb-4 text-lg sm:text-xl font-semibold text-gray-900">Betal med kort</h2>
              {!stripePromise ? (
                <div className="rounded-lg bg-red-50 p-4 text-red-600">
                  ❌ Stripe er ikke konfigurert. NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY mangler.
                  <p className="mt-2 text-sm">
                    Vennligst legg til Stripe keys i .env filen og start serveren på nytt.
                  </p>
                </div>
              ) : (
                <Elements
                  stripe={stripePromise}
                  options={{
                    clientSecret,
                    appearance: {
                      theme: "stripe",
                    },
                    locale: "no",
                  }}
                >
                  {getStripeKey()?.startsWith("pk_test_") && (
                  <div className="mb-4 rounded-lg bg-green-900/20 border border-green-600 p-4 text-sm text-green-400">
                    <strong>Test kort:</strong> 4242 4242 4242 4242<br />
                    CVV: 123 | Utløpsdato: Hvilken som helst fremtidig dato
                  </div>
                  )}
                  <CheckoutForm clientSecret={clientSecret} />
                </Elements>
              )}
            </div>
          )}
        </div>

        <aside className="lg:sticky lg:top-24 space-y-4 rounded-xl border border-gray-200 bg-white p-5 sm:p-6 shadow-sm h-fit">
          <h2 className="text-lg sm:text-xl font-semibold text-gray-900">Ordresammendrag</h2>
          <div className="rounded-lg border bg-gray-50 p-3 text-sm space-y-2">
            <label className="block text-sm font-medium text-slate-800">Rabattkode</label>
            <input
              value={discountCode}
              onChange={(e) => setDiscountCode(e.target.value)}
              placeholder="Rabattkode (valgfritt)"
              className="w-full rounded-lg border border-gray-300 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
            />
          </div>
          <div className="space-y-4">
            {items.map((item) => (
              <div key={item.productId} className="flex items-center justify-between text-sm">
                <div>
                  <p className="font-semibold text-slate-900">{item.name}</p>
                  <p className="text-secondary">x {item.quantity}</p>
                </div>
                <p className="font-semibold">{formatCurrency(item.price * item.quantity)}</p>
              </div>
            ))}
          </div>
          <div className="space-y-2 border-t pt-4 text-sm text-secondary">
            <div className="flex justify-between">
              <span>Subtotal</span>
              <span>{formatCurrency(total)}</span>
            </div>
            <div className="flex justify-between">
              <span>Frakt</span>
              <span>{shippingCost === 0 ? "Gratis" : formatCurrency(shippingCost)}</span>
            </div>
              {discountAmount > 0 && (
                <div className="flex justify-between text-green-700 font-semibold">
                  <span>Rabatt</span>
                  <span>-{formatCurrency(discountAmount)}</span>
                </div>
              )}
            {total < SITE_CONFIG.freeShippingThreshold && (
              <p className="text-xs text-green-600 font-medium">
                ✨ Kjøp for {(SITE_CONFIG.freeShippingThreshold - total).toLocaleString('no-NO')},- mer og få gratis frakt!
              </p>
            )}
            {total >= SITE_CONFIG.freeShippingThreshold && shippingCost === 0 && (
              <p className="text-xs text-green-600 font-medium">
                ✓ Gratis frakt!
              </p>
            )}
            <div className="flex justify-between border-t pt-2 text-lg font-semibold text-slate-900">
              <span>Total</span>
              <span>{formatCurrency(grandTotal)}</span>
            </div>
            <p className="text-xs text-secondary">Alle priser er inkl. 25% mva</p>
              {discountMessage && (
                <p className="text-xs text-green-700">{discountMessage}</p>
              )}
          </div>
        </aside>
      </div>
    </div>
  );
}

"use client";

import { useSearchParams } from 'next/navigation';
import { useEffect, useState } from 'react';
import Link from 'next/link';
import { CheckCircle, Package, Mail, ArrowRight } from 'lucide-react';
import { useCart } from '@/lib/cart-context';

interface Order {
  id: string;
  orderNumber: string;
  customer: {
    name: string | null;
    email: string | null;
  } | null;
  items: any[];
  total: number;
  shippingAddress: any;
  createdAt: string;
  paymentStatus?: string;
  fulfillmentStatus?: string;
  trackingNumber?: string | null;
  trackingUrl?: string | null;
  customerEmailStatus?: string;
}

export default function OrderConfirmationClient() {
  const searchParams = useSearchParams();
  const paymentIntentId = searchParams.get('payment_intent');
  const sessionId = searchParams.get('session_id');
  const [order, setOrder] = useState<Order | null>(null);
  const [loading, setLoading] = useState(true);
  const { clearCart } = useCart();

  useEffect(() => {
    const fetchOrder = async () => {
      if (!sessionId && !paymentIntentId) {
        setLoading(false);
        return;
      }

      try {
        let response: Response | undefined;
        if (sessionId) {
          response = await fetch(`/api/orders/by-session?sessionId=${encodeURIComponent(sessionId)}`);
        } else if (paymentIntentId) {
          response = await fetch(
            `/api/orders/by-payment-intent?paymentIntentId=${encodeURIComponent(paymentIntentId)}`
          );
        }

        if (response && response.ok) {
          const data = await response.json();
          setOrder(data);
          // Cart clear only after we confirmed the order exists
          clearCart();
        }
      } catch (error) {
        console.error('Error fetching order:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchOrder();
    // eslint-disable-next-line react-hooks/exhaustive-deps -- clearCart is stable enough; avoid re-fetch loops
  }, [paymentIntentId, sessionId]);

  if (loading) {
    return (
      <div className="flex min-h-screen items-center justify-center">
        <div className="text-center">
          <div className="mx-auto h-16 w-16 animate-spin rounded-full border-4 border-green-600 border-t-transparent"></div>
          <p className="mt-4 text-lg text-slate-600">Behandler din ordre...</p>
        </div>
      </div>
    );
  }

  if (!order) {
    return (
      <div className="container mx-auto px-4 py-16">
        <div className="mx-auto max-w-2xl text-center">
          <h1 className="mb-4 text-3xl font-bold text-white">Ordre ikke funnet</h1>
          <p className="mb-8 text-gray-300">
            Betalingen kan fortsatt behandles. Sjekk e-posten din om noen minutter, eller kontakt
            kundeservice med kvitteringen fra Stripe.
          </p>
          <Link href="/kundeservice" className="inline-block rounded-lg bg-green-600 px-6 py-3 text-white hover:bg-green-700 mr-3">
            Kundeservice
          </Link>
          <Link href="/" className="inline-block rounded-lg border border-green-600 px-6 py-3 text-white hover:bg-green-700/20">
            Til forsiden
          </Link>
        </div>
      </div>
    );
  }

  let items: any[] = [];
  let shippingAddress: any = {};

  try {
    if (typeof order.items === 'string') {
      items = JSON.parse(order.items);
    } else if (Array.isArray(order.items)) {
      items = order.items;
    }

    if (typeof order.shippingAddress === 'string') {
      shippingAddress = JSON.parse(order.shippingAddress);
    } else if (order.shippingAddress) {
      shippingAddress = order.shippingAddress;
    }
  } catch (error) {
    console.error('Error parsing order data:', error);
  }

  const customerEmail = order.customer?.email || null;
  const customerName = order.customer?.name || shippingAddress?.name || 'Kunde';

  return (
    <div className="min-h-screen bg-gradient-to-b from-black to-gray-900 py-12">
      <div className="container mx-auto px-4">
        <div className="mx-auto max-w-3xl">
          <div className="mb-8 text-center">
            <div className="mx-auto mb-4 flex h-20 w-20 items-center justify-center rounded-full bg-green-100">
              <CheckCircle className="h-12 w-12 text-green-600" />
            </div>
            <h1 className="mb-2 text-4xl font-bold text-white">Takk for din bestilling!</h1>
            <p className="text-lg text-gray-300">
              Din ordre er mottatt. Vi behandler den manuelt og sender sporingsinfo når pakken er sendt.
            </p>
            {order.paymentStatus === 'paid' && (
              <div className="mt-4 inline-block rounded-lg bg-green-50 border border-green-200 px-4 py-2 text-sm text-green-800">
                Betaling bekreftet
              </div>
            )}
          </div>

          <div className="mb-6 rounded-2xl bg-gray-900 border border-green-600/20 p-8 shadow-lg">
            <div className="mb-6 flex items-center justify-between border-b pb-4">
              <div>
                <p className="text-sm text-gray-400">Ordrenummer</p>
                <p className="text-2xl font-bold text-white">{order.orderNumber}</p>
              </div>
              <div className="text-right">
                <p className="text-sm text-gray-400">Dato</p>
                <p className="font-medium text-white">{new Date(order.createdAt).toLocaleDateString('no-NO')}</p>
              </div>
            </div>

            {(customerName || customerEmail) && (
              <div className="mb-6">
                <h2 className="mb-3 text-lg font-semibold text-white">Kundeinformasjon</h2>
                <div className="rounded-lg bg-gray-800 border border-green-600/10 p-4">
                  {customerName && <p className="font-medium text-white">{customerName}</p>}
                  {customerEmail && <p className="text-sm text-gray-300">{customerEmail}</p>}
                </div>
              </div>
            )}

            {shippingAddress && (shippingAddress.city || shippingAddress.name) && (
              <div className="mb-6">
                <h2 className="mb-3 text-lg font-semibold text-white">Levering</h2>
                <div className="rounded-lg bg-gray-800 border border-green-600/10 p-4">
                  {shippingAddress.name && <p className="font-medium text-white">{shippingAddress.name}</p>}
                  <p className="text-sm text-gray-300">
                    {[shippingAddress.postalCode, shippingAddress.city].filter(Boolean).join(' ')}
                    {shippingAddress.country ? `, ${shippingAddress.country}` : ''}
                  </p>
                </div>
              </div>
            )}

            {items.length > 0 && (
              <div className="mb-6">
                <h2 className="mb-3 text-lg font-semibold text-white">Produkter</h2>
                <div className="space-y-3">
                  {items.map((item: any, index: number) => (
                    <div key={index} className="flex justify-between rounded-lg bg-gray-800 border border-green-600/10 p-4">
                      <div>
                        <p className="font-medium text-white">{item.name || item.productName || 'Produkt'}</p>
                        <p className="text-sm text-gray-300">Antall: {item.quantity}</p>
                      </div>
                      <p className="font-medium text-white">
                        {((Number(item.price) || 0) * (Number(item.quantity) || 1)).toFixed(0)} kr
                      </p>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="border-t border-green-600/20 pt-4">
              <div className="flex justify-between text-2xl font-bold text-white">
                <span>Total</span>
                <span>{Number(order.total || 0).toFixed(0)} kr</span>
              </div>
              <p className="mt-1 text-xs text-gray-400">Inkl. mva</p>
            </div>

            {(order.trackingNumber || order.trackingUrl) && (
              <div className="mt-6 rounded-lg bg-gray-800 border border-green-600/10 p-4">
                <h3 className="mb-2 text-lg font-semibold text-white">Sporing</h3>
                {order.trackingNumber && (
                  <p className="text-gray-200 text-sm mb-2">Sporingsnummer: {order.trackingNumber}</p>
                )}
                {order.trackingUrl && (
                  <Link
                    href={order.trackingUrl}
                    className="inline-flex items-center gap-2 rounded-lg bg-green-600 px-4 py-2 text-sm font-semibold text-white hover:bg-green-700"
                    target="_blank"
                    rel="noreferrer"
                  >
                    Spor pakken <ArrowRight size={14} />
                  </Link>
                )}
              </div>
            )}
          </div>

          <div className="mb-6 rounded-lg bg-blue-900/30 border border-blue-500/30 p-4">
            <h3 className="text-sm font-semibold text-blue-200 mb-2">Viktig informasjon</h3>
            <p className="text-xs text-blue-100">
              Din ordre blir behandlet manuelt av ElectroHypeX. Forventet leveringstid:
              <strong> 5–12 virkedager</strong> etter ordrebehandling.
            </p>
          </div>

          <div className="mb-8 rounded-2xl bg-gray-900 border border-green-600/20 p-6">
            <h2 className="mb-4 text-xl font-semibold text-white">Hva skjer nå?</h2>
            <div className="space-y-4">
              <div className="flex gap-4">
                <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-green-600 text-white">
                  <Mail size={20} />
                </div>
                <div>
                  <h3 className="font-semibold text-white">1. Ordrebekreftelse på e-post</h3>
                  <p className="text-sm text-gray-300">
                    {customerEmail
                      ? `Vi sender detaljer til ${customerEmail} (sjekk også søppelpost).`
                      : 'Sjekk e-posten du oppga i kassen.'}
                  </p>
                </div>
              </div>
              <div className="flex gap-4">
                <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-green-600 text-white">
                  <Package size={20} />
                </div>
                <div>
                  <h3 className="font-semibold text-white">2. Manuell behandling</h3>
                  <p className="text-sm text-gray-300">Ordren pakkes og sendes av vårt team</p>
                </div>
              </div>
              <div className="flex gap-4">
                <div className="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-full bg-green-600 text-white">
                  <ArrowRight size={20} />
                </div>
                <div>
                  <h3 className="font-semibold text-white">3. Sporing når sendt</h3>
                  <p className="text-sm text-gray-300">Du får sporingsinfo når pakken er på vei</p>
                </div>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-4 sm:flex-row">
            <button
              type="button"
              onClick={() => window.print()}
              className="flex-1 rounded-lg border-2 border-white/40 bg-transparent px-6 py-3 text-center font-medium text-white hover:bg-white/10 print:hidden"
            >
              Skriv ut / lagre kvittering
            </button>
            <Link
              href="/"
              className="flex-1 rounded-lg border-2 border-green-600 bg-green-600 px-6 py-3 text-center font-medium text-white hover:bg-green-700"
            >
              Fortsett å handle
            </Link>
            <Link
              href="/products"
              className="flex-1 rounded-lg border-2 border-green-600 bg-transparent px-6 py-3 text-center font-medium text-white hover:bg-green-600/10 print:hidden"
            >
              Se alle produkter
            </Link>
          </div>
          <p className="mt-4 text-center text-xs text-gray-400 print:hidden">
            Ta vare på ordrenummeret — du trenger det ved retur eller kundeservice.
          </p>
        </div>
      </div>
    </div>
  );
}

import { prisma } from "@/lib/prisma";
import ProductCard from "@/components/ProductCard";
import Link from "next/link";
import Image from "next/image";
import { ChevronRight, Truck, Shield, CreditCard, Headphones, AlertTriangle } from "lucide-react";
import { getCategoriesWithCounts } from "@/lib/utils/product-count";
import { DEFAULT_STORE_ID } from "@/lib/store";
import { getStoreIdFromHeadersServer } from "@/lib/store-server";
import { headers } from "next/headers";
import type { Metadata } from "next";
import { NewsletterForm } from "@/components/NewsletterForm";
import { isDatabaseConfigured, isDevelopment } from "@/lib/utils/database-check";

// ISR: Revalidate every 60 seconds
export const revalidate = 60;

const baseUrl = process.env.NEXTAUTH_URL || "https://www.electrohypex.com";

export const metadata: Metadata = {
