}

import { prisma } from '@/lib/prisma';
import type { Metadata } from 'next';
import { Suspense } from 'react';
import Link from 'next/link';
import ProductPageClientWrapper from '@/components/ProductPageClientWrapper';
import ProductVariantSelector from '@/components/ProductVariantSelector';
import AddToCartButton from '@/components/AddToCartButton';
import ProductCard from '@/components/ProductCard';
import ProductTabs from '@/components/ProductTabs';
import { Truck, Shield, RotateCcw, Check } from 'lucide-react';
import { cleanProductName } from '@/lib/utils/url-decode';
import { getStoreIdFromHeadersServer } from '@/lib/store-server';
import { DEFAULT_STORE_ID } from '@/lib/store';
import { safeQuery } from '@/lib/safeQuery';
import { SITE_CONFIG } from '@/lib/site';
import { generateProductJSONLD, generateBreadcrumbJSONLD, generateSEOMetadata } from '@/lib/seo';
import { getAvailability, getAvailabilityBadgeClasses } from '@/lib/products/availability';

interface ProductPageProps {
  params: Promise<{ slug: string }>;
  searchParams: Promise<{ variant?: string | string[] }>;
}

type VariantDisplay = {
  id: string;
  name: string;
  price: number;
  compareAtPrice: number | null;
  image: string | null;
  attributes: Record<string, string>;
  stock: number;
  colorCode: string;
  slug: string;
};

// ISR: Revalidate every 60 seconds
export const revalidate = 60;

export async function generateMetadata({ params }: ProductPageProps): Promise<Metadata> {
  const { slug } = await params;
  const storeId = await getStoreIdFromHeadersServer();
  
  const product = await safeQuery(
    () =>
      prisma.product.findFirst({
        where: { slug, storeId },
        select: {
          name: true,
          description: true,
          shortDescription: true,
          metaTitle: true,
          metaDescription: true,
          price: true,
          images: true,
          category: true,
        },
      }),
    null,
    'product:metadata'
  );

  if (!product) {
    return {
      title: 'Produkt ikke funnet | ElectroHypeX',
      description: 'Produktet du leter etter ble ikke funnet.',
    };
  }

  // Parse images
  let images: string[] = [];
  try {
    if (typeof product.images === 'string') {
      images = JSON.parse(product.images);
    } else if (Array.isArray(product.images)) {
      images = product.images;
    }
  } catch {
    images = [];
  }

  const cleanedName = cleanProductName(product.metaTitle || product.name);
  const description =
    product.metaDescription ||
    product.shortDescription ||
    product.description?.substring(0, 160) ||
    'Kjøp produkt hos ElectroHypeX';

  // Use SEO helper for consistent metadata
  return generateSEOMetadata({
    title: cleanedName,
    description,
    url: `/products/${slug}`,
    images: images.length > 0 ? [{ url: images[0], width: 1200, height: 630, alt: cleanedName }] : [],
    keywords: [cleanedName, product.category || '', 'elektronikk', 'Norge', 'kjøp', 'nettbutikk'],
    type: 'product',
    canonical: `/products/${slug}`,
  });
}

export default async function ProductPage({ params, searchParams }: ProductPageProps) {
  const { slug } = await params;
  const sp = await searchParams;
  const variantParam = Array.isArray(sp.variant) ? sp.variant[0] : sp.variant;
  const headerStoreId = await getStoreIdFromHeadersServer();
  const safeStoreId = headerStoreId && headerStoreId !== 'demo-store' ? headerStoreId : DEFAULT_STORE_ID;
  
  // Try multiple strategies to find the product
  let product = null;
  
  // Strategy 1: Try with current storeId and isActive
  product = await safeQuery(
    () =>
      prisma.product.findFirst({
        where: { 
          slug, 
          storeId: safeStoreId,
          isActive: true,
        },
        include: {
          variants: {
            where: { isActive: true },
            orderBy: { price: 'asc' },
          },
        },
      }),
    null,
    'product:detail:strategy1'
  );

  // Strategy 2: If not found, try with DEFAULT_STORE_ID
  if (!product && safeStoreId !== DEFAULT_STORE_ID) {
    product = await safeQuery(
      () =>
        prisma.product.findFirst({
          where: { 
            slug, 
            storeId: DEFAULT_STORE_ID,
            isActive: true,
          },
          include: {
            variants: {
              where: { isActive: true },
              orderBy: { price: 'asc' },
            },
          },
        }),
      null,
      'product:detail:strategy2'
    );
  }

  // Strategy 3: If still not found, try without storeId filter (find by slug only)
  if (!product) {
    product = await safeQuery(
      () =>
        prisma.product.findFirst({
          where: { 
            slug,
            isActive: true,
            // Exclude demo-store products
            storeId: { not: 'demo-store' },
          },
          include: {
            variants: {
              where: { isActive: true },
              orderBy: { price: 'asc' },
            },
          },
        }),
      null,
      'product:detail:strategy3'
    );
  }

  // Strategy 4: Last resort - find by slug only (even if inactive, but exclude demo-store)
  if (!product) {
    product = await safeQuery(
      () =>
        prisma.product.findFirst({
          where: { 
            slug,
            storeId: { not: 'demo-store' },
          },
          include: {
            variants: {
              where: { isActive: true },
              orderBy: { price: 'asc' },
            },
          },
        }),
      null,
      'product:detail:strategy4'
    );
  }


  if (!product) {
    return (
      <main className="min-h-screen bg-slate-50 py-12">
        <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8">
          <div className="mx-auto max-w-2xl rounded-xl bg-white p-8 sm:p-12 text-center shadow-sm border border-gray-200">
            <h1 className="mb-3 text-2xl sm:text-3xl font-bold text-gray-900">Produktet er ikke tilgjengelig</h1>
            <p className="mb-6 text-sm sm:text-base text-gray-600">
              Vi klarte ikke å hente produktdetaljene akkurat nå. Produktet kan ha blitt fjernet eller flyttet.
            </p>
            <div className="flex flex-col sm:flex-row gap-3 justify-center">
              <Link
                href="/products"
                className="inline-flex items-center justify-center gap-2 rounded-lg bg-green-600 px-6 py-3 text-sm font-semibold text-white hover:bg-green-700 transition-colors"
              >
                Se alle produkter
              </Link>
              <Link
                href="/tilbud"
                className="inline-flex items-center justify-center gap-2 rounded-lg border-2 border-green-600 px-6 py-3 text-sm font-semibold text-green-600 hover:bg-green-50 transition-colors"
              >
                Se tilbud
              </Link>
            </div>
          </div>
        </div>
      </main>
    );
  }

  // Get 3 random related products from same category
  const relatedProducts = await safeQuery(
    async () => {
      const allRelated = await prisma.product.findMany({
        where: {
          category: product.category,
          id: { not: product.id },
          isActive: true,
          storeId: safeStoreId !== 'demo-store' ? safeStoreId : DEFAULT_STORE_ID,
        },
        select: {
          id: true,
          name: true,
          slug: true,
          price: true,
          compareAtPrice: true,
          images: true,
          category: true,
        },
        take: 20, // Get more to randomize from
      });
      
      // Shuffle and take 3
      const shuffled = allRelated.sort(() => Math.random() - 0.5);
      return shuffled.slice(0, 3);
    },
    [],
    'product:related'
  );

  // Parse images with error handling
  // CRITICAL: Collect ALL images from product AND variants
  let images: string[] = [];
  try {
    if (typeof product.images === 'string') {
      images = JSON.parse(product.images);
    } else if (Array.isArray(product.images)) {
      images = product.images;
    }
  } catch (error) {
    images = [];
  }

  // CRITICAL: Add variant images to product images array
  // This ensures all variant images are available for display
  const variantImages = product.variants
    .map((v) => v.image)
    .filter((img): img is string => 
      !!img && 
      typeof img === 'string' &&
      img.startsWith('http') && 
      !img.includes('placeholder') &&
      !img.includes('placehold.co')
    )
    .filter((img: string, idx: number, arr: string[]) => arr.indexOf(img) === idx); // Remove duplicates
  
  // Combine: variant images first (prioritized), then product images
  const imagesSet = new Set<string>();
  [...variantImages, ...images].forEach((img: string) => {
    if (img && typeof img === 'string' && img.length > 0) {
      imagesSet.add(img);
    }
  });
  
  // Preserve order: variant images first, then others
  images = [...variantImages, ...Array.from(imagesSet).filter(img => !variantImages.includes(img))];

  // Parse tags to detect color variants
  let tags: string[] = [];
  try {
    if (typeof product.tags === 'string') {
      tags = JSON.parse(product.tags);
    } else if (Array.isArray(product.tags)) {
      tags = product.tags;
    }
  } catch {
    tags = [];
  }

  // Helper function to get color code
  const getColorCode = (colorName: string): string => {
    const colorMap: Record<string, string> = {
      svart: '#1f2937',
      hvit: '#f9fafb',
      grå: '#6b7280',
      rød: '#ef4444',
      blå: '#3b82f6',
      grønn: '#10b981',
      gul: '#fbbf24',
      rosa: '#ec4894',
      lilla: '#a855f7',
      oransje: '#f97316',
      brun: '#92400e',
      black: '#1f2937',
      white: '#f9fafb',
      gray: '#6b7280',
      grey: '#6b7280',
      red: '#ef4444',
      blue: '#3b82f6',
      green: '#10b981',
      yellow: '#fbbf24',
      pink: '#ec4899',
      purple: '#a855f7',
      orange: '#f97316',
      brown: '#92400e',
    };

    const normalized = colorName.toLowerCase().trim();
    for (const [key, code] of Object.entries(colorMap)) {
      if (normalized.includes(key)) {
        return code;
      }
    }
    return '#94a3b8';
  };

  // Helper function to find image by color name in URL or tags
  const findImageByColor = (color: string, availableImages: string[]): string | null => {
    const normalizedColor = color.toLowerCase().trim();
    
    // Try to find image URL that contains color name
    for (const img of availableImages) {
      const imgLower = img.toLowerCase();
      if (imgLower.includes(normalizedColor)) {
        return img;
      }
    }
    
    // Try matching with color variations
    const colorVariations: Record<string, string[]> = {
      'svart': ['black', 'svart'],
      'hvit': ['white', 'hvit'],
      'grå': ['gray', 'grey', 'grå', 'graa'],
      'rød': ['red', 'rød'],
      'blå': ['blue', 'blå'],
      'grønn': ['green', 'grønn', 'grønn'],
    };
    
    const variations = colorVariations[normalizedColor] || [normalizedColor];
    for (const variation of variations) {
      for (const img of availableImages) {
        if (img.toLowerCase().includes(variation)) {
          return img;
        }
      }
    }
    
    return null;
  };

  // Track used images to ensure uniqueness
  const usedImages = new Set<string>();
  
  // Map variants with proper images and color codes
  const variants: VariantDisplay[] = product.variants.map((v, index) => {
    const attrs = (v.attributes as Record<string, string>) || {};
    const color = attrs.color || attrs.farge || v.name.toLowerCase();
    const colorSlug = color.toLowerCase().replace(/\s+/g, '-');
    
    // CRITICAL: Prioritize variant's own image from database, but skip placeholders
    let variantImage = v.image || null;
    
    // Skip placeholder images from variant - they're not useful
    const isPlaceholder = variantImage && (
      variantImage.includes('placeholder') || 
      variantImage.includes('placehold.co') ||
      variantImage.includes('via.placeholder')
    );
    
    if (isPlaceholder) {
      variantImage = null;
    }
    
    // If no valid variant image, try to find one
    if (!variantImage) {
      // Try to find image by color name in URL
      variantImage = findImageByColor(color, images) || null;
      
      if (!variantImage) {
        // Fallback: try to match with tags to find correct image index
        const colorIndex = tags.findIndex((tag: string) => 
          tag.toLowerCase().includes(color.toLowerCase())
        );
        
        if (colorIndex >= 0 && images[colorIndex] && !images[colorIndex].includes('placehold')) {
          variantImage = images[colorIndex];
        } else if (images[index] && !images[index].includes('placehold')) {
          // Use index-based assignment (skip placeholders)
          variantImage = images[index];
        } else {
          // Find first non-placeholder image
          for (let i = 0; i < images.length; i++) {
            if (!images[i].includes('placehold')) {
              variantImage = images[i];
              break;
            }
          }
        }
      }
    }
    
    // Track used images for uniqueness (but allow duplicates if necessary)
    if (variantImage) {
      usedImages.add(variantImage);
    }
    
    return {
      id: v.id,
      name: v.name,
      price: Number(v.price),
      compareAtPrice: v.compareAtPrice ? Number(v.compareAtPrice) : null,
      image: variantImage,
      attributes: attrs,
      stock: v.stock,
      colorCode: getColorCode(color),
      slug: colorSlug,
    };
  });

  // Determine active variant from URL parameter
  const activeVariantSlug = variantParam || variants[0]?.slug;
  const activeVariant = variants.find((v) => v.slug === activeVariantSlug) || variants[0];

  // Reorder images to show active variant first
  // CRITICAL: Ensure variant image is included in images array
  let reorderedImages = [...images];
  if (activeVariant && activeVariant.image) {
    // Filter out placeholder/invalid images
    const validVariantImage = activeVariant.image && 
      activeVariant.image.startsWith('http') && 
      !activeVariant.image.includes('placeholder') &&
      !activeVariant.image.includes('placehold.co');
    
    if (validVariantImage) {
      const variantImageIndex = images.findIndex((img: string) => img === activeVariant.image);
      
      if (variantImageIndex > 0) {
        // Move variant's image to front
        reorderedImages = [
          activeVariant.image,
          ...images.filter((_: string, idx: number) => idx !== variantImageIndex)
        ];
      } else if (variantImageIndex === -1) {
        // If variant image is not in main images array, add it to front
        // This ensures the variant image is always available
        reorderedImages = [activeVariant.image, ...images.filter((img: string) => 
          img !== activeVariant.image && 
          img && 
          img.startsWith('http') &&
          !img.includes('placeholder')
        )];
      } else {
        // Variant image is already first, but ensure it's there
        if (reorderedImages[0] !== activeVariant.image) {
          reorderedImages = [
            activeVariant.image, 
            ...images.filter((img: string) => 
              img !== activeVariant.image && 
              img && 
              img.startsWith('http') &&
              !img.includes('placeholder')
            )
          ];
        }
      }
    } else {
      // Variant image is invalid, filter out placeholders from images
      reorderedImages = images.filter((img: string) => 
        img && 
        img.startsWith('http') &&
        !img.includes('placeholder') &&
        !img.includes('placehold.co')
      );
    }
  } else {
    // No active variant or no variant image, filter out placeholders
    reorderedImages = images.filter((img: string) => 
      img && 
      img.startsWith('http') &&
      !img.includes('placeholder') &&
      !img.includes('placehold.co')
    );
  }

  const hasDiscount = product.compareAtPrice && product.compareAtPrice > product.price;
  const discountPercent = hasDiscount && product.compareAtPrice
    ? Math.round((1 - product.price / product.compareAtPrice) * 100) 
    : 0;

  // Clean product name (decode URL-encoded characters)
  const cleanedName = cleanProductName(product.name);

  const productData = {
    id: product.id,
    name: cleanedName,
    slug: product.slug,
    price: Number(product.price),
    compareAtPrice: product.compareAtPrice ? Number(product.compareAtPrice) : null,
    image: images[0] || 'https://placehold.co/600x600?text=Ingen+bilde',
  };

  // Get availability using shared helper
  const availability = getAvailability({
    stock: product.stock || 0,
    variants: variants.map(v => ({ stock: v.stock })),
    isActive: product.isActive !== false,
  });

  // Parse specs from product.specs (JSON field)
  let productSpecs: Record<string, string> = {};
  try {
    if (product.specs && typeof product.specs === 'object') {
      productSpecs = product.specs as Record<string, string>;
    } else if (typeof product.specs === 'string') {
      productSpecs = JSON.parse(product.specs);
    }
  } catch {
    productSpecs = {};
  }

  // Add default specs if none exist
  if (Object.keys(productSpecs).length === 0) {
    productSpecs = {
      'Kategori': product.category || 'Elektronikk',
      'Lagerstatus': availability.label,
      'Leveringstid': availability.leadTimeDays ? `${availability.leadTimeDays.min}–${availability.leadTimeDays.max} virkedager` : 'Ikke tilgjengelig',
      'Garanti': '2 år',
    };
  }

  // Generate JSON-LD structured data
  const productJSONLD = generateProductJSONLD({
    name: cleanedName,
    description: product.shortDescription || product.description?.substring(0, 200) || cleanedName,
    image: images.length > 0 ? images : [productData.image],
    price: product.price,
    currency: 'NOK',
    availability: availability.purchasable ? 'InStock' : 'OutOfStock',
    sku: product.sku || undefined,
    brand: 'ElectroHypeX',
    category: product.category || undefined,
    url: `/products/${product.slug}`,
  });

  // Generate breadcrumb JSON-LD
  const breadcrumbItems = [
    { name: 'Hjem', url: '/' },
    { name: 'Produkter', url: '/products' },
  ];
  if (product.category) {
    breadcrumbItems.push({ name: product.category, url: `/products?category=${encodeURIComponent(product.category)}` });
  }
  breadcrumbItems.push({ name: cleanedName, url: `/products/${product.slug}` });
  const breadcrumbJSONLD = generateBreadcrumbJSONLD(breadcrumbItems);

  return (
    <>
      {/* JSON-LD Structured Data */}
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(productJSONLD) }}
      />
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumbJSONLD) }}
      />
      
      <main className="min-h-screen bg-slate-50 py-4 sm:py-6 lg:py-8">
        <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8">
          
          {/* Breadcrumbs */}
        <nav className="mb-4 sm:mb-6 flex items-center gap-1.5 sm:gap-2 text-xs sm:text-sm text-gray-600 overflow-x-auto">
          <Link href="/" className="hover:text-green-600 transition-colors whitespace-nowrap">Hjem</Link>
          <span>/</span>
          <Link href="/products" className="hover:text-green-600 transition-colors whitespace-nowrap">Produkter</Link>
          <span>/</span>
          {product.category && (
            <>
              <Link href={`/products?category=${product.category}`} className="hover:text-green-600 transition-colors whitespace-nowrap">
                {product.category}
              </Link>
              <span>/</span>
            </>
          )}
          <span className="text-gray-900 truncate">{cleanedName}</span>
        </nav>

        <ProductPageClientWrapper
          images={reorderedImages}
          productName={cleanedName}
          variants={variants}
          defaultImage={productData.image}
          activeVariantSlug={activeVariantSlug}
        >
          {/* Høyre - Produktinfo */}
          <div>
            <div className="rounded-lg sm:rounded-xl bg-white p-4 sm:p-6">
              {/* Badges */}
              <div className="mb-3 sm:mb-4 flex flex-wrap gap-2">
                {hasDiscount && (
                  <span className="rounded-md bg-red-500 px-2.5 sm:px-3 py-1 text-xs sm:text-sm font-bold text-white">
                    SPAR {discountPercent}%
                  </span>
                )}
                <span className={getAvailabilityBadgeClasses(availability)}>
                  {availability.label}
                </span>
              </div>

              {/* Kategori */}
              <p className="mb-1.5 sm:mb-2 text-xs sm:text-sm font-medium uppercase tracking-wide text-gray-500">
                {product.category}
              </p>

              {/* Tittel */}
              <h1 className="mb-4 sm:mb-6 text-xl sm:text-2xl lg:text-3xl font-bold text-gray-900">
                {cleanedName}
              </h1>

              {/* Pris */}
              <div className="mb-4 sm:mb-6 rounded-lg bg-gray-50 p-3 sm:p-4">
                <div className="flex flex-wrap items-baseline gap-2 sm:gap-3">
                  <span className="text-2xl sm:text-3xl lg:text-4xl font-bold text-gray-900">
                    {Math.floor(product.price).toLocaleString('no-NO')},-
                  </span>
                  {hasDiscount && (
                    <span className="text-lg sm:text-xl text-gray-500 line-through">
                      {Math.floor(product.compareAtPrice!).toLocaleString('no-NO')},-
                    </span>
                  )}
                </div>
                {hasDiscount && (
                  <p className="mt-1 text-xs sm:text-sm font-semibold text-red-600">
                    Du sparer {Math.floor(product.compareAtPrice! - product.price).toLocaleString('no-NO')},-
                  </p>
                )}
                <p className="mt-2 text-xs text-gray-500">Inkl. mva</p>
              </div>

              {/* Kort beskrivelse */}
              <p className="mb-4 sm:mb-6 text-sm sm:text-base text-gray-600 leading-relaxed">
                {product.shortDescription || product.description?.substring(0, 200)}
              </p>

              {/* Variant selector - vises før AddToCartButton */}
              {variants.length > 0 && (
                <div className="mb-4 sm:mb-6">
                  <Suspense fallback={<div className="h-20 w-full rounded-lg bg-gray-200 animate-pulse" />}>
                    <ProductVariantSelector
                      variants={variants}
                      defaultImage={productData.image}
                      variantTypeLabel="Farge"
                    />
                  </Suspense>
                </div>
              )}

              {/* Add to cart - disabled if not purchasable */}
              {availability.purchasable ? (
                <AddToCartButton product={productData} variants={variants} />
              ) : (
                <div className="rounded-lg border-2 border-red-200 bg-red-50 p-4 text-center">
                  <p className="text-sm font-semibold text-red-700 mb-2">Ikke tilgjengelig for kjøp</p>
                  <p className="text-xs text-red-600">Dette produktet er for øyeblikket ikke på lager.</p>
                </div>
              )}

              {/* Manuell oppfyllelse info */}
              <div className="mt-4 rounded-lg bg-blue-50 border border-blue-200 p-3 sm:p-4">
                <p className="text-xs sm:text-sm text-blue-900">
                  <strong>Hva skjer etter betaling?</strong> Ordren behandles manuelt av vårt team. 
                  Du mottar bekreftelse på e-post og sporingsinformasjon når pakken er sendt. 
                  Forventet leveringstid: 5–12 virkedager fra ordrebehandling.
                </p>
              </div>

              {/* USPs */}
              <div className="mt-4 sm:mt-6 grid grid-cols-2 gap-2 sm:gap-4">
                <div className="flex items-center gap-2 sm:gap-3 rounded-lg border border-gray-200 p-2 sm:p-3">
                  <Truck className="text-green-600 flex-shrink-0" size={20} />
                  <div>
                    <p className="text-xs sm:text-sm font-semibold text-gray-900">Fri frakt</p>
                    <p className="text-[10px] sm:text-xs text-gray-600">Over 500,-</p>
                  </div>
                </div>
                <div className="flex items-center gap-2 sm:gap-3 rounded-lg border border-gray-200 p-2 sm:p-3">
                  <RotateCcw className="text-green-600 flex-shrink-0" size={20} />
                  <div>
                    <p className="text-xs sm:text-sm font-semibold text-gray-900">30 dagers</p>
                    <p className="text-[10px] sm:text-xs text-gray-600">Åpent kjøp</p>
                  </div>
                </div>
                <div className="flex items-center gap-2 sm:gap-3 rounded-lg border border-gray-200 p-2 sm:p-3">
                  <Shield className="text-green-600 flex-shrink-0" size={20} />
                  <div>
                    <p className="text-xs sm:text-sm font-semibold text-gray-900">2 års garanti</p>
                    <p className="text-[10px] sm:text-xs text-gray-600">Full dekning</p>
                  </div>
                </div>
                {availability.purchasable && availability.leadTimeDays && (
                  <div className="flex items-center gap-2 sm:gap-3 rounded-lg border border-gray-200 p-2 sm:p-3">
                    <Check className="text-green-600 flex-shrink-0" size={20} />
                    <div>
                      <p className="text-xs sm:text-sm font-semibold text-gray-900">Tilgjengelig</p>
                      <p className="text-[10px] sm:text-xs text-gray-600">{availability.leadTimeDays.min}–{availability.leadTimeDays.max} virkedager</p>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </ProductPageClientWrapper>

        {/* Tabs */}
        <ProductTabs 
          description={product.description || ''} 
          specifications={productSpecs}
        />

        {/* Anbefalte produkter */}
        {relatedProducts.length > 0 && (
          <section className="mt-8 sm:mt-12">
            <h2 className="mb-4 sm:mb-6 text-xl sm:text-2xl font-bold text-gray-900">Anbefalte produkter</h2>
            <div className="grid grid-cols-2 gap-3 sm:gap-4 md:grid-cols-3 lg:grid-cols-4">
              {relatedProducts.map((p) => {
                const pImages = typeof p.images === 'string' ? JSON.parse(p.images) : p.images || [];
                return (
                  <ProductCard 
                    key={p.id} 
                    product={{
                      id: p.id,
                      name: p.name,
                      slug: p.slug,
                      price: Number(p.price),
                      compareAtPrice: p.compareAtPrice ? Number(p.compareAtPrice) : null,
                      images: pImages,
                      category: p.category,
                    }} 
                  />
                );
              })}
            </div>
          </section>
        )}
        </div>
      </main>
    </>
  );
}

import { Prisma } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { Suspense } from "react";
import Link from "next/link";
import ProductCard from "@/components/ProductCard";
import { FilterSidebar } from "@/components/products/FilterSidebar";
import { SortDropdown } from "@/components/products/SortDropdown";
import { MobileFilterButton } from "@/components/products/MobileFilterButton";
import { Pagination } from "@/components/products/Pagination";
import { DEFAULT_STORE_ID } from "@/lib/store";
import { getStoreIdFromHeadersServer } from "@/lib/store-server";
import { getCategoryBySlug, getAllCategorySlugs, CATEGORY_DEFINITIONS } from "@/lib/categories";
import type { Metadata } from "next";

const baseUrl = process.env.NEXTAUTH_URL || "https://www.electrohypex.com";

interface ProductsPageProps {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}

function firstParam(value: string | string[] | undefined): string | undefined {
  if (Array.isArray(value)) return value[0];
  return value;
}

async function resolveSearchParams(searchParams: ProductsPageProps["searchParams"]) {
  const raw = await searchParams;
  return {
    category: firstParam(raw.category),
    page: firstParam(raw.page),
    q: firstParam(raw.q),
    query: firstParam(raw.query),
    sort: firstParam(raw.sort),
    minPrice: firstParam(raw.minPrice),
    maxPrice: firstParam(raw.maxPrice),
    inStock: firstParam(raw.inStock),
  };
}

export async function generateMetadata({ searchParams }: ProductsPageProps): Promise<Metadata> {
  const params = await resolveSearchParams(searchParams);
  const categorySlug = params.category;
  const categoryDef = getCategoryBySlug(categorySlug);
  const categoryName = categoryDef?.label;
  const title = categoryName ? `${categoryName} - ElectroHypeX` : "Produkter - ElectroHypeX";
  const description = categoryName 
    ? `Utforsk vårt utvalg av ${categoryName.toLowerCase()}. Gratis frakt over 500 kr. Rask levering i hele Norge.`
    : "Utforsk vårt utvalg av elektronikk, gaming-utstyr, mobil og tilbehør. Gratis frakt over 500 kr.";
  
  return {
    title,
    description,
    keywords: categoryName 
      ? [categoryName.toLowerCase(), "elektronikk", "gaming", "mobil", "tilbehør", "Norge"]
      : ["produkter", "elektronikk", "gaming", "mobil", "tilbehør", "Norge"],
    openGraph: {
      title,
      description,
      type: "website",
      url: `${baseUrl}/products${categorySlug ? `?category=${categorySlug}` : ''}`,
      siteName: "ElectroHypeX",
      locale: "nb_NO",
    },
    alternates: {
      canonical: `${baseUrl}/products${categorySlug ? `?category=${categorySlug}` : ''}`,
    },
  };
}

const PAGE_SIZE = 12;

export default async function ProductsPage({ searchParams }: ProductsPageProps) {
  const params = await resolveSearchParams(searchParams);
  const headerStoreId = await getStoreIdFromHeadersServer();
  const storeId = headerStoreId || DEFAULT_STORE_ID;
  const page = Math.max(1, Number(params.page ?? "1"));
  const categorySlug = params.category ?? undefined;
  const categoryDef = getCategoryBySlug(categorySlug);
  const categoryName = categoryDef?.label;
  const categoryDbValue = categoryDef?.dbValue;
  
  // Handle unknown category slug - if slug exists but is not in our definitions
  const isUnknownCategory = categorySlug && !categoryDef;
  
  // Støtt både 'q' og 'query' for søkeparameter
  const query = params.q ?? params.query ?? undefined;
  const sort = params.sort ?? "newest";
  const minPrice = params.minPrice ? Number(params.minPrice) : undefined;
  const maxPrice = params.maxPrice ? Number(params.maxPrice) : undefined;
  const inStockOnly = params.inStock === "true";

  // Ensure we don't query demo-store products - fallback to DEFAULT_STORE_ID (Electro Hype)
  const safeStoreId = storeId === "demo-store" ? DEFAULT_STORE_ID : storeId;
  
  // Build category filter
  // If valid category slug is provided, use it; otherwise exclude Sport and Klær
  // For unknown categories, show all products (exclude Sport and Klær)
  const categoryFilter = !isUnknownCategory && categorySlug && categoryDbValue
    ? { equals: categoryDbValue } // Use database value for known category
    : { notIn: ["Sport & Trening", "Klær", "Sport"] }; // Exclude Sport and Klær by default

  const where: Prisma.ProductWhereInput = {
    isActive: true,
    // Use safe storeId and exclude demo-store - fallback to DEFAULT_STORE_ID (Electro Hype)
    // Also exclude null storeId (old products without storeId)
    storeId: safeStoreId && safeStoreId !== "demo-store" ? safeStoreId : DEFAULT_STORE_ID,
    // Exclude Sport and Klær categories (unless explicitly requested via categorySlug)
    category: categoryFilter,
    ...(query
      ? {
          name: {
            contains: query,
            mode: "insensitive",
          },
        }
      : {}),
  };

  if (minPrice || maxPrice) {
    where.price = {};
    if (minPrice) {
      where.price.gte = minPrice;
    }
    if (maxPrice) {
      where.price.lte = maxPrice;
    }
  }

  // Filter by stock if requested
  if (inStockOnly) {
    where.stock = {
      gt: 0,
    };
  }

  let productsRaw: Array<{
    id: string;
    name: string;
    slug: string;
    price: number | Prisma.Decimal;
    compareAtPrice: number | Prisma.Decimal | null;
    images: any;
    category: string | null;
    isActive: boolean;
  }> = [];
  let total = 0;
  let categoryRecords: Array<{ category: string | null }> = [];
  let loadError: string | null = null;
  let usedStoreId = storeId;

  try {
    const orderByMap: Record<string, Prisma.ProductOrderByWithRelationInput> = {
      "price-asc": { price: "asc" },
      "price-desc": { price: "desc" },
      name: { name: "asc" },
      newest: { createdAt: "desc" },
    };
    const orderBy = orderByMap[sort] ?? { createdAt: "desc" };

    // Primary query
    const [primaryProducts, primaryTotal, primaryCategories] = await Promise.all([
      prisma.product.findMany({
        where,
        orderBy,
        skip: (page - 1) * PAGE_SIZE,
        take: PAGE_SIZE,
        select: {
          id: true,
          name: true,
          slug: true,
          price: true,
          compareAtPrice: true,
          images: true,
          category: true,
          isActive: true,
        },
      }),
      prisma.product.count({ where }),
      prisma.product.findMany({
        where: {
          storeId: safeStoreId && safeStoreId !== "demo-store" ? safeStoreId : DEFAULT_STORE_ID,
          category: { 
            not: null,
            // Exclude Sport and Klær from category list
            notIn: ["Sport", "Klær", "Sport & Trening"],
          },
          isActive: true,
        },
        distinct: ["category"],
        select: { category: true },
      }),
    ]);

    productsRaw = primaryProducts;
    total = primaryTotal;
    categoryRecords = primaryCategories;
    usedStoreId = storeId;

    // Fallback: if no products, try DEFAULT_STORE_ID (Electro Hype) but NOT demo-store
    if (productsRaw.length === 0 && safeStoreId !== DEFAULT_STORE_ID) {
      const currentFallback = DEFAULT_STORE_ID;
      
      if (currentFallback) {
        console.log(`[products page] no products for storeId="${safeStoreId}", trying fallback="${currentFallback}"`);
        const fallbackWhere: Prisma.ProductWhereInput = {
          ...where,
          storeId: currentFallback,
          // Keep category filter (excludes Sport and Klær unless explicitly requested)
          category: categoryFilter,
        };
        
      const [fallbackProducts, fallbackTotal, fallbackCategories] = await Promise.all([
        prisma.product.findMany({
          where: fallbackWhere,
          orderBy,
          skip: (page - 1) * PAGE_SIZE,
          take: PAGE_SIZE,
          select: {
            id: true,
            name: true,
            slug: true,
            price: true,
            compareAtPrice: true,
            images: true,
            category: true,
            isActive: true,
          },
        }),
        prisma.product.count({ where: fallbackWhere }),
        prisma.product.findMany({
          where: {
            storeId: currentFallback,
            category: { 
              not: null,
              notIn: ["Sport", "Klær"], // Exclude sport/clothing categories
            },
            isActive: true,
          },
          distinct: ["category"],
          select: { category: true },
        }),
      ]);

      productsRaw = fallbackProducts;
      total = fallbackTotal;
      categoryRecords = fallbackCategories;
      usedStoreId = currentFallback;
      }
    }
  } catch (error: any) {
    console.error("[products:list] Failed to load products", error);
    loadError = error?.message ?? "Kunne ikke hente produkter.";
  }

  const totalPages = Math.ceil(total / PAGE_SIZE);
  // Use category definitions for sidebar instead of raw DB categories
  const sidebarCategories = getAllCategorySlugs();

  const products = productsRaw.map((product) => ({
    id: product.id,
    name: product.name,
    slug: product.slug,
    price: Number(product.price),
    compareAtPrice: product.compareAtPrice ? Number(product.compareAtPrice) : null,
    images: product.images,
  }));

  // Debug logging to inspect filters and result size (server-side)
  console.log("[products page] final result count:", products.length, {
    primaryStoreId: storeId,
    actuallyUsedStoreId: usedStoreId,
    hasCategoryFilter: Boolean(where.category),
    search: query ?? null,
    minPrice: typeof minPrice === "number" ? minPrice : null,
    maxPrice: typeof maxPrice === "number" ? maxPrice : null,
  });

  // Get category name for display
  const resolvedCategoryName = categoryName || null;

  return (
    <div className="bg-slate-50 min-h-screen">
      <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8 py-6 sm:py-8 lg:py-10">
        {/* Header section */}
        <div className="mb-6 sm:mb-8">
          <div className="flex flex-col gap-3 sm:gap-4 md:flex-row md:items-center md:justify-between mb-4">
            <div>
              <h1 className="text-2xl sm:text-3xl lg:text-4xl font-semibold tracking-tight text-gray-900">
                {resolvedCategoryName ? resolvedCategoryName : "Alle produkter"}
              </h1>
              {resolvedCategoryName && (
                <p className="mt-2 text-sm sm:text-base text-slate-600">
                  {total} {total === 1 ? "produkt" : "produkter"} i denne kategorien
                </p>
              )}
            </div>
            <div className="hidden md:block">
              <Suspense fallback={<div className="h-10 w-32 rounded-lg bg-gray-200 animate-pulse" />}>
                <SortDropdown />
              </Suspense>
            </div>
          </div>
        </div>
        {/* Mobile: Filter/Sort buttons */}
        <div className="mb-4 flex gap-2 md:hidden">
          <Suspense fallback={<div className="h-10 flex-1 rounded-lg bg-gray-200 animate-pulse" />}>
            <MobileFilterButton categories={sidebarCategories} />
          </Suspense>
          <Suspense fallback={<div className="h-10 w-32 rounded-lg bg-gray-200 animate-pulse" />}>
            <SortDropdown />
          </Suspense>
        </div>

        <div className="flex flex-col gap-6 lg:flex-row lg:items-start lg:gap-8">
          {/* Desktop: Filter sidebar */}
          <Suspense fallback={<div className="hidden lg:block h-96 w-64 rounded-lg bg-gray-200 animate-pulse" />}>
            <aside className="hidden lg:block w-64 flex-shrink-0 lg:sticky lg:top-24 lg:self-start">
              <FilterSidebar categories={sidebarCategories} />
            </aside>
          </Suspense>

          {/* Product grid */}
          <div className="flex-1 min-w-0">
            {isUnknownCategory && (
              <div className="mb-6 rounded-lg border border-blue-200 bg-blue-50 p-4 sm:p-6">
                <p className="text-sm text-blue-800">
                  <span className="font-semibold">Fant ikke kategorien "{categorySlug}".</span> Viser alle produkter i stedet.
                </p>
              </div>
            )}
            {loadError ? (
              <div className="rounded-lg border border-red-200 bg-red-50 p-4 sm:p-6 text-red-700">
                <p className="font-semibold">Kunne ikke laste produkter</p>
                <p className="text-sm">{loadError}</p>
              </div>
            ) : products.length === 0 ? (
              <div className="rounded-lg border border-gray-200 bg-white p-8 sm:p-12 text-center">
                <h2 className="text-xl sm:text-2xl font-semibold text-gray-900 mb-3">
                  {resolvedCategoryName
                    ? `Ingen produkter i denne kategorien ennå`
                    : "Ingen produkter matcher filtrene dine"}
                </h2>
                <p className="text-sm sm:text-base text-gray-600 mb-6 max-w-md mx-auto">
                  {resolvedCategoryName
                    ? "Vi jobber med å utvide sortimentet. I mellomtiden kan du se andre kategorier."
                    : "Prøv å justere filtrene eller søk etter noe annet."}
                </p>
                <div className="flex flex-col sm:flex-row gap-3 justify-center">
                  <Link
                    href="/products"
                    className="inline-block rounded-lg bg-green-600 px-6 py-2.5 text-sm font-semibold text-white hover:bg-green-700 transition-colors"
                  >
                    Se alle produkter
                  </Link>
                  {resolvedCategoryName && (
                    <Link
                      href="/tilbud"
                      className="inline-block rounded-lg border-2 border-green-600 px-6 py-2.5 text-sm font-semibold text-green-600 hover:bg-green-50 transition-colors"
                    >
                      Se tilbud
                    </Link>
                  )}
                </div>
              </div>
            ) : (
              <div className="grid grid-cols-2 gap-4 sm:gap-5 md:grid-cols-3 lg:grid-cols-3 xl:grid-cols-4 2xl:grid-cols-5">
                {products.map((product) => (
                  <ProductCard key={product.id} product={product} />
                ))}
              </div>
            )}
            <Suspense fallback={<div className="h-10 w-full rounded-lg bg-gray-200 animate-pulse mt-4" />}>
              <Pagination currentPage={page} totalPages={totalPages} />
            </Suspense>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

/**
 * Client component to suppress source map warnings in development
 * 
 * This is a known issue with Next.js/Turbopack and Prisma source maps,
 * especially on Windows. The warnings don't affect functionality.
 * 
 * This component filters out these specific console.error messages in development only.
 */

import { useEffect } from "react";

const SOURCE_MAP_ERROR_PATTERNS = [
  /Invalid source map/i,
  /sourceMapURL could not be parsed/i,
  /Failed to parse source map/i,
  /\.next\/dev\/server\/chunks/i,
  /@prisma\/client\/runtime\/library\.js/i,
];

function isSourceMapWarning(message: string): boolean {
  return SOURCE_MAP_ERROR_PATTERNS.some(pattern => pattern.test(message));
}

export function SourceMapSuppress() {
  useEffect(() => {
    // Only in development
    if (process.env.NODE_ENV !== "development") {
      return;
    }

    // Store original console.error
    const originalError = console.error;

    // Override console.error to filter source map warnings
    console.error = (...args: any[]) => {
      // Check if any argument contains source map warning
      const hasSourceMapWarning = args.some((arg) => {
        if (typeof arg === "string") {
          return isSourceMapWarning(arg);
        }
        if (arg instanceof Error) {
          return isSourceMapWarning(arg.message) || isSourceMapWarning(arg.stack || "");
        }
        if (typeof arg === "object" && arg !== null) {
          try {
            const stringified = JSON.stringify(arg);
            return isSourceMapWarning(stringified);
          } catch {
            // If stringify fails, check toString
            return isSourceMapWarning(String(arg));
          }
        }
        return false;
      });

      // If it's a source map warning, suppress it
      if (hasSourceMapWarning) {
        return; // Don't log
      }

      // Otherwise, log normally
      originalError.apply(console, args);
    };

    // Cleanup: restore original on unmount
    return () => {
      console.error = originalError;
    };
  }, []);

  return null; // This component doesn't render anything
}

import { prisma } from "@/lib/prisma";
import ProductCard from "@/components/ProductCard";
import Link from "next/link";
import { ChevronRight, Tag } from "lucide-react";
import { DEFAULT_STORE_ID } from "@/lib/store";
import { getStoreIdFromHeadersServer } from "@/lib/store-server";
import type { Metadata } from "next";

// ISR: Revalidate every 60 seconds
export const revalidate = 60;

const baseUrl = process.env.NEXTAUTH_URL || "https://www.electrohypex.com";

export const metadata: Metadata = {
  title: "Tilbud - ElectroHypeX",
  description: "Se våre beste tilbud på elektronikk, gaming-utstyr og mobil. Spesialpriser og rabatter på utvalgte produkter.",
  keywords: ["tilbud", "rabatt", "elektronikk", "gaming", "mobil", "Norge", "nettbutikk"],
  openGraph: {
    title: "Tilbud - ElectroHypeX",
    description: "Se våre beste tilbud på elektronikk, gaming-utstyr og mobil.",
    type: "website",
    url: `${baseUrl}/tilbud`,
    siteName: "ElektroHype",
  },
  alternates: {
    canonical: `${baseUrl}/tilbud`,
  },
};

/**
 * Henter produkter med rabatt fra databasen.
 */
async function getDiscountedProducts(storeId: string) {
  return prisma.product.findMany({
    where: {
      isActive: true,
      storeId: storeId !== "demo-store" ? storeId : DEFAULT_STORE_ID,
      compareAtPrice: {
        not: null,
        gt: 0,
      },
      // Exclude Sport and Klær categories
      category: {
        notIn: ["Sport", "Klær", "Sport & Trening"],
      },
    },
    orderBy: {
      createdAt: "desc",
    },
    select: {
      id: true,
      name: true,
      slug: true,
      price: true,
      compareAtPrice: true,
      images: true,
      category: true,
    },
  });
}

export default async function TilbudPage() {
  const headerStoreId = await getStoreIdFromHeadersServer();
  // Use DEFAULT_STORE_ID (Electro Hype) as default
  const primaryStoreId = headerStoreId || DEFAULT_STORE_ID;

  let discountedProducts: Awaited<ReturnType<typeof getDiscountedProducts>> = [];
  let loadError: string | null = null;
  let usedStoreId = primaryStoreId;

  try {
    discountedProducts = await getDiscountedProducts(primaryStoreId);
    // Fallback: if no offers for primary store, try DEFAULT_STORE_ID (Electro Hype)
    if (discountedProducts.length === 0 && primaryStoreId !== DEFAULT_STORE_ID) {
      console.log(`[tilbud] no products for storeId, falling back to '${DEFAULT_STORE_ID}'`, {
        storeId: primaryStoreId,
      });
      discountedProducts = await getDiscountedProducts(DEFAULT_STORE_ID);
      usedStoreId = DEFAULT_STORE_ID;
    }
  } catch (error: any) {
    console.error("[tilbud] Failed to load discounted products", error);
    loadError = error?.message ?? "Kunne ikke hente tilbudsprodukter.";
  }

  // Filtrer produkter hvor compareAtPrice faktisk er høyere enn price
  const actualDiscounted = discountedProducts.filter((product) => {
    if (!product.compareAtPrice) return false;
    return Number(product.compareAtPrice) > Number(product.price);
  });

  // Beregn gjennomsnittlig rabatt
  const averageDiscount = actualDiscounted.length > 0
    ? Math.round(
        actualDiscounted.reduce((sum, p) => {
          const discount = ((Number(p.compareAtPrice) - Number(p.price)) / Number(p.compareAtPrice)) * 100;
          return sum + discount;
        }, 0) / actualDiscounted.length
      )
    : 0;

  return (
    <main className="min-h-screen bg-slate-50 py-6 sm:py-8 lg:py-7">
      <div className="mx-auto max-w-screen-2xl px-4 sm:px-6 lg:px-8">
        {/* Breadcrumbs */}
        <nav className="mb-6 text-sm text-gray-medium">
          <Link href="/" className="hover:text-brand">Hjem</Link>
          <span className="mx-2">/</span>
          <span className="text-dark">Ukens tilbud</span>
        </nav>

        {/* Header */}
        <div className="mb-6 sm:mb-8">
          <div className="mb-3 sm:mb-4 flex items-center gap-2 sm:gap-3">
            <Tag className="h-6 w-6 sm:h-8 sm:w-8 text-green-600" />
            <h1 className="text-2xl sm:text-3xl lg:text-4xl font-bold text-gray-900">Ukens tilbud</h1>
          </div>
          <p className="text-sm sm:text-base lg:text-lg text-gray-600">
            {actualDiscounted.length > 0 
              ? `Opptil ${averageDiscount}% rabatt på utvalgte produkter. Begrenset tid!`
              : 'Sjekk tilbake senere for nye tilbud.'}
          </p>
        </div>

        {/* Antall produkter */}
        {actualDiscounted.length > 0 && (
          <div className="mb-6 rounded-lg bg-green-50 border border-green-200 p-3 sm:p-4">
            <p className="text-xs sm:text-sm font-semibold text-green-700">
              {actualDiscounted.length} produkt{actualDiscounted.length !== 1 ? 'er' : ''} på tilbud
            </p>
          </div>
        )}

        {/* Produkter */}
        {loadError ? (
          <div className="rounded-xl bg-white p-12 text-center border border-red-200 bg-red-50 text-red-700">
            <Tag className="mx-auto mb-4 h-16 w-16 text-red-400" />
            <h2 className="mb-2 text-2xl font-bold">Kunne ikke laste tilbud</h2>
            <p className="mb-6 text-sm">{loadError}</p>
          </div>
        ) : actualDiscounted.length > 0 ? (
          <div className="grid grid-cols-2 gap-4 sm:gap-5 md:grid-cols-3 lg:grid-cols-4 xl:grid-cols-5 2xl:grid-cols-6">
            {actualDiscounted.map((product) => {
              const images = typeof product.images === "string" ? JSON.parse(product.images) : product.images || [];

              const discount = Math.round(
                ((Number(product.compareAtPrice) - Number(product.price)) / Number(product.compareAtPrice)) * 100
              );

              return (
                <div key={product.id} className="relative">
                  {/* Stor rabatt-badge */}
                  <div className="absolute -left-2 -top-2 z-10 rounded-full bg-sale px-3 py-1 text-sm font-bold text-white shadow-lg">
                    -{discount}%
                  </div>
                  <ProductCard
                    product={{
                      id: product.id,
                      name: product.name,
                      slug: product.slug,
                      price: Number(product.price),
                      compareAtPrice: product.compareAtPrice ? Number(product.compareAtPrice) : null,
                      images: images,
                      category: product.category,
                    }}
                  />
                </div>
              );
            })}
          </div>
        ) : (
          <div className="rounded-xl bg-white shadow-sm border border-gray-200 p-8 sm:p-12 text-center">
            <Tag className="mx-auto mb-4 h-12 w-12 sm:h-16 sm:w-16 text-gray-300" />
            <h2 className="mb-2 text-xl sm:text-2xl font-bold text-gray-900">Ingen tilbud akkurat nå</h2>
            <p className="mb-6 text-sm sm:text-base text-gray-600">Sjekk tilbake senere for nye tilbud!</p>
            <Link
              href="/products"
              className="inline-flex items-center gap-2 rounded-lg bg-green-600 px-5 sm:px-6 py-2.5 sm:py-3 text-sm sm:text-base font-semibold text-white hover:bg-green-700 transition-colors"
            >
              Se alle produkter
              <ChevronRight size={18} className="sm:w-5 sm:h-5" />
            </Link>
          </div>
        )}

        {/* Call to action */}
        {actualDiscounted.length > 0 && (
          <section className="mt-6 sm:mt-8 rounded-xl bg-gradient-to-r from-gray-900 to-gray-800 p-6 sm:p-8 lg:p-10 text-center text-white">
            <h2 className="mb-2 text-xl sm:text-2xl lg:text-3xl font-bold">Glemt å sjekke noe?</h2>
            <p className="mb-4 sm:mb-6 text-sm sm:text-base text-gray-300">
              Se vårt fulle utvalg av elektronikk og tech-produkter
            </p>
            <Link
              href="/products"
              className="inline-flex items-center gap-2 rounded-lg border-2 border-white px-5 sm:px-6 py-2.5 sm:py-3 text-sm sm:text-base font-semibold text-white hover:bg-white hover:text-gray-900 transition-colors"
            >
              Se alle produkter
              <ChevronRight size={18} className="sm:w-5 sm:h-5" />
            </Link>
          </section>
        )}
      </div>
    </main>
  );
}

'use client';

import { useState, useMemo, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import Image from 'next/image';
import { ShoppingCart, Minus, Plus, Check } from 'lucide-react';
import { useCart } from '@/lib/cart-context';
import toast from 'react-hot-toast';

interface Variant {
  id: string;
  name: string;
  price: number;
  compareAtPrice?: number | null;
  image?: string | null;
  attributes: Record<string, string>;
  stock: number;
}

interface AddToCartButtonProps {
  product: {
    id: string;
    name: string;
    slug: string;
    price: number;
    compareAtPrice?: number | null;
    image: string;
  };
  variants?: Variant[];
  onVariantChange?: (variant: Variant | null) => void;
}

export default function AddToCartButton({ product, variants = [], onVariantChange }: AddToCartButtonProps) {
  const [quantity, setQuantity] = useState(1);
  const [selectedVariantId, setSelectedVariantId] = useState<string | null>(
    variants.length > 0 ? variants[0].id : null
  );
  const [added, setAdded] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { addToCart } = useCart();
  const router = useRouter();

  const hasVariants = variants.length > 0;
  const selectedVariant = useMemo(
    () => variants.find((v) => v.id === selectedVariantId) || null,
    [variants, selectedVariantId]
  );

  // Notify parent when variant changes
  useEffect(() => {
    if (onVariantChange) {
      onVariantChange(selectedVariant);
    }
  }, [selectedVariant, onVariantChange]);

  const displayPrice = selectedVariant ? selectedVariant.price : product.price;
  const displayCompareAtPrice = selectedVariant
    ? selectedVariant.compareAtPrice
    : product.compareAtPrice;
  const displayImage = selectedVariant?.image || product.image;

  const handleAddToCart = async () => {
    try {
      setIsLoading(true);
      setError(null);
      
      const itemToAdd = {
        productId: product.id,
        name: product.name,
        price: displayPrice,
        image: displayImage,
        quantity: 1, // Will be handled by addToCart
        slug: product.slug,
        variantId: selectedVariant?.id || undefined,
        variantName: selectedVariant?.name || undefined,
      };

      addToCart(itemToAdd, quantity);
      setAdded(true);
      toast.success(`${product.name} lagt i handlekurv!`, {
        icon: '🛒',
      });
      setTimeout(() => setAdded(false), 2000);
    } catch (err) {
      setError('Kunne ikke legge produkt i handlekurv. Prøv igjen.');
      console.error('Error adding to cart:', err);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-4">

      {/* Antall velger */}
      <div className="flex items-center gap-4">
        <span className="text-sm font-medium text-dark">Antall:</span>
        <div className="flex items-center rounded-lg border border-gray-border">
          <button
            onClick={() => setQuantity(Math.max(1, quantity - 1))}
            className="px-4 py-3 hover:bg-gray-light transition-colors"
          >
            <Minus size={16} />
          </button>
          <span className="w-12 text-center font-semibold">{quantity}</span>
          <button
            onClick={() => setQuantity(quantity + 1)}
            className="px-4 py-3 hover:bg-gray-light transition-colors"
          >
            <Plus size={16} />
          </button>
        </div>
      </div>

      {/* Error message */}
      {error && (
        <div className="rounded-lg bg-red-50 border border-red-200 p-3 text-sm text-red-700">
          {error}
        </div>
      )}

      {/* Legg i handlekurv knapp */}
      <button
        onClick={handleAddToCart}
        disabled={added || isLoading}
        className={`flex w-full items-center justify-center gap-3 rounded-lg py-3 sm:py-4 text-base sm:text-lg font-semibold transition-all shadow-sm hover:shadow-md disabled:opacity-60 disabled:cursor-not-allowed ${
          added 
            ? 'bg-green-600 text-white' 
            : isLoading
            ? 'bg-green-600 text-white cursor-wait'
            : 'bg-green-600 text-white hover:bg-green-700'
        }`}
      >
        {isLoading ? (
          <>
            <svg className="animate-spin h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
            </svg>
            Legger til...
          </>
        ) : added ? (
          <>
            <Check size={20} className="sm:w-6 sm:h-6" />
            Lagt i handlekurv!
          </>
        ) : (
          <>
            <ShoppingCart size={20} className="sm:w-6 sm:h-6" />
            Legg i handlekurv
          </>
        )}
      </button>

      {/* Kjøp nå knapp */}
      <button
        onClick={async () => {
          try {
            setIsLoading(true);
            setError(null);
            
            const itemToAdd = {
              productId: product.id,
              name: product.name,
              price: displayPrice,
              image: displayImage,
              quantity: 1,
              slug: product.slug,
              variantId: selectedVariant?.id || undefined,
              variantName: selectedVariant?.name || undefined,
            };

            addToCart(itemToAdd, quantity);
            
            // Navigate to checkout immediately
            router.push('/checkout');
          } catch (err) {
            setError('Kunne ikke legge produkt i handlekurv. Prøv igjen.');
            console.error('Error adding to cart:', err);
            setIsLoading(false);
          }
        }}
        disabled={isLoading}
        className="w-full rounded-lg border-2 border-green-600 py-4 text-lg font-semibold text-green-600 hover:bg-green-600 hover:text-white transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
      >
        {isLoading ? 'Legger til...' : 'Kjøp nå'}
      </button>
    </div>
  );
}

'use client';

import Link from 'next/link';
import Image from 'next/image';
import { Search, ShoppingCart, User, Menu, X } from 'lucide-react';
import { useState, useEffect } from 'react';
import { useRouter, usePathname, useSearchParams } from 'next/navigation';
