'use client';

import Image from 'next/image';
import Link from 'next/link';
import { ShoppingCart, Heart } from 'lucide-react';
import { useState } from 'react';
import { useCart } from '@/lib/cart-context';
import { cleanProductName } from '@/lib/utils/url-decode';
import { getCategoryByDbValue } from '@/lib/categories';
import { getAvailability } from '@/lib/products/availability';
import toast from 'react-hot-toast';

interface ProductCardProps {
  product: any;
}

function ProductCard({ product }: ProductCardProps) {
  const [isHovered, setIsHovered] = useState(false);
  const [imageError, setImageError] = useState(false);
  const { addToCart } = useCart();

  // KRITISK: Parse images fra JSON string med error handling
  // Støtter både images (JSON array) og imageUrl (single string)
  let images: string[] = [];
  try {
    if (typeof product.images === 'string') {
      // Try to parse as JSON array
      try {
        const parsed = JSON.parse(product.images);
        images = Array.isArray(parsed) ? parsed : [];
      } catch {
        // If not valid JSON, treat as single URL string
        if (product.images && product.images.startsWith('http')) {
          images = [product.images];
        }
      }
    } else if (Array.isArray(product.images)) {
      images = product.images;
    }
  } catch (error) {
    images = [];
  }

  // Check for imageUrl field (if product has it)
  const imageUrl = (product as any).imageUrl;

  // Valider at bildene er gyldige URLs
  const isValidUrl = (url: string) => {
    if (!url || typeof url !== 'string') return false;
    try {
      new URL(url);
      return url.startsWith('http') && !url.includes('placehold.co');
    } catch {
      return false;
    }
  };

  // Filtrer ut ugyldige bilder og placeholders
  const validImages = images.filter(img => isValidUrl(img));
  
  // Prioritize: imageUrl > images[0] > fallback
  // Fallback hvis ingen bilder
  const fallbackImage = 'https://placehold.co/400x400/f5f5f5/666666?text=Produkt';
  const primaryImage = 
    (imageUrl && isValidUrl(imageUrl)) 
      ? imageUrl 
      : (validImages[0] || fallbackImage);
  const mainImage = primaryImage;
  const hoverImage = validImages[1] || mainImage; // Hvis ingen andre bilder, bruk samme
  
  // Clean product name (decode URL-encoded characters)
  const cleanedName = cleanProductName(product.name);

  const handleAddToCart = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    
    // Parse images to get first image
    let image = '';
    try {
      const images = typeof product.images === 'string' 
        ? JSON.parse(product.images) 
        : product.images || [];
      image = images[0] || '';
    } catch {
      image = '';
    }
    
    const cartItem = {
      productId: product.id,
      name: cleanedName,
      price: product.price,
      image: image,
      quantity: 1,
      slug: product.slug,
      variantId: undefined,
      variantName: undefined,
    };
    
    addToCart(cartItem, 1);
    toast.success(`${cleanedName} lagt i handlekurv!`, {
      icon: '🛒',
    });
  };

  // Beregn rabatt
  const hasDiscount = product.compareAtPrice && product.compareAtPrice > product.price;
  const discountPercent = hasDiscount 
    ? Math.round((1 - product.price / product.compareAtPrice) * 100) 
    : 0;

  // Get availability info
  const availability = getAvailability({
    stock: product.stock || 0,
    variants: product.variants || [],
    isActive: product.isActive !== false,
  });

  return (
    <Link 
      href={`/products/${product.slug}`}
      className="group block h-full"
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      <div className="relative flex h-full flex-col overflow-hidden rounded-xl border border-gray-200 bg-white shadow-sm transition-all duration-300 hover:-translate-y-1 hover:border-green-600 hover:shadow-md">
        
        {/* Badges */}
        {(hasDiscount || product.isNew) && (
          <div className="absolute left-2 top-2 z-10 flex flex-col gap-1.5 sm:left-3 sm:top-3">
            {hasDiscount && (
              <span className="rounded-md bg-red-500 px-2 py-1 text-xs font-bold text-white shadow-sm">
                -{discountPercent}%
              </span>
            )}
            {product.isNew && (
              <span className="rounded-md bg-green-500 px-2 py-1 text-xs font-bold text-white shadow-sm">
                NYHET
              </span>
            )}
          </div>
        )}

        {/* Wishlist button - kun på desktop */}
        <button 
          className="absolute right-2 top-2 z-10 hidden rounded-full bg-white p-2 opacity-0 shadow-md transition-opacity group-hover:opacity-100 hover:bg-gray-50 sm:right-3 sm:top-3 sm:block"
          onClick={(e) => { e.preventDefault(); e.stopPropagation(); }}
        >
          <Heart size={16} className="text-gray-600 hover:text-red-500" />
        </button>

        {/* Image container med hover-effekt */}
        <div className="relative aspect-square overflow-hidden bg-gray-50 group-hover:bg-gray-100 transition-colors duration-300">
          {/* Hovedbilde */}
          <div className={`absolute inset-0 transition-opacity duration-300 ${
            isHovered && hoverImage !== mainImage ? 'opacity-0' : 'opacity-100'
          }`}>
            <Image
              src={imageError ? fallbackImage : mainImage}
              alt={cleanedName}
              fill
              sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
              className="object-contain p-3 sm:p-4"
              loading="lazy"
              onError={() => setImageError(true)}
            />
          </div>
          
          {/* Hover-bilde (kun hvis forskjellig) */}
          {hoverImage !== mainImage && (
            <div className={`absolute inset-0 transition-opacity duration-300 ${
              isHovered ? 'opacity-100' : 'opacity-0'
            }`}>
              <Image
                src={hoverImage}
                alt={`${cleanedName} - alternativt bilde`}
                fill
                sizes="(max-width: 640px) 50vw, (max-width: 1024px) 33vw, 25vw"
                className="object-contain p-3 sm:p-4"
                loading="lazy"
                onError={() => {
                  // Hvis hover-bilde feiler, vis hovedbilde
                  setIsHovered(false);
                }}
              />
            </div>
          )}
        </div>

        {/* Content */}
        <div className="flex flex-1 flex-col p-4 sm:p-5">
          {/* Kategori */}
          <p className="mb-1 text-[11px] sm:text-xs font-medium uppercase tracking-wide text-gray-500">
            {(() => {
              const categoryDef = getCategoryByDbValue(product.category);
              return categoryDef?.label || product.category || 'Elektronikk';
            })()}
          </p>

          {/* Produktnavn */}
          <h3 className="mb-2 line-clamp-2 min-h-[2.5rem] text-sm sm:text-base font-semibold text-gray-900 group-hover:text-green-600 transition-colors">
            {cleanedName}
          </h3>


          {/* Pris */}
          <div className="mb-3 sm:mb-4">
            <div className="flex items-baseline gap-2">
              <span className="text-xl font-semibold text-gray-900">
                {Math.floor(product.price).toLocaleString('no-NO')},-
              </span>
            </div>
            {hasDiscount && (
              <div className="mt-1 flex flex-wrap items-center gap-2">
                <span className="text-sm text-gray-400 line-through">
                  {Math.floor(product.compareAtPrice).toLocaleString('no-NO')},-
                </span>
                <span className="rounded-full bg-green-600 px-2 py-1 text-xs font-semibold text-white">
                  -{discountPercent}%
                </span>
              </div>
            )}
          </div>

          {/* Legg i handlekurv knapp */}
          <button
            onClick={handleAddToCart}
            disabled={!availability.purchasable}
            className={`mt-auto flex w-full items-center justify-center gap-2 rounded-lg py-2.5 sm:py-3 text-sm font-semibold text-white transition-all active:scale-[0.98] shadow-sm hover:shadow-md focus:outline-none focus:ring-2 focus:ring-green-600 focus:ring-offset-2 ${
              availability.purchasable
                ? 'bg-green-600 hover:bg-green-700'
                : 'bg-gray-400 cursor-not-allowed opacity-60'
            }`}
          >
            <ShoppingCart size={16} />
            <span>{availability.purchasable ? 'Legg i handlekurv' : 'Ikke på lager'}</span>
          </button>

          {/* Leveringsinfo - skjul på mobil */}
          {availability.purchasable && (
            <p className="mt-2 hidden text-center text-xs font-medium text-green-600 sm:block">
              ✓ {availability.label}
            </p>
          )}
          {!availability.purchasable && (
            <p className="mt-2 hidden text-center text-xs font-medium text-red-600 sm:block">
              ✗ {availability.label}
            </p>
          )}
        </div>
      </div>
    </Link>
  );
}

export default ProductCard;
export { ProductCard };

'use client';

import Image from 'next/image';
import { useState, useEffect, useMemo } from 'react';
import { ChevronLeft, ChevronRight, ZoomIn, X } from 'lucide-react';

interface ProductImageGalleryProps {
  images: string[] | string;
  productName: string;
  variantImage?: string | null;
}

export default function ProductImageGallery({ images, productName, variantImage }: ProductImageGalleryProps) {
  const [activeIndex, setActiveIndex] = useState(0);
  const [isZoomed, setIsZoomed] = useState(false);
  const [showFullscreen, setShowFullscreen] = useState(false);
  const [imageErrors, setImageErrors] = useState<Set<number>>(new Set());

  // Parse images and combine with variant image
  // CRITICAL: This must recalculate when variantImage or images change
  const allImages = useMemo(() => {
    let parsedImages: string[] = [];
    try {
      if (typeof images === 'string') {
        parsedImages = JSON.parse(images);
      } else if (Array.isArray(images)) {
        parsedImages = images;
      }
    } catch {
      parsedImages = [];
    }

    console.log(`[ProductImageGallery] 🔄 Recalculating allImages, variantImage: ${variantImage?.substring(0, 60)}...`);
    console.log(`[ProductImageGallery] Parsed images count: ${parsedImages.length}`);

    // If variantImage is available, add it as first image
    if (variantImage) {
      if (!parsedImages.includes(variantImage)) {
        const withVariant = [variantImage, ...parsedImages];
        console.log(`[ProductImageGallery] ✅ Added variant image to front, new first: ${withVariant[0]?.substring(0, 60)}...`);
        return withVariant;
      } else {
        // Variant image exists in array - move it to front
        const variantIndex = parsedImages.indexOf(variantImage);
        const reordered = [
          variantImage,
          ...parsedImages.filter((img, idx) => idx !== variantIndex)
        ];
        console.log(`[ProductImageGallery] ✅ Moved variant image to front, new first: ${reordered[0]?.substring(0, 60)}...`);
        return reordered;
      }
    }
    console.log(`[ProductImageGallery] No variant image, returning original images`);
    return parsedImages;
  }, [variantImage, typeof images === 'string' ? images : JSON.stringify(images)]);

  const validImages = allImages.length > 0 
    ? allImages 
    : ['https://placehold.co/600x600/f5f5f5/666666?text=Produkt'];

  // Reset til første bilde når variantImage endres - THIS IS CRITICAL FOR VARIANT SWITCHING
  // Create stable string keys that will never change size
  const variantImageKey = variantImage || '';
  const allImagesKey = allImages.length > 0 ? allImages.join('|') : '';
  
  useEffect(() => {
    console.log(`[ProductImageGallery] 🔄 useEffect triggered, variantImage: ${variantImageKey?.substring(0, 60)}..., allImages.length: ${allImages.length}`);
    
    if (variantImage && allImages.length > 0) {
      const variantIndex = allImages.indexOf(variantImage);
      console.log(`[ProductImageGallery] Variant image index in allImages: ${variantIndex}`);
      
      if (variantIndex !== -1 && variantIndex >= 0) {
        // Variant image found in array - switch to it immediately
        console.log(`[ProductImageGallery] ✅ Switching to variant index ${variantIndex}`);
        setActiveIndex(variantIndex);
      } else if (allImages.length > 0) {
        // Variant image should be first (was added by useMemo) - switch to first image
        console.log(`[ProductImageGallery] ✅ Switching to first image (variant should be at front)`);
        setActiveIndex(0);
      }
    } else if (!variantImage && allImages.length > 0) {
      // Reset to first image if no variant
      console.log(`[ProductImageGallery] No variant image, resetting to first image`);
      setActiveIndex(0);
    }
  }, [variantImageKey, allImagesKey]); // ALWAYS exactly 2 dependencies - never changes size

  const goToPrevious = () => {
    setActiveIndex((prev) => (prev === 0 ? validImages.length - 1 : prev - 1));
  };

  const goToNext = () => {
    setActiveIndex((prev) => (prev === validImages.length - 1 ? 0 : prev + 1));
  };

  const handleImageError = (index: number) => {
    console.error(`[ProductImageGallery] ❌ Failed to load image at index ${index}: ${validImages[index]}`);
    setImageErrors(prev => new Set(prev).add(index));
    
    // If this is a generated/modified URL that doesn't exist, try to find the original base image
    const failedUrl = validImages[index];
    if (failedUrl && (failedUrl.includes('0001') || failedUrl.includes('0002') || failedUrl.includes('0003') || failedUrl.includes('0004'))) {
      // This looks like a generated URL - try to find the original
      const baseUrl = failedUrl.replace(/000[1-9]\.jpg/, '.jpg').replace(/000[1-9]\.jpeg/, '.jpeg');
      const baseIndex = validImages.findIndex(img => img === baseUrl || img.includes(baseUrl.split('/').pop()?.split('.')[0] || ''));
      
      if (baseIndex >= 0 && baseIndex !== index) {
        // Found original, switch to it
        setActiveIndex(baseIndex);
        return;
      }
    }
    
    // Try to move to next valid image
    if (validImages.length > 1) {
      const nextIndex = (index + 1) % validImages.length;
      if (!imageErrors.has(nextIndex)) {
        setActiveIndex(nextIndex);
      } else {
        // If next also has error, try to find first non-error image
        for (let i = 0; i < validImages.length; i++) {
          if (!imageErrors.has(i)) {
            setActiveIndex(i);
            break;
          }
        }
      }
    }
  };

  const currentImage = validImages[activeIndex];
  const hasError = imageErrors.has(activeIndex);

  return (
    <div>
      {/* Hovedbilde */}
      <div className="relative mb-4 aspect-square overflow-hidden rounded-lg bg-gray-light">
        {currentImage && !hasError ? (
          <Image
            src={currentImage}
            alt={`${productName} - Bilde ${activeIndex + 1}`}
            fill
            sizes="(max-width: 768px) 100vw, 50vw"
            className="object-contain p-4"
            onError={() => handleImageError(activeIndex)}
            unoptimized={currentImage.includes('img.kwcdn.com') || currentImage.includes('temu.com')}
            priority={activeIndex === 0}
          />
        ) : (
          <div className="flex items-center justify-center w-full h-full bg-gray-200">
            <div className="text-center p-4">
              <p className="text-gray-500 text-sm mb-2">Bilde kunne ikke lastes</p>
              {validImages.length > 1 && (
                <>
                  <button
                    onClick={goToNext}
                    className="text-blue-600 hover:text-blue-700 text-sm underline mr-2"
                  >
                    Prøv neste bilde
                  </button>
                  {/* Try to find and use the base/original image */}
                  {(() => {
                    const baseImage = validImages.find(img => 
                      !img.includes('0001') && 
                      !img.includes('0002') && 
                      !img.includes('0003') &&
                      !img.includes('_v1') &&
                      !img.includes('_v2')
                    );
                    if (baseImage && baseImage !== currentImage) {
                      const baseIndex = validImages.indexOf(baseImage);
                      return (
                        <button
                          onClick={() => {
                            setImageErrors(prev => {
                              const newSet = new Set(prev);
                              newSet.delete(baseIndex);
                              return newSet;
                            });
                            setActiveIndex(baseIndex);
                          }}
                          className="text-blue-600 hover:text-blue-700 text-sm underline"
                        >
                          Bruk originalt bilde
                        </button>
                      );
                    }
                    return null;
                  })()}
                </>
              )}
            </div>
          </div>
        )}
        
        {/* Navigasjonspiler */}
        {validImages.length > 1 && (
          <>
            <button
              onClick={goToPrevious}
              className="absolute left-2 top-1/2 -translate-y-1/2 rounded-full bg-white p-2 shadow-md hover:bg-gray-light transition-colors z-10"
              aria-label="Forrige bilde"
            >
              <ChevronLeft size={24} />
            </button>
            <button
              onClick={goToNext}
              className="absolute right-2 top-1/2 -translate-y-1/2 rounded-full bg-white p-2 shadow-md hover:bg-gray-light transition-colors z-10"
              aria-label="Neste bilde"
            >
              <ChevronRight size={24} />
            </button>
          </>
        )}

        {/* Zoom/Fullscreen knapp */}
        <button 
          className="absolute right-4 top-4 rounded-full bg-white p-2 shadow-md hover:bg-gray-light z-10"
          onClick={() => setShowFullscreen(true)}
          aria-label="Vis fullskjerm"
        >
          <ZoomIn size={20} />
        </button>

        {/* Bildenummer */}
        {validImages.length > 1 && (
          <div className="absolute bottom-4 left-1/2 -translate-x-1/2 rounded-full bg-black/70 px-3 py-1 text-sm text-white">
            {activeIndex + 1} / {validImages.length}
          </div>
        )}
      </div>

      {/* Miniatyrbilder */}
      {validImages.length > 1 && (
        <div className="flex gap-2 overflow-x-auto pb-2">
          {validImages.map((image, index) => (
            <button
              key={index}
              onClick={() => {
                setImageErrors(prev => {
                  const newSet = new Set(prev);
                  newSet.delete(index);
                  return newSet;
                });
                setActiveIndex(index);
              }}
              className={`relative h-20 w-20 flex-shrink-0 overflow-hidden rounded-lg border-2 transition-all ${
                index === activeIndex 
                  ? 'border-brand ring-2 ring-brand/20' 
                  : 'border-gray-border hover:border-gray-medium'
              }`}
            >
              {!imageErrors.has(index) ? (
                <Image
                  src={image}
                  alt={`${productName} - Miniatyr ${index + 1}`}
                  fill
                  sizes="80px"
                  className="object-contain p-1"
                  onError={() => {
                    console.error(`[ProductImageGallery] ❌ Failed to load thumbnail ${index}: ${image}`);
                    setImageErrors(prev => new Set(prev).add(index));
                  }}
                  unoptimized={image.includes('img.kwcdn.com') || image.includes('temu.com')}
                />
              ) : (
                <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                  <span className="text-xs text-gray-400">Feil</span>
                </div>
              )}
            </button>
          ))}
        </div>
      )}

      {/* Fullscreen Modal */}
      {showFullscreen && (
        <div 
          className="fixed inset-0 z-50 bg-black/95 flex items-center justify-center p-4"
          onClick={() => setShowFullscreen(false)}
        >
          <button
            onClick={(e) => {
              e.stopPropagation();
              setShowFullscreen(false);
            }}
            className="absolute right-4 top-4 rounded-full bg-white/10 p-3 text-white hover:bg-white/20 z-10"
            aria-label="Lukk fullskjerm"
          >
            <X size={24} />
          </button>
          <div 
            className="relative h-[80vh] w-full max-w-4xl"
            onClick={(e) => e.stopPropagation()}
          >
            <Image
              src={validImages[activeIndex]}
              alt={productName}
              fill
              className="object-contain"
              sizes="100vw"
            />
            {validImages.length > 1 && (
              <>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    goToPrevious();
                  }}
                  className="absolute left-4 top-1/2 -translate-y-1/2 rounded-full bg-white/10 p-3 text-white hover:bg-white/20 z-10"
                  aria-label="Forrige bilde"
                >
                  <ChevronLeft size={24} />
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    goToNext();
                  }}
                  className="absolute right-4 top-1/2 -translate-y-1/2 rounded-full bg-white/10 p-3 text-white hover:bg-white/20 z-10"
                  aria-label="Neste bilde"
                >
                  <ChevronRight size={24} />
                </button>
                <div className="absolute bottom-4 left-1/2 -translate-x-1/2 rounded-full bg-black/70 px-4 py-2 text-white">
                  {activeIndex + 1} / {validImages.length}
                </div>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

'use client';

import { useState, createContext, useContext, ReactNode, useEffect, useMemo } from 'react';
import ProductImageGallery from './ProductImageGallery';
import ProductVariantSelector from './ProductVariantSelector';

interface Variant {
  id: string;
  name: string;
  price: number;
  compareAtPrice?: number | null;
  image?: string | null;
  attributes: Record<string, string>;
  stock: number;
  slug?: string;
  colorCode?: string;
}

// Context for sharing selected variant image between components
const VariantContext = createContext<{
  selectedVariantImage: string | null;
  selectedVariant: Variant | null;
  setSelectedVariantImage: (image: string | null) => void;
  setSelectedVariant: (variant: Variant | null) => void;
} | null>(null);

export const useVariantImage = () => {
  const context = useContext(VariantContext);
  return context; // Returns null if not in provider, which is OK
};

interface ProductPageClientWrapperProps {
  images: string[];
  productName: string;
  variants: Variant[];
  defaultImage: string;
  activeVariantSlug?: string;
  children: ReactNode;
}

export default function ProductPageClientWrapper({
  images,
  productName,
  variants,
  defaultImage,
  activeVariantSlug,
  children,
}: ProductPageClientWrapperProps) {
  // Find active variant from slug
  const getInitialVariant = () => {
    if (activeVariantSlug) {
      return variants.find((v: Variant) => v.slug === activeVariantSlug) || variants[0] || null;
    }
    return variants[0] || null;
  };

  const initialVariant = getInitialVariant();

  const [selectedVariant, setSelectedVariant] = useState<Variant | null>(initialVariant);
  const [selectedVariantImage, setSelectedVariantImage] = useState<string | null>(
    initialVariant?.image || defaultImage || null
  );

  // Update image when selectedVariant changes (from user click OR context update)
  useEffect(() => {
    if (selectedVariant) {
      const newImage = selectedVariant.image || defaultImage || null;
      if (newImage !== selectedVariantImage) {
        setSelectedVariantImage(newImage);
        console.log(`[ProductPageClientWrapper] ✅ Variant image updated: ${selectedVariant.name} -> ${newImage?.substring(0, 60)}...`);
      }
    }
  }, [selectedVariant?.id, selectedVariant?.image, defaultImage]); // Only react to variant selection changes
  
  // Sync with URL on mount or when URL changes externally (but don't override active selection)
  useEffect(() => {
    if (activeVariantSlug) {
      const variantFromSlug = variants.find((v: Variant) => v.slug === activeVariantSlug);
      // Only sync if variant is different AND we don't have an active selection
      if (variantFromSlug && variantFromSlug.id !== selectedVariant?.id) {
        // Only update if URL variant is actually different (avoid loops)
        const newImage = variantFromSlug.image || defaultImage || null;
        setSelectedVariant(variantFromSlug);
        setSelectedVariantImage(newImage);
        console.log(`[ProductPageClientWrapper] ✅ Synced with URL variant: ${activeVariantSlug}`);
      }
    }
  }, [activeVariantSlug]); // Only react to external URL changes

  // Determine which images to show - prioritize variant image
  // CRITICAL: This must recalculate when selectedVariantImage changes
  const displayImages = useMemo(() => {
    // Filter out invalid/placeholder images
    const validImages = images.filter(img => 
      img && 
      typeof img === 'string' && 
      img.length > 0 && 
      img.startsWith('http') &&
      !img.includes('placeholder') &&
      !img.includes('placehold.co')
    );
    
    console.log(`[ProductPageClientWrapper] 🔄 Recalculating displayImages`);
    console.log(`  Variant image: ${selectedVariantImage?.substring(0, 60)}...`);
    console.log(`  Valid images count: ${validImages.length}`);
    
    // If no valid images at all, return empty array (will show placeholder)
    if (validImages.length === 0) {
      console.log(`[ProductPageClientWrapper] ⚠️ No valid images found`);
      return selectedVariantImage && selectedVariantImage.startsWith('http') && !selectedVariantImage.includes('placeholder')
        ? [selectedVariantImage]
        : [];
    }
    
    // If no variant image or variant image is invalid, return valid images as-is
    if (!selectedVariantImage || !selectedVariantImage.startsWith('http') || selectedVariantImage.includes('placeholder')) {
      console.log(`[ProductPageClientWrapper] No valid variant image, returning valid images`);
      return validImages;
    }

    // If variant image exists in images array, move it to front
    const variantImageIndex = validImages.findIndex(img => img === selectedVariantImage);
    console.log(`[ProductPageClientWrapper] Variant image index in array: ${variantImageIndex}`);
    
    if (variantImageIndex > 0) {
      // Move variant image to front
      const reordered = [
        selectedVariantImage,
        ...validImages.filter((img, idx) => idx !== variantImageIndex)
      ];
      console.log(`[ProductPageClientWrapper] ✅ Moved variant image to front, new first: ${reordered[0]?.substring(0, 60)}...`);
      return reordered;
    } else if (variantImageIndex === -1) {
      // Variant image not in images array, add it to front
      const withVariant = [selectedVariantImage, ...validImages];
      console.log(`[ProductPageClientWrapper] ✅ Added variant image to front, new first: ${withVariant[0]?.substring(0, 60)}...`);
      return withVariant;
    } else {
      // Variant image is already first
      console.log(`[ProductPageClientWrapper] ✅ Variant image already first`);
      return validImages;
    }
  }, [selectedVariantImage, JSON.stringify(images)]); // Recalculate when variant image or images change

  return (
    <VariantContext.Provider value={{ 
      selectedVariantImage, 
      selectedVariant,
      setSelectedVariantImage, 
      setSelectedVariant 
    }}>
      <div className="grid gap-4 sm:gap-6 lg:gap-8 lg:grid-cols-2">
        {/* Venstre - Bilder */}
        <div className="rounded-lg sm:rounded-xl bg-white p-3 sm:p-4 lg:p-6 order-1 lg:order-1">
          <ProductImageGallery 
            images={displayImages} 
            productName={productName}
            variantImage={selectedVariantImage || null}
          />
        </div>

        {/* Høyre - Produktinfo (children kan inneholde variant selector) */}
        <div className="order-2 lg:order-2">
          {children}
        </div>
      </div>
    </VariantContext.Provider>
  );
}

// Export context for use in ProductVariantSelector
export { VariantContext };

'use client';

import { useState, useMemo, useEffect, useContext, useRef } from 'react';
import Image from 'next/image';
import { useRouter, usePathname, useSearchParams } from 'next/navigation';
import { Check } from 'lucide-react';
import { VariantContext } from './ProductPageClientWrapper';

interface Variant {
  id: string;
  name: string;
  price: number;
  compareAtPrice?: number | null;
  image?: string | null;
  attributes: Record<string, string>;
  stock: number;
  slug?: string;
  colorCode?: string;
}

interface ProductVariantSelectorProps {
  variants: Variant[];
  defaultImage: string;
  onVariantChange?: (variant: Variant | null, variantImage: string | null) => void;
  variantTypeLabel?: string;
}

export default function ProductVariantSelector({ 
  variants, 
  defaultImage, 
  onVariantChange,
  variantTypeLabel = 'Farge'
}: ProductVariantSelectorProps) {
  const router = useRouter();
  const pathname = usePathname();
  const searchParams = useSearchParams();
  
  // Get initial variant from URL or default - also update when URL changes
  const initialVariantSlug = searchParams.get('variant');
  const initialVariant = initialVariantSlug 
    ? variants.find((v) => v.slug === initialVariantSlug) || variants[0]
    : variants[0];

  const [selectedVariantId, setSelectedVariantId] = useState<string | null>(
    initialVariant?.id || (variants.length > 0 ? variants[0].id : null)
  );
  
  // Track if user just clicked (to avoid URL sync overriding user selection)
  const userClickRef = useRef<{ variantId: string; timestamp: number } | null>(null);

  // Update selected variant when URL changes externally (user navigated or shared link)
  // But only if user didn't just click (to avoid overriding user selection)
  useEffect(() => {
    // Ignore URL changes if user just clicked within last 500ms
    const recentClick = userClickRef.current && (Date.now() - userClickRef.current.timestamp) < 500;
    if (recentClick && userClickRef.current?.variantId === selectedVariantId) {
      return; // User just clicked this variant, don't override
    }
    
    if (initialVariantSlug && initialVariant && initialVariant.id !== selectedVariantId) {
      // URL changed externally - sync with it
      setSelectedVariantId(initialVariant.id);
      console.log(`[VariantSelector] 📍 Synced with URL variant: ${initialVariantSlug}`);
    }
  }, [initialVariantSlug]); // Only react to URL slug changes, not internal state
  
  // Try to use context if available (when used within ProductPageVariantWrapper)
  const variantContext = useContext(VariantContext);

  const selectedVariant = useMemo(
    () => variants.find((v) => v.id === selectedVariantId) || null,
    [variants, selectedVariantId]
  );

  // Update variant image and URL when variant changes - BUT only if it's a real change
  useEffect(() => {
    if (!selectedVariant) return;
    
    // Check if this variant is already selected in URL to avoid loops
    const currentUrlVariant = searchParams.get('variant');
    if (selectedVariant.slug === currentUrlVariant) {
      // Already in sync, just update context
      const variantImage = selectedVariant.image || defaultImage || null;
      if (variantContext) {
        variantContext.setSelectedVariantImage(variantImage);
        variantContext.setSelectedVariant(selectedVariant);
      }
      return;
    }
    
    const variantImage = selectedVariant.image || defaultImage || null;
    
    // Update via context if available - THIS IS CRITICAL
    if (variantContext) {
      // Force immediate update - don't wait for React batching
      variantContext.setSelectedVariantImage(variantImage);
      variantContext.setSelectedVariant(selectedVariant);
    }
    
    // Update URL with variant parameter (only if different)
    if (selectedVariant.slug && selectedVariant.slug !== currentUrlVariant) {
      const params = new URLSearchParams(searchParams.toString());
      params.set('variant', selectedVariant.slug);
      // Use replace instead of push to avoid adding to history
      router.replace(`${pathname}?${params.toString()}`, { scroll: false });
      console.log(`[VariantSelector] ✅ Updated URL to: ?variant=${selectedVariant.slug}`);
    }
    
    // Also call callback if provided (for backwards compatibility)
    if (onVariantChange) {
      onVariantChange(selectedVariant, variantImage);
    }
  }, [selectedVariant?.id, selectedVariant?.slug, defaultImage, variantContext, onVariantChange, router, pathname, searchParams]);

  // Grupper varianter etter attributt (farge, størrelse, etc)
  const variantGroups = useMemo(() => {
    const groups: Record<string, Variant[]> = {};
    variants.forEach((variant) => {
      const key = variant.attributes?.color || variant.attributes?.farge || variant.attributes?.størrelse || variant.name.split(' - ')[0];
      if (!groups[key]) groups[key] = [];
      groups[key].push(variant);
    });
    return groups;
  }, [variants]);

  if (variants.length === 0) return null;

  return (
    <div className="space-y-3">
      <label className="text-sm font-semibold text-dark">
        {variantTypeLabel}: {selectedVariant?.attributes?.color || selectedVariant?.attributes?.farge || selectedVariant?.name.split(' - ')[0] || selectedVariant?.name}
      </label>
      
      <div className="flex flex-wrap gap-3">
        {variants.map((variant) => {
          const isSelected = selectedVariantId === variant.id;
          // Prioritize variant's own image, fallback to default
          const variantImage = variant.image || defaultImage;
          const variantLabel = variant.attributes?.color || variant.attributes?.farge || variant.attributes?.størrelse || variant.name.split(' - ')[0] || variant.name;
          
          return (
            <button
              key={variant.id}
              onClick={(e) => {
                e.preventDefault();
                
                // Track user click to prevent URL sync from overriding
                userClickRef.current = { variantId: variant.id, timestamp: Date.now() };
                
                setSelectedVariantId(variant.id);
                
                // CRITICAL: Immediately update context when clicked to trigger image change
                // This must happen synchronously, not in useEffect
                if (variantContext) {
                  const variantImageToUse = variant.image || defaultImage || null;
                  // Force immediate synchronous update - this will trigger re-render
                  variantContext.setSelectedVariantImage(variantImageToUse);
                  variantContext.setSelectedVariant(variant);
                  console.log(`[VariantSelector] ✅ Clicked variant: ${variantLabel}`);
                  console.log(`[VariantSelector] Image: ${variantImageToUse?.substring(0, 80)}...`);
                }
              }}
              className={`group relative flex flex-col items-center rounded-lg border-2 overflow-hidden transition-all ${
                isSelected
                  ? 'border-brand ring-2 ring-brand/20 shadow-md'
                  : 'border-gray-border hover:border-brand hover:shadow-sm'
              }`}
              aria-label={`Velg ${variantLabel}`}
            >
              {/* Variant bilde - unikt for hver variant */}
              <div className="relative w-24 h-24 bg-gray-light">
                {variantImage ? (
                  <Image
                    src={variantImage}
                    alt={`${variantLabel} variant`}
                    fill
                    sizes="96px"
                    className="object-contain p-2"
                  />
                ) : variant.colorCode ? (
                  // Show color swatch if no image but has color code
                  <div 
                    className="w-full h-full"
                    style={{ backgroundColor: variant.colorCode }}
                  />
                ) : (
                  <div className="w-full h-full flex items-center justify-center text-gray-400 text-xs">
                    Ingen bilde
                  </div>
                )}
              </div>
              
              {/* Variant navn */}
              <div className={`w-full px-2 py-1.5 text-xs font-medium text-center transition-colors ${
                isSelected ? 'bg-brand-light text-brand' : 'bg-white text-dark'
              }`}>
                {variantLabel}
              </div>
              
              {/* Selected indicator */}
              {isSelected && (
                <div className="absolute top-1 right-1 w-5 h-5 rounded-full bg-brand border-2 border-white flex items-center justify-center shadow-sm z-10">
                  <Check size={12} className="text-white" />
                </div>
              )}
            </button>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Sparkles, Loader2, Copy, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { callAdminAI } from "@/lib/admin-ai";

interface AIHelperProps {
  type: "productDescription" | "seo";
  onResult: (result: any) => void;
  productData?: {
    name?: string;
    category?: string;
    price?: number;
    description?: string;
  };
}

export function AIHelper({ type, onResult, productData = {} }: AIHelperProps) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [toneOfVoice, setToneOfVoice] = useState<"nøytral" | "entusiastisk" | "teknisk">("nøytral");
  const [useCase, setUseCase] = useState("");
  const [result, setResult] = useState<any>(null);
  const [copied, setCopied] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const response = await callAdminAI(type, {
        name: productData.name,
        category: productData.category,
        price: productData.price,
        tone: toneOfVoice,
        notes: useCase || undefined,
        description: productData.description,
        // Legacy support
        toneOfVoice,
        useCase: useCase || undefined,
      });

      if (!response.ok) {
        throw new Error(response.error || "Kunne ikke generere innhold");
      }

      setResult(response.result);
      onResult(response.result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Ukjent feil");
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  if (type === "productDescription") {
    return (
      <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
        <div className="mb-3 flex items-center gap-2">
          <Sparkles size={18} className="text-green-600" />
          <h3 className="text-sm font-semibold text-gray-900">AI-hjelper: Produktbeskrivelse</h3>
        </div>

        <div className="mb-3 space-y-2">
          <div>
            <label className="mb-1 block text-xs font-medium text-gray-700">Tone</label>
            <select
              value={toneOfVoice}
              onChange={(e) => setToneOfVoice(e.target.value as any)}
              className="w-full rounded border border-slate-300 bg-white px-3 py-1.5 text-sm"
            >
              <option value="nøytral">Nøytral</option>
              <option value="entusiastisk">Entusiastisk</option>
              <option value="teknisk">Teknisk</option>
            </select>
          </div>

          <div>
            <label className="mb-1 block text-xs font-medium text-gray-700">
              Bruksområde (valgfritt)
            </label>
            <input
              type="text"
              value={useCase}
              onChange={(e) => setUseCase(e.target.value)}
              placeholder="F.eks. Hjemmekontor, Gaming, etc."
              className="w-full rounded border border-slate-300 bg-white px-3 py-1.5 text-sm"
            />
          </div>
        </div>

        <Button
          onClick={handleGenerate}
          disabled={loading || !productData.name}
          className="w-full bg-green-600 hover:bg-green-700 text-white"
        >
          {loading ? (
            <>
              <Loader2 size={16} className="mr-2 animate-spin" />
              Genererer...
            </>
          ) : (
            <>
              <Sparkles size={16} className="mr-2" />
              Generer produktbeskrivelse
            </>
          )}
        </Button>

        {error && (
          <div className="mt-3 rounded border border-red-200 bg-red-50 p-2 text-xs text-red-700">
            {error}
          </div>
        )}

        {result && (
          <div className="mt-4 space-y-3">
            {result.description && (
              <div>
                <div className="mb-1 flex items-center justify-between">
                  <label className="text-xs font-medium text-gray-700">Beskrivelse</label>
                  <button
                    onClick={() => copyToClipboard(result.description)}
                    className="flex items-center gap-1 text-xs text-green-600 hover:text-green-700"
                  >
                    {copied ? <Check size={14} /> : <Copy size={14} />}
                    {copied ? "Kopiert!" : "Kopier"}
                  </button>
                </div>
                <textarea
                  readOnly
                  value={result.description}
                  className="w-full rounded border border-slate-300 bg-white p-2 text-sm"
                  rows={4}
                />
              </div>
            )}

            {result.bullets && result.bullets.length > 0 && (
              <div>
                <div className="mb-1 flex items-center justify-between">
                  <label className="text-xs font-medium text-gray-700">Nøkkelfordeler</label>
                  <button
                    onClick={() => copyToClipboard(result.bullets.join("\n"))}
                    className="flex items-center gap-1 text-xs text-green-600 hover:text-green-700"
                  >
                    {copied ? <Check size={14} /> : <Copy size={14} />}
                    {copied ? "Kopiert!" : "Kopier"}
                  </button>
                </div>
                <ul className="space-y-1 rounded border border-slate-300 bg-white p-2 text-sm">
                  {result.bullets.map((bullet: string, idx: number) => (
                    <li key={idx} className="list-disc list-inside">
                      {bullet}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  if (type === "seo") {
    return (
      <div className="rounded-lg border border-slate-200 bg-slate-50 p-4">
        <div className="mb-3 flex items-center gap-2">
          <Sparkles size={18} className="text-green-600" />
          <h3 className="text-sm font-semibold text-gray-900">AI-hjelper: SEO</h3>
        </div>

        <Button
          onClick={handleGenerate}
          disabled={loading || !productData.name}
          className="w-full bg-green-600 hover:bg-green-700 text-white"
        >
          {loading ? (
            <>
              <Loader2 size={16} className="mr-2 animate-spin" />
              Genererer...
            </>
          ) : (
            <>
              <Sparkles size={16} className="mr-2" />
              Generer SEO-tittel & meta-beskrivelse
            </>
          )}
        </Button>

        {error && (
          <div className="mt-3 rounded border border-red-200 bg-red-50 p-2 text-xs text-red-700">
            {error}
          </div>
        )}

        {result && (
          <div className="mt-4 space-y-3">
            {result.title && (
              <div>
                <div className="mb-1 flex items-center justify-between">
                  <label className="text-xs font-medium text-gray-700">SEO-tittel</label>
                  <button
                    onClick={() => copyToClipboard(result.title)}
                    className="flex items-center gap-1 text-xs text-green-600 hover:text-green-700"
                  >
                    {copied ? <Check size={14} /> : <Copy size={14} />}
                    {copied ? "Kopiert!" : "Kopier"}
                  </button>
                </div>
                <input
                  readOnly
                  value={result.title}
                  className="w-full rounded border border-slate-300 bg-white p-2 text-sm"
                />
                <p className="mt-1 text-xs text-gray-500">
                  {result.title.length} tegn (anbefalt: 50-60)
                </p>
              </div>
            )}

            {result.description && (
              <div>
                <div className="mb-1 flex items-center justify-between">
                  <label className="text-xs font-medium text-gray-700">Meta-beskrivelse</label>
                  <button
                    onClick={() => copyToClipboard(result.description)}
                    className="flex items-center gap-1 text-xs text-green-600 hover:text-green-700"
                  >
                    {copied ? <Check size={14} /> : <Copy size={14} />}
                    {copied ? "Kopiert!" : "Kopier"}
                  </button>
                </div>
                <textarea
                  readOnly
                  value={result.description}
                  className="w-full rounded border border-slate-300 bg-white p-2 text-sm"
                  rows={3}
                />
                <p className="mt-1 text-xs text-gray-500">
                  {result.description.length} tegn (anbefalt: 140-160)
                </p>
              </div>
            )}
          </div>
        )}
      </div>
    );
  }

  return null;
}

"use client";

import { useState } from "react";
import { Sparkles, Loader2, Copy, Check, X } from "lucide-react";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { callAdminAI, type AIType } from "@/lib/admin-ai";

type Mode = "productDescription" | "seo" | "categoryCopy" | "heroCopy" | "emailTemplate";

const MODES: { id: Mode; label: string }[] = [
  { id: "productDescription", label: "Produktbeskrivelse" },
  { id: "seo", label: "SEO" },
  { id: "categoryCopy", label: "Kategoritekst" },
  { id: "heroCopy", label: "Hero-tekst" },
  { id: "emailTemplate", label: "E-postmal" },
];

export function GlobalAIAssistant() {
  const [open, setOpen] = useState(false);
  const [mode, setMode] = useState<Mode>("productDescription");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [copied, setCopied] = useState(false);

  // Form states
  const [formData, setFormData] = useState<Record<string, any>>({});
  const [result, setResult] = useState<any>(null);

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const payload: any = {};

      // Build payload based on mode
      switch (mode) {
        case "productDescription":
          payload.name = formData.name || "";
          payload.category = formData.category || "";
          payload.price = formData.price ? Number(formData.price) : undefined;
          payload.tone = formData.tone || "nøytral";
          payload.notes = formData.notes || "";
          break;
        case "seo":
          payload.name = formData.name || "";
          payload.category = formData.category || "";
          payload.shortDescription = formData.shortDescription || "";
          payload.pageType = formData.pageType || "product";
          break;
        case "categoryCopy":
          payload.categoryName = formData.categoryName || "";
          payload.productsHint = formData.productsHint || "";
          payload.tone = formData.tone || "nøytral";
          break;
        case "heroCopy":
          payload.campaignName = formData.campaignName || "";
          payload.focus = formData.focus || "";
          payload.discountInfo = formData.discountInfo || "";
          break;
        case "emailTemplate":
          payload.templateType = formData.templateType || "campaign";
          payload.audienceDescription = formData.audienceDescription || "";
          payload.offerDescription = formData.offerDescription || "";
          break;
      }

      const response = await callAdminAI(mode, payload);

      if (!response.ok) {
        throw new Error(response.error || "Kunne ikke generere innhold");
      }

      setResult(response.result);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Ukjent feil");
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const resetForm = () => {
    setFormData({});
    setResult(null);
    setError(null);
  };

  return (
    <>
      {/* Floating button - bottom right for all screens */}
      <button
        onClick={() => setOpen(true)}
        className="fixed bottom-6 right-6 z-40 flex items-center gap-2 rounded-full bg-green-600 px-4 py-2.5 text-sm font-semibold text-white shadow-lg hover:bg-green-700 transition-colors"
      >
        <Sparkles size={18} />
        AI Assistent
      </button>

      {/* Dialog */}
      <Dialog open={open} onOpenChange={setOpen}>
        <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto bg-slate-50">
          <DialogHeader>
            <DialogTitle className="text-xl font-semibold">AI Assistent</DialogTitle>
            <DialogDescription className="text-sm text-slate-600">
              Få hjelp til tekst, SEO og kampanjer med noen få klikk.
            </DialogDescription>
          </DialogHeader>

          {/* Mode tabs */}
          <div className="flex flex-wrap gap-2 mb-6">
            {MODES.map((m) => (
              <button
                key={m.id}
                onClick={() => {
                  setMode(m.id);
                  resetForm();
                }}
                className={`inline-flex rounded-full border px-3 py-1 text-xs sm:text-sm transition-colors ${
                  mode === m.id
                    ? "bg-green-600 text-white border-green-600"
                    : "bg-white text-slate-700 border-slate-300 hover:bg-slate-50"
                }`}
              >
                {m.label}
              </button>
            ))}
          </div>

          {/* Form based on mode */}
          <div className="space-y-4">
            {mode === "productDescription" && (
              <>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Produktnavn *
                  </label>
                  <Input
                    value={formData.name || ""}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="F.eks. Gaming-tastatur RGB"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Kategori
                  </label>
                  <Input
                    value={formData.category || ""}
                    onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                    placeholder="F.eks. Gaming"
                    className="bg-white"
                  />
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="mb-1 block text-sm font-medium text-slate-700">
                      Pris (kr)
                    </label>
                    <Input
                      type="number"
                      value={formData.price || ""}
                      onChange={(e) => setFormData({ ...formData, price: e.target.value })}
                      placeholder="999"
                      className="bg-white"
                    />
                  </div>
                  <div>
                    <label className="mb-1 block text-sm font-medium text-slate-700">
                      Tone
                    </label>
                    <select
                      value={formData.tone || "nøytral"}
                      onChange={(e) => setFormData({ ...formData, tone: e.target.value })}
                      className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"
                    >
                      <option value="nøytral">Nøytral</option>
                      <option value="entusiastisk">Entusiastisk</option>
                      <option value="teknisk">Teknisk</option>
                    </select>
                  </div>
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Stikkord (valgfritt)
                  </label>
                  <Textarea
                    value={formData.notes || ""}
                    onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                    placeholder="F.eks. Hjemmekontor, Gaming, RGB-lys"
                    rows={2}
                    className="bg-white"
                  />
                </div>
              </>
            )}

            {mode === "seo" && (
              <>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Side/Produktnavn *
                  </label>
                  <Input
                    value={formData.name || ""}
                    onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                    placeholder="F.eks. Gaming-tastatur RGB"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Kort beskrivelse
                  </label>
                  <Textarea
                    value={formData.shortDescription || ""}
                    onChange={(e) => setFormData({ ...formData, shortDescription: e.target.value })}
                    placeholder="Kort beskrivelse av produktet/siden"
                    rows={2}
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Type side
                  </label>
                  <select
                    value={formData.pageType || "product"}
                    onChange={(e) => setFormData({ ...formData, pageType: e.target.value })}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"
                  >
                    <option value="product">Produktside</option>
                    <option value="category">Kategoriside</option>
                    <option value="frontpage">Forside</option>
                    <option value="other">Annet</option>
                  </select>
                </div>
              </>
            )}

            {mode === "categoryCopy" && (
              <>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Kategorinavn *
                  </label>
                  <Input
                    value={formData.categoryName || ""}
                    onChange={(e) => setFormData({ ...formData, categoryName: e.target.value })}
                    placeholder="F.eks. Gaming"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Hva slags produkter? (valgfritt)
                  </label>
                  <Textarea
                    value={formData.productsHint || ""}
                    onChange={(e) => setFormData({ ...formData, productsHint: e.target.value })}
                    placeholder="F.eks. Tastaturer, mus, headset, gaming-stoler"
                    rows={3}
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Tone
                  </label>
                  <select
                    value={formData.tone || "nøytral"}
                    onChange={(e) => setFormData({ ...formData, tone: e.target.value })}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"
                  >
                    <option value="nøytral">Nøytral</option>
                    <option value="entusiastisk">Entusiastisk</option>
                    <option value="teknisk">Teknisk</option>
                  </select>
                </div>
              </>
            )}

            {mode === "heroCopy" && (
              <>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Kampanjenavn *
                  </label>
                  <Input
                    value={formData.campaignName || ""}
                    onChange={(e) => setFormData({ ...formData, campaignName: e.target.value })}
                    placeholder="F.eks. Black Week, Ukens tilbud"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Fokus (valgfritt)
                  </label>
                  <Input
                    value={formData.focus || ""}
                    onChange={(e) => setFormData({ ...formData, focus: e.target.value })}
                    placeholder="F.eks. Gaming, Elektronikk, Hjem"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Rabattinfo (valgfritt)
                  </label>
                  <Input
                    value={formData.discountInfo || ""}
                    onChange={(e) => setFormData({ ...formData, discountInfo: e.target.value })}
                    placeholder="F.eks. Opptil 40% rabatt"
                    className="bg-white"
                  />
                </div>
              </>
            )}

            {mode === "emailTemplate" && (
              <>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Type mal *
                  </label>
                  <select
                    value={formData.templateType || "campaign"}
                    onChange={(e) => setFormData({ ...formData, templateType: e.target.value })}
                    className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm"
                  >
                    <option value="welcome">Velkomst-e-post</option>
                    <option value="campaign">Kampanje-e-post</option>
                    <option value="newsletter">Nyhetsbrev</option>
                  </select>
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Målgruppe (valgfritt)
                  </label>
                  <Input
                    value={formData.audienceDescription || ""}
                    onChange={(e) => setFormData({ ...formData, audienceDescription: e.target.value })}
                    placeholder="F.eks. Nye kunder, Gaming-entusiaster"
                    className="bg-white"
                  />
                </div>
                <div>
                  <label className="mb-1 block text-sm font-medium text-slate-700">
                    Tilbud / Tema (valgfritt)
                  </label>
                  <Textarea
                    value={formData.offerDescription || ""}
                    onChange={(e) => setFormData({ ...formData, offerDescription: e.target.value })}
                    placeholder="F.eks. 20% rabatt på alle gaming-produkter"
                    rows={2}
                    className="bg-white"
                  />
                </div>
              </>
            )}

            {/* Generate button */}
            <Button
              onClick={handleGenerate}
              disabled={loading || (mode === "productDescription" && !formData.name) || (mode === "seo" && !formData.name) || (mode === "categoryCopy" && !formData.categoryName) || (mode === "heroCopy" && !formData.campaignName)}
              className="w-full bg-green-600 hover:bg-green-700 text-white font-semibold rounded-full px-4 py-2 text-sm"
            >
              {loading ? (
                <>
                  <Loader2 size={16} className="mr-2 animate-spin" />
                  Genererer...
                </>
              ) : (
                <>
                  <Sparkles size={16} className="mr-2" />
                  Generer {MODES.find((m) => m.id === mode)?.label.toLowerCase()}
                </>
              )}
            </Button>

            {/* Error */}
            {error && (
              <div className="rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">
                {error}
              </div>
            )}

            {/* Results */}
            {result && (
              <div className="space-y-4 rounded-xl bg-white p-6 shadow-sm">
                {mode === "productDescription" && (
                  <>
                    {result.description && (
                      <div>
                        <div className="mb-2 flex items-center justify-between">
                          <label className="text-sm font-medium text-slate-700">Beskrivelse</label>
                          <button
                            onClick={() => copyToClipboard(result.description)}
                            className="flex items-center gap-1 rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-800 hover:bg-slate-200 transition-colors"
                          >
                            {copied ? <Check size={14} /> : <Copy size={14} />}
                            {copied ? "Kopiert!" : "Kopier"}
                          </button>
                        </div>
                        <Textarea
                          value={result.description}
                          onChange={(e) => setResult({ ...result, description: e.target.value })}
                          rows={6}
                          className="bg-white"
                        />
                      </div>
                    )}
                    {result.bullets && result.bullets.length > 0 && (
                      <div>
                        <div className="mb-2 flex items-center justify-between">
                          <label className="text-sm font-medium text-slate-700">Nøkkelfordeler</label>
                          <button
                            onClick={() => copyToClipboard(result.bullets.join("\n"))}
                            className="flex items-center gap-1 rounded-full bg-slate-100 px-3 py-1 text-xs text-slate-800 hover:bg-slate-200 transition-colors"
                          >
                            {copied ? <Check size={14} /> : <Copy size={14} />}
                            {copied ? "Kopiert!" : "Kopier"}
                          </button>
                        </div>
                        <ul className="space-y-1 rounded-lg border border-slate-300 bg-white p-3 text-sm">
                          {result.bullets.map((bullet: string, idx: number) => (
                            <li key={idx} className="list-disc list-inside">
                              {bullet}
                            </li>
                          ))}
                        </ul>
                      </div>
                    )}
                  </>
                )}

                {mode === "seo" && (
