"use client";

import { useRouter } from "next/navigation";
import { useState } from "react";
import toast from "react-hot-toast";

export function BulkMarkOrderedButton({ count }: { count: number }) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  if (count <= 0) return null;

  const run = async () => {
    if (
      !confirm(
        `Markere alle ${count} betalte NY-ordrer som «bestilt hos leverandør»? Dette er Robs ett-klikks morgenrutine.`
      )
    ) {
      return;
    }
    setLoading(true);
    try {
      const res = await fetch("/api/admin/orders/bulk", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ action: "mark_ordered" }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Feil");
      toast.success(data.message || `Oppdatert ${data.updated}`);
      router.refresh();
    } catch (e: any) {
      toast.error(e.message || "Kunne ikke oppdatere");
    } finally {
      setLoading(false);
    }
  };

  return (
    <button
      type="button"
      disabled={loading}
      onClick={run}
      className="rounded-lg bg-green-600 px-4 py-2.5 text-sm font-semibold text-white hover:bg-green-700 disabled:opacity-60"
    >
      {loading ? "Jobber…" : `Ett klikk: bestill alle ${count} betalte NY`}
    </button>
  );
}

export function RetryFailedEmailsHint({ count }: { count: number }) {
  if (count <= 0) return null;
  return (
    <p className="text-xs text-amber-800">
      {count} ordre har feilet e-post — åpne køen og bruk «Send på nytt» (bulk-retry kommer neste
      runde for å fjerne enda flere klikk).
    </p>
  );
}

'use client';

import Script from 'next/script';
import { useEffect } from 'react';

interface GoogleAnalyticsProps {
  measurementId?: string;
}

export function GoogleAnalytics({ measurementId }: GoogleAnalyticsProps) {
  // Only load if measurement ID is provided
  if (!measurementId) {
    return null;
  }

  return (
    <>
      <Script
        strategy="afterInteractive"
        src={`https://www.googletagmanager.com/gtag/js?id=${measurementId}`}
      />
      <Script
        id="google-analytics"
        strategy="afterInteractive"
        dangerouslySetInnerHTML={{
          __html: `
            window.dataLayer = window.dataLayer || [];
            function gtag(){dataLayer.push(arguments);}
            gtag('js', new Date());
            gtag('config', '${measurementId}', {
              page_path: window.location.pathname,
            });
          `,
        }}
      />
    </>
  );
}

/**
 * Generic analytics hook for tracking events
 * Can be extended to support other analytics providers
 */
export function useAnalytics() {
  const trackEvent = (eventName: string, params?: Record<string, any>) => {
    if (typeof window !== 'undefined' && (window as any).gtag) {
      (window as any).gtag('event', eventName, params);
    }
  };

  const trackPageView = (url: string) => {
    if (typeof window !== 'undefined' && (window as any).gtag) {
      (window as any).gtag('config', process.env.NEXT_PUBLIC_GA_MEASUREMENT_ID, {
        page_path: url,
      });
    }
  };

  return { trackEvent, trackPageView };
}

