/**
 * Shared utility for calling the admin AI API
 * Used by both GlobalAIAssistant and per-product AI helpers
 */

export type AIType = "productDescription" | "seo" | "heroCopy" | "categoryCopy" | "emailTemplate";

export interface AIRequestPayload {
  // ProductDescription
  name?: string;
  category?: string;
  price?: number;
  tone?: "nøytral" | "entusiastisk" | "teknisk";
  notes?: string;
  // SEO
  shortDescription?: string;
  pageType?: "product" | "category" | "frontpage" | "other";
  // CategoryCopy
  categoryName?: string;
  productsHint?: string;
  // HeroCopy
  campaignName?: string;
  focus?: string;
  discountInfo?: string;
  // EmailTemplate
  templateType?: "welcome" | "campaign" | "newsletter";
  audienceDescription?: string;
  offerDescription?: string;
  // Legacy fields (for backward compatibility)
  toneOfVoice?: "nøytral" | "entusiastisk" | "teknisk";
  useCase?: string;
  description?: string;
  productTypes?: string;
  discount?: number;
}

export interface AIResponse {
  ok: boolean;
  result?: any;
  error?: string;
}

/**
 * Call the admin AI API
 */
export async function callAdminAI(
  type: AIType,
  payload: AIRequestPayload
): Promise<AIResponse> {
  try {
    const response = await fetch("/api/admin/ai", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ type, payload }),
    });

    const data = await response.json();

    if (!response.ok || !data.ok) {
      return {
        ok: false,
        error: data.error || "Kunne ikke generere innhold",
      };
    }

    return {
      ok: true,
      result: data.result,
    };
  } catch (error) {
    return {
      ok: false,
      error: error instanceof Error ? error.message : "Ukjent feil",
    };
  }
}

import { NextResponse } from "next/server";
import { getAuthSession } from "@/lib/auth";

/** Require INTERNAL_CRON_TOKEN via x-internal-token header. */
export function requireInternalToken(req: Request): NextResponse | null {
  const secret = req.headers.get("x-internal-token");
  const expected = process.env.INTERNAL_CRON_TOKEN;
  if (!expected || !secret || secret !== expected) {
    return NextResponse.json({ ok: false, error: "Unauthorized" }, { status: 401 });
  }
  return null;
}

/** Debug endpoints: 404 in production; require internal token otherwise. */
export function requireDebugAccess(req: Request): NextResponse | null {
  if (process.env.NODE_ENV === "production") {
    return NextResponse.json({ ok: false, error: "Not found" }, { status: 404 });
  }
  if (process.env.DEBUG_API_OPEN === "true") {
    return null;
  }
  return requireInternalToken(req);
}

export async function requireAdminSession(): Promise<
  | { ok: true; userId: string }
  | { ok: false; response: NextResponse }
> {
  const session = await getAuthSession();
  if (!session?.user) {
    return {
      ok: false,
      response: NextResponse.json({ ok: false, error: "Unauthorized" }, { status: 401 }),
    };
  }
  const role = (session.user as { role?: string }).role;
  if (role !== "admin") {
    return {
      ok: false,
      response: NextResponse.json({ ok: false, error: "Forbidden" }, { status: 403 }),
    };
  }
  return { ok: true, userId: session.user.id || "admin" };
}

/** Public-safe order payload — strips customer PII and supplier internals. */
export function toPublicOrder(order: Record<string, any>) {
  const shipping =
    order.shippingAddress && typeof order.shippingAddress === "object"
      ? {
          city: (order.shippingAddress as any).city ?? null,
          postalCode: (order.shippingAddress as any).postalCode ?? null,
          country: (order.shippingAddress as any).country ?? "NO",
        }
      : {};

  const items = Array.isArray(order.items)
    ? order.items.map((item: any) => ({
        name: item.name || item.productName || item.product?.name || "Produkt",
        quantity: item.quantity,
        price: item.price,
        variantName: item.variantName ?? null,
      }))
    : [];

  return {
    id: order.id,
    orderNumber: order.orderNumber,
    fulfillmentStatus: order.fulfillmentStatus,
    paymentStatus: order.paymentStatus,
    status: order.status,
    subtotal: order.subtotal,
    shippingCost: order.shippingCost,
    tax: order.tax,
    total: order.total,
    trackingNumber: order.trackingNumber,
    trackingUrl: order.trackingUrl,
    shippingCarrier: order.shippingCarrier,
    createdAt: order.createdAt,
    updatedAt: order.updatedAt,
    items,
    shippingAddress: shipping,
    // Explicitly omit: customerEmail, customer, paymentIntentId details dump, supplier fields
  };
}

import { OrderStatus, SupplierOrderStatus } from "@prisma/client";
import { prisma } from "@/lib/prisma";
import { getSupplierAdapter } from "@/lib/suppliers";
import type { Supplier } from "@/lib/suppliers/types";

interface ProcessOptions {
  isRetry?: boolean;
}

export async function processOrderAutomation(orderId: string, options?: ProcessOptions) {
  const order = await prisma.order.findUnique({
    where: { id: orderId },
    include: {
      orderItems: {
        include: {
          product: true,
        },
      },
      customer: true,
    },
  });

  if (!order) {
    throw new Error(`Order ${orderId} not found`);
  }

  if (!order.orderItems.length) {
    throw new Error("Cannot process order without items");
  }

  // Parse shipping address - can be Json (object) or string
  let shippingAddressData: any = order.shippingAddress;
  if (typeof order.shippingAddress === 'string') {
    try {
      shippingAddressData = JSON.parse(order.shippingAddress);
    } catch {
      throw new Error("Order missing valid shipping address");
    }
  }
  
  const shippingAddress = parseAddressFromObject(shippingAddressData);
  if (!shippingAddress) {
    throw new Error("Order missing shipping address");
  }

  const autoOrderAttempts = (order.autoOrderAttempts ?? 0) + 1;
  const supplierResults: Array<{ supplierOrderId: string; supplier: Supplier }> = [];

  for (const item of order.orderItems) {
    if (!item.product?.supplierName || !item.product.supplierUrl) {
      continue;
    }

    const supplier = item.product.supplierName.toLowerCase() as Supplier;
    const adapter = await getSupplierAdapter(supplier);

    const result = await (adapter as any).placeOrder({
      orderId: order.id,
      productId: item.productId,
      supplierProductId: item.product.supplierProductId,
      quantity: item.quantity,
      customer: {
        name: order.customer?.name ?? shippingAddress.name,
        email: order.customer?.email,
        phone: order.customer?.phone,
      },
      shippingAddress,
    });

    supplierResults.push({ supplierOrderId: result.supplierOrderId, supplier });
  }

  if (!supplierResults.length) {
    throw new Error("No supplier orders were placed");
  }

  const primarySupplier = supplierResults[0];

  const updated = await prisma.order.update({
    where: { id: order.id },
    data: {
      supplierOrderId: primarySupplier.supplierOrderId,
      supplierOrderStatus: SupplierOrderStatus.PENDING,
      autoOrderAttempts,
      status: OrderStatus.processing,
      updatedAt: new Date(),
    },
