          }
        } else {
          const html = $(selector).first().html();
          if (html && html.trim()) {
            return html.trim();
          }
          const text = $(selector).first().text().trim();
          if (text && text.length > 10) {
            return text;
          }
        }
      } catch {
        // Continue
      }
