    });

    it("should handle invalid URLs gracefully", () => {
      const productId = extractAlibabaProductId("not-a-url");
      expect(productId).toBeNull();
    });
  });

  describe("Edge cases", () => {
    it("should handle URLs with only whitespace", () => {
      expect(normalizeUrl("   ")).toBe("");
      expect(isValidTemuUrl("   ")).toBe(false);
      expect(isValidAlibabaUrl("   ")).toBe(false);
    });

    it("should handle URLs without https/http", () => {
      const normalized = normalizeUrl("www.temu.com/goods.html");
      expect(normalized).toMatch(/^https:/);
    });

    it("should handle very long query strings", () => {
      const longParams = Array(100).fill("param=value").join("&");
      const url = `https://www.temu.com/goods.html?goods_id=123&${longParams}&utm_source=google`;
      const normalized = normalizeUrl(url);
      
      expect(normalized).not.toContain("utm_source");
      expect(normalized).toContain("goods_id=123");
    });

    it("should handle invalid domain gracefully", () => {
      const invalidUrl = "https://invalid-domain-that-does-not-exist-12345.com/product.html";
      const normalized = normalizeUrl(invalidUrl);
      
      // Should return normalized URL even if domain is invalid
      expect(normalized).toContain("invalid-domain");
    });

    it("should handle special characters in URL", () => {
      const url = "https://www.temu.com/goods.html?goods_id=123&name=Test%20Product";
      const normalized = normalizeUrl(url);
      
      expect(normalized).toContain("goods_id=123");
    });

    it("should handle URLs with fragments", () => {
      const url = "https://www.temu.com/goods.html?goods_id=123#section";
      const normalized = normalizeUrl(url);
      
      expect(normalized).toContain("goods_id=123");
      // Fragment should be preserved
      expect(normalized).toContain("#section");
    });
  });
});

/**
 * Global minimal logger for consistent error logging across the application.
 * Use this instead of console.error directly for better error tracking.
 */
export function logError(err: any, ctx: string) {
  const message = err?.message || String(err);
  const stack = err?.stack;
  
  console.error("🔥 ERROR:", ctx, message);
  if (stack && process.env.NODE_ENV === "development") {
    console.error("Stack:", stack);
  }
}

/**
 * Log warning messages with context.
 */
export function logWarning(message: string, ctx: string) {
  console.warn("⚠️  WARNING:", ctx, message);
}

/**
 * Log info messages with context (only in development).
 */
export function logInfo(message: string, ctx: string) {
  if (process.env.NODE_ENV === "development") {
    console.log("ℹ️  INFO:", ctx, message);
  }
}

/**
 * Utility functions for consistent product counting
 * 
 * Ensures product counts always match what users can actually see
 */

import { Prisma } from '@prisma/client';
import { prisma } from '@/lib/prisma';
import { safeQuery } from '../safeQuery';
import { shouldUseDevFallback, isDatabaseConfigured } from './database-check';

/**
 * Get count of active products matching filters
 * Uses the same filters as the product listing
 */
export async function getProductCount(
  filters?: {
    category?: string;
    query?: string;
    minPrice?: number;
    maxPrice?: number;
    isActive?: boolean;
    storeId?: string;
  }
): Promise<number> {
  // In dev, if DB is not configured, return 0 silently
  if (shouldUseDevFallback()) {
    return 0;
  }

  const where: Prisma.ProductWhereInput = {
    isActive: filters?.isActive !== undefined ? filters.isActive : true,
    ...(filters?.storeId ? { storeId: filters.storeId } : {}),
    ...(filters?.category ? { category: filters.category } : {}),
    ...(filters?.query
      ? {
          name: {
            contains: filters.query,
          },
        }
      : {}),
  };

  if (filters?.minPrice || filters?.maxPrice) {
    where.price = {};
    if (filters.minPrice) {
      where.price.gte = filters.minPrice;
    }
    if (filters.maxPrice) {
      where.price.lte = filters.maxPrice;
    }
  }

  return await safeQuery(() => prisma.product.count({ where }), 0, 'product-count');
}

/**
 * Get count of products per category
 * Returns a map of category name to product count
 */
export async function getCategoryCounts(storeId?: string): Promise<Record<string, number>> {
  // In dev, if DB is not configured, return empty object silently
  if (shouldUseDevFallback()) {
    return {};
  }

  const products = await safeQuery(
    () =>
      prisma.product.findMany({
        where: {
          isActive: true,
          category: { not: null },
          ...(storeId ? { storeId } : {}),
        },
        select: {
          category: true,
        },
      }),
    [],
    'product-category-counts'
  );

  const counts: Record<string, number> = {};
  
  products.forEach((product) => {
    if (product.category) {
      counts[product.category] = (counts[product.category] || 0) + 1;
    }
  });

  return counts;
}

/**
 * Get all unique categories with their product counts
 */
export async function getCategoriesWithCounts(storeId?: string): Promise<Array<{
  name: string;
  count: number;
}>> {
  const counts = await getCategoryCounts(storeId);
  
  return Object.entries(counts)
    .map(([name, count]) => ({ name, count }))
    .sort((a, b) => b.count - a.count); // Sort by count descending
}

/**
 * Get total count of active products
 */
export async function getTotalProductCount(storeId?: string): Promise<number> {
  return getProductCount({ isActive: true, storeId });
}

/**
 * Suppress source map warnings in development
 * 
 * This is a known issue with Next.js/Turbopack and Prisma source maps,
 * especially on Windows. The warnings don't affect functionality.
 * 
 * This utility filters out these specific console.error messages in development only.
 */

const SOURCE_MAP_ERROR_PATTERNS = [
  /Invalid source map/i,
  /sourceMapURL could not be parsed/i,
  /Failed to parse source map/i,
  /\.next\/dev\/server\/chunks/i,
  /@prisma\/client\/runtime\/library\.js/i,
];

/**
 * Check if an error message is a source map warning
 */
function isSourceMapWarning(message: string): boolean {
  return SOURCE_MAP_ERROR_PATTERNS.some(pattern => pattern.test(message));
}

/**
 * Setup source map warning suppression in development
 * This should be called once at app startup
 */
export function setupSourceMapWarningSuppression() {
  // Only in development
  if (process.env.NODE_ENV !== "development") {
    return;
  }

  // Store original console.error
  const originalError = console.error;

  // Override console.error to filter source map warnings
  console.error = (...args: any[]) => {
    // Check if any argument contains source map warning
    const hasSourceMapWarning = args.some((arg) => {
      if (typeof arg === "string") {
        return isSourceMapWarning(arg);
      }
      if (arg instanceof Error) {
        return isSourceMapWarning(arg.message) || isSourceMapWarning(arg.stack || "");
      }
      if (typeof arg === "object" && arg !== null) {
        const stringified = JSON.stringify(arg);
        return isSourceMapWarning(stringified);
      }
      return false;
    });

    // If it's a source map warning, suppress it
    if (hasSourceMapWarning) {
      return; // Don't log
    }

    // Otherwise, log normally
    originalError.apply(console, args);
  };
}

/**
 * URL validation and normalization utilities for Temu and Alibaba
 */

/**
 * Tracking parameters to remove from URLs
 */
const TRACKING_PARAMS = [
  "utm_source",
  "utm_medium",
  "utm_campaign",
  "utm_term",
  "utm_content",
  "ref",
  "referrer",
  "affiliate_id",
  "aff_id",
  "click_id",
  "gclid",
  "fbclid",
  "twclid",
  "li_fat_id",
  "mc_cid",
  "mc_eid",
  "_ga",
  "_gid",
  "spm", // Alibaba-specific
  "scm", // Alibaba-specific
  "trace", // Alibaba-specific
  "tracelog", // Alibaba-specific
] as const;

/**
 * Essential parameters to keep for Temu (product identification)
 */
const TEMU_ESSENTIAL_PARAMS = [
  "goods_id",
  "top_gallery_url",
  "spec_gallery_id",
] as const;

/**
 * Normalize URL by:
 * - Trimming whitespace
 * - Removing tracking query parameters
 * - Preserving essential parameters (for Temu)
 * - Normalizing protocol to https
 * - Normalizing domain (if applicable)
 */
export function normalizeUrl(url: string): string {
  if (!url || typeof url !== "string") {
    return url;
  }

  // Trim whitespace
  const trimmed = url.trim();
  if (!trimmed) {
    return trimmed;
  }

  try {
    // If URL doesn't start with http:// or https://, try to add https://
    let urlToParse = trimmed;
    if (!trimmed.startsWith("http://") && !trimmed.startsWith("https://")) {
      urlToParse = `https://${trimmed}`;
    }

    const urlObj = new URL(urlToParse);

    // Remove tracking parameters
    TRACKING_PARAMS.forEach((param) => {
      urlObj.searchParams.delete(param);
    });

    // Normalize protocol to https
    urlObj.protocol = "https:";

    // Normalize domain for Temu
    if (urlObj.hostname.includes("temu")) {
      urlObj.hostname = "www.temu.com";
    }

    // Normalize domain for Alibaba
    if (urlObj.hostname.includes("alibaba.com")) {
      urlObj.hostname = "www.alibaba.com";
    } else if (urlObj.hostname.includes("1688.com")) {
      urlObj.hostname = "www.1688.com";
    }

    return urlObj.toString();
  } catch (error) {
    // If URL parsing fails, return trimmed original
    console.warn(`[URL Validation] Failed to normalize URL: ${trimmed}`, error);
    return trimmed;
  }
}

/**
 * Check if URL is a valid Temu URL
 * @param url - URL to validate
 * @returns true if hostname includes temu.com
 */
export function isValidTemuUrl(url: string): boolean {
  if (!url || typeof url !== "string") {
    return false;
  }

  try {
    // Handle URLs without protocol
    let urlToParse = url.trim();
    if (!urlToParse.startsWith("http://") && !urlToParse.startsWith("https://")) {
      urlToParse = `https://${urlToParse}`;
    }

    const urlObj = new URL(urlToParse);
    const hostname = urlObj.hostname.toLowerCase();
    
    return hostname.includes("temu.com") || hostname.includes("temu.");
  } catch {
    // If URL parsing fails, do simple string check
    const normalized = url.toLowerCase();
    return normalized.includes("temu.com") || normalized.includes("temu.");
  }
}

/**
 * Check if URL is a valid Alibaba URL
 * @param url - URL to validate
 * @returns true if hostname includes alibaba.com (best effort: prefers /product-detail/ in path)
 */
export function isValidAlibabaUrl(url: string): boolean {
  if (!url || typeof url !== "string") {
    return false;
  }

  try {
    // Handle URLs without protocol
    let urlToParse = url.trim();
    if (!urlToParse.startsWith("http://") && !urlToParse.startsWith("https://")) {
      urlToParse = `https://${urlToParse}`;
    }

    const urlObj = new URL(urlToParse);
    const hostname = urlObj.hostname.toLowerCase();
    
    // Check hostname (required)
    return hostname.includes("alibaba.com") || hostname.includes("1688.com");
  } catch {
    // If URL parsing fails, do simple string check
    const normalized = url.toLowerCase();
    return normalized.includes("alibaba.com") || normalized.includes("1688.com");
  }
}

/**
 * Check if Alibaba URL looks like a product detail page
 * @param url - URL to check
 * @returns true if path contains /product-detail/
 */
export function isAlibabaProductUrl(url: string): boolean {
  if (!url || typeof url !== "string") {
    return false;
  }

  try {
    let urlToParse = url.trim();
    if (!urlToParse.startsWith("http://") && !urlToParse.startsWith("https://")) {
      urlToParse = `https://${urlToParse}`;
    }

    const urlObj = new URL(urlToParse);
    const pathname = urlObj.pathname.toLowerCase();
    
    return pathname.includes("/product-detail/");
  } catch {
    const normalized = url.toLowerCase();
    return normalized.includes("/product-detail/");
  }
}

/**
 * Validate and normalize a URL for a specific provider
 * @param url - URL to validate and normalize
 * @param provider - Provider type ("temu" | "alibaba")
 * @returns Normalized URL if valid, null otherwise
 */
export function validateAndNormalizeUrl(
  url: string,
  provider: "temu" | "alibaba"
): string | null {
  if (!url || typeof url !== "string") {
    return null;
  }

  const trimmed = url.trim();
  if (!trimmed) {
    return null;
  }

  // Validate based on provider
  if (provider === "temu" && !isValidTemuUrl(trimmed)) {
    return null;
  }

  if (provider === "alibaba" && !isValidAlibabaUrl(trimmed)) {
    return null;
  }

  // Normalize
  return normalizeUrl(trimmed);
}

/**
 * Extract essential parameters from Temu URL
 * @param url - Temu URL
 * @returns Object with essential parameters
 */
export function extractTemuParams(url: string): {
  goodsId?: string;
  topGalleryUrl?: string;
  specGalleryId?: string;
} {
  try {
    const normalized = normalizeUrl(url);
    const urlObj = new URL(normalized);
    
    return {
      goodsId: urlObj.searchParams.get("goods_id") || undefined,
      topGalleryUrl: urlObj.searchParams.get("top_gallery_url") || undefined,
      specGalleryId: urlObj.searchParams.get("spec_gallery_id") || undefined,
    };
  } catch {
    return {};
  }
}

/**
 * Extract product ID from Alibaba URL
 * @param url - Alibaba URL
 * @returns Product ID if found, null otherwise
 */
export function extractAlibabaProductId(url: string): string | null {
  try {
    const normalized = normalizeUrl(url);
    const urlObj = new URL(normalized);
    const pathname = urlObj.pathname;
    
    // Extract from /product-detail/123456789.html pattern
    const match = pathname.match(/\/product-detail\/(\d+)/);
    if (match && match[1]) {
      return match[1];
    }
    
    return null;
  } catch {
    return null;
  }
}

/**
 * Color validation and normalization for product variants.
 *
 * All supplier colors are allowed. Validation normalizes known color
 * names to consistent Norwegian naming and keeps the `color`/`farge`
 * attribute pair in sync.
 *
 * NOTE: The legacy "only BLACK/SVART variants" policy has been removed –
 * variants are imported exactly as the supplier provides them.
 */

/** Known color names mapped to consistent Norwegian naming. */
const COLOR_NORMALIZATION: Record<string, string> = {
  black: 'Svart',
  svart: 'Svart',
  sort: 'Svart',
  white: 'Hvit',
  hvit: 'Hvit',
  red: 'Rød',
  rød: 'Rød',
  blue: 'Blå',
  blå: 'Blå',
  green: 'Grønn',
  grønn: 'Grønn',
  yellow: 'Gul',
  gul: 'Gul',
  pink: 'Rosa',
  rosa: 'Rosa',
  purple: 'Lilla',
  lilla: 'Lilla',
  orange: 'Oransje',
  oransje: 'Oransje',
  brown: 'Brun',
  brun: 'Brun',
  grey: 'Grå',
  gray: 'Grå',
  grå: 'Grå',
  silver: 'Sølv',
  sølv: 'Sølv',
  gold: 'Gull',
  gull: 'Gull',
};

/**
 * Validate and normalize a color name.
 *
 * All colors are accepted. Known color names are normalized to
 * consistent Norwegian naming ("black" -> "Svart"); unknown colors
 * are kept as provided by the supplier.
 *
 * @param color - The color to normalize
 * @returns Normalized color name, or null if no color specified
 */
export function validateAndNormalizeColor(color: string | null | undefined): string | null {
  if (!color) {
    return null; // No color specified is OK
  }

  const trimmed = color.trim();
  if (!trimmed) {
    return null;
  }

  const known = COLOR_NORMALIZATION[trimmed.toLowerCase()];
  if (known) {
    return known;
  }

  // Unknown color – keep the supplier's value as-is
  return trimmed;
}

/**
 * Validate variant attributes: normalize color naming and keep the
 * color/farge attribute pair in sync. All colors are allowed.
 */
export function validateVariantAttributes(attributes: Record<string, any>): Record<string, any> {
  const validated = { ...attributes };

  // Check color field
  if (validated.color !== undefined) {
    const normalizedColor = validateAndNormalizeColor(validated.color);
    if (normalizedColor) {
      validated.color = normalizedColor;
      validated.farge = normalizedColor; // Also set Norwegian version
    } else {
      delete validated.color;
      delete validated.farge;
    }
  } else if (validated.farge !== undefined) {
    // Check farge field (Norwegian) when color is not set
    const normalizedColor = validateAndNormalizeColor(validated.farge);
    if (normalizedColor) {
      validated.farge = normalizedColor;
      validated.color = normalizedColor; // Also set English version
    } else {
      delete validated.farge;
      delete validated.color;
    }
  }

  return validated;
}

/**
 * Script to automatically match images to product variants based on color names
 * This script analyzes product images and matches them to variants based on:
 * - Color keywords in image URLs
 * - Color keywords in variant names
 * - Image order/distribution
 */

import { prisma } from '../lib/prisma';

interface ColorMapping {
  keywords: string[];
  variants: string[];
}

const COLOR_MAPPINGS: Record<string, ColorMapping> = {
  'Svart': {
    keywords: ['black', 'svart', 'dark', '1', '01', 'b'],
    variants: ['Svart', 'Black', 'Sort'],
  },
  'Hvit': {
    keywords: ['white', 'hvit', 'light', '2', '02', 'w'],
    variants: ['Hvit', 'White', 'Hvit'],
  },
  'Grå': {
    keywords: ['gray', 'grey', 'grå', '3', '03', 'g'],
    variants: ['Grå', 'Grey', 'Gray', 'Grå'],
  },
  'Rød': {
    keywords: ['red', 'rød', '4', '04', 'r'],
    variants: ['Rød', 'Red'],
  },
  'Blå': {
    keywords: ['blue', 'blå', '5', '05'],
    variants: ['Blå', 'Blue'],
  },
  'Grønn': {
    keywords: ['green', 'grønn', '6', '06'],
    variants: ['Grønn', 'Green'],
  },
  'Gul': {
    keywords: ['yellow', 'gul', '7', '07'],
    variants: ['Gul', 'Yellow'],
  },
  'Rosa': {
    keywords: ['pink', 'rosa', '8', '08'],
    variants: ['Rosa', 'Pink'],
  },
  'Lilla': {
    keywords: ['purple', 'lilla', '9', '09'],
    variants: ['Lilla', 'Purple'],
  },
  'Sølv': {
    keywords: ['silver', 'sølv', '10'],
    variants: ['Sølv', 'Silver'],
  },
  'Rosa Gull': {
    keywords: ['rosegold', 'rose-gold', 'rosa-gull', 'rose', 'gold'],
    variants: ['Rosa Gull', 'Rose Gold', 'RoseGold'],
  },
};

/**
 * Find the best matching image for a variant based on color
 */
function findMatchingImage(
  variantName: string,
  images: string[],
  variantIndex: number,
  totalVariants: number
): string | null {
  if (images.length === 0) return null;
  
  // Normalize variant name
  const variantLower = variantName.toLowerCase();
  
  // Find color mapping for this variant
  let colorMapping: ColorMapping | null = null;
  for (const [color, mapping] of Object.entries(COLOR_MAPPINGS)) {
    if (mapping.variants.some(v => v.toLowerCase() === variantLower)) {
      colorMapping = mapping;
      break;
    }
  }
  
  // Strategy 1: Try to find image with color keyword in URL
  if (colorMapping) {
    for (const keyword of colorMapping.keywords) {
      const matchingImage = images.find(img => 
        img.toLowerCase().includes(keyword.toLowerCase())
      );
      if (matchingImage) {
        return matchingImage;
      }
    }
  }
  
  // Strategy 2: Check if variant name appears in image URL
  const variantKeywords = variantName.toLowerCase().split(/\s+/);
  for (const keyword of variantKeywords) {
    if (keyword.length > 2) { // Skip short words
      const matchingImage = images.find(img => 
        img.toLowerCase().includes(keyword)
      );
      if (matchingImage) {
        return matchingImage;
      }
    }
  }
  
  // Strategy 3: Distribute images evenly across variants
  // If we have multiple images, assign them based on index
  if (images.length >= totalVariants) {
    return images[variantIndex];
  } else if (images.length > 1) {
    // Cycle through available images
    return images[variantIndex % images.length];
  }
  
  // Strategy 4: Use first image as fallback
  return images[0];
}

/**
 * Update variant images for a single product
 */
async function updateProductVariants(productId: string) {
  try {
    const product = await prisma.product.findUnique({
      where: { id: productId },
      include: {
        variants: true,
      },
    });

    if (!product) {
      console.log(`❌ Product ${productId} not found`);
      return { updated: false, reason: 'not_found' };
    }

    // Parse images
    let images: string[] = [];
    try {
      if (product.images) {
        images = typeof product.images === 'string' 
          ? JSON.parse(product.images) 
          : product.images;
      }
    } catch (e) {
      console.log(`⚠️ Could not parse images for product ${productId}`);
      return { updated: false, reason: 'parse_error' };
    }

    if (images.length === 0) {
      console.log(`⚠️ No images for product ${productId}`);
      return { updated: false, reason: 'no_images' };
    }

    if (product.variants.length === 0) {
      console.log(`⚠️ No variants for product ${productId}`);
      return { updated: false, reason: 'no_variants' };
    }

    // Update each variant with matching image
    let updatedCount = 0;
    for (let i = 0; i < product.variants.length; i++) {
      const variant = product.variants[i];
      const matchingImage = findMatchingImage(
        variant.name,
        images,
        i,
        product.variants.length
      );

      if (matchingImage && variant.image !== matchingImage) {
        await prisma.productVariant.update({
          where: { id: variant.id },
          data: { image: matchingImage },
        });
        updatedCount++;
        console.log(`  ✅ Updated variant "${variant.name}" with image`);
      } else if (matchingImage) {
        console.log(`  ✓ Variant "${variant.name}" already has correct image`);
      } else {
        console.log(`  ⚠️ No matching image for variant "${variant.name}"`);
      }
    }

    return { 
      updated: updatedCount > 0, 
      updatedCount,
      totalVariants: product.variants.length 
    };
  } catch (error) {
    console.error(`❌ Error updating product ${productId}:`, error);
    return { updated: false, reason: 'error', error };
