/**
 * ElectroHypeX Lead Product Buyer — review queue builder.
 *
 * Scrapes candidates, runs pricing + AI/fallback enrichment + score + buyer policy.
 * NEVER saves products to the database.
 *
 * Usage: npx tsx scripts/build-buyer-review-queue.ts
 * Optional: LIMIT=20 npx tsx scripts/build-buyer-review-queue.ts
 */
import "./stub-server-only";
import "dotenv/config";
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "fs";
import { join } from "path";
import { TemuScraper } from "../lib/scrapers/temu-scraper";
import {
  calculateCompareAtPrice,
  calculateSuggestedRetailPrice,
  convertPriceToNOK,
} from "../lib/import/pricing";
import { prepareImages, upgradeImageUrl } from "../lib/import/image-quality";
import { extractSpecs } from "../lib/import/spec-extractor";
import { detectSubcategory } from "../lib/import/subcategories";
import {
  enrichmentToDescription,
  enrichmentToShortDescription,
  enrichProductWithAI,
} from "../lib/import/ai-enrichment";
import { calculateProductScore } from "../lib/import/product-score";
import { detectProductWarnings } from "../lib/import/product-warnings";
import { evaluateBuyerFit, type BuyerDecision } from "../lib/import/buyer-policy";
import { IMPORT_DELIVERY_TIME } from "../lib/import/types";
import type { ProductVariant } from "../lib/scrapers/types";

interface Candidate {
  goodsId: string;
  url: string;
  whySelected: string;
  searchTheme: string;
  alreadyInStore?: boolean;
  storeProductName?: string;
}

export interface ReviewQueueItem {
  goodsId: string;
  url: string;
  supplier: string;
  name: string;
  originalTitle: string;
  category: string;
  subcategory: string | null;
  costNOK: number;
  sellingPrice: number;
  compareAtPrice: number;
  marginPct: number;
  markupPct: number;
  score: number;
  decision: BuyerDecision;
  whySelected: string;
  searchTheme: string;
  warnings: string[];
  slug: string;
  metaTitle: string;
  metaDescription: string;
  tags: string[];
  imagesCount: number;
  variantsCount: number;
  aiGenerated: boolean;
  alreadyInStore?: boolean;
}

function mapVariants(variants: ProductVariant[] | undefined, baseCostNOK: number, images: string[]) {
  if (!variants || variants.length === 0) {
    const retailPrice = calculateSuggestedRetailPrice(baseCostNOK);
    return [
      {
        name: "Standard",
        price: retailPrice,
        compareAtPrice: calculateCompareAtPrice(retailPrice),
        supplierPrice: Math.round(baseCostNOK),
        image: images[0] || null,
        attributes: {},
        stock: null as number | null,
        sku: null as string | null,
      },
    ];
  }

  return variants.map((variant) => {
    const rawVariantPrice = variant.supplierPrice ?? variant.price;
    const variantCostNOK =
      rawVariantPrice < 100 && baseCostNOK > rawVariantPrice * 5
        ? convertPriceToNOK(rawVariantPrice, "USD")
        : rawVariantPrice;
    const retailPrice = calculateSuggestedRetailPrice(variantCostNOK);
    return {
      name: variant.name || "Standard",
      price: retailPrice,
      compareAtPrice: calculateCompareAtPrice(retailPrice),
      supplierPrice: Math.round(variantCostNOK),
      image: variant.image ? upgradeImageUrl(variant.image) : images[0] || null,
      attributes: variant.attributes || {},
      stock: typeof variant.stock === "number" ? variant.stock : null,
      sku: variant.sku || null,
    };
  });
}

async function processCandidate(
  candidate: Candidate,
  scraper: TemuScraper
): Promise<ReviewQueueItem | { rejected: true; reason: string; goodsId: string; url: string }> {
  const scrape = await scraper.scrapeProduct(candidate.url);
  if (!scrape.success || !scrape.data) {
    return {
      rejected: true,
      reason: scrape.error || "Scrape failed",
      goodsId: candidate.goodsId,
      url: candidate.url,
    };
  }

  const data = scrape.data;
  const costNOK = convertPriceToNOK(data.price.amount, data.price.currency);
  const suggestedPrice = calculateSuggestedRetailPrice(costNOK);
  const compareAtPrice = calculateCompareAtPrice(suggestedPrice);
  const images = prepareImages(Array.isArray(data.images) ? data.images : []);
  const specs = extractSpecs(data.title, data.description || "", data.specs || {});
  const variants = mapVariants(data.variants, costNOK, images);
  const deliveryTime = data.shippingEstimate?.trim() || IMPORT_DELIVERY_TIME;

  const { enrichment, aiGenerated } = await enrichProductWithAI({
    context: {
      url: candidate.url,
      supplier: data.supplier,
      originalTitle: data.title,
      originalDescription: data.description || "",
      costNOK,
      images,
      specs,
      variants,
    },
    suggestedRetailPrice: suggestedPrice,
  });

  const mergedSpecs = { ...specs, ...enrichment.specifications };
  const subcategory =
    enrichment.subcategory ??
    detectSubcategory(enrichment.category, `${data.title} ${data.description || ""}`);
  const description = enrichmentToDescription(enrichment, deliveryTime);

  const score = calculateProductScore({
    costNOK,
    suggestedPrice,
    category: enrichment.category,
    subcategory,
    name: enrichment.title,
    originalTitle: data.title,
    description,
    imagesCount: images.length,
    variantsCount: variants.length,
    specsCount: Object.keys(mergedSpecs).length,
    descriptionLength: description.replace(/<[^>]+>/g, "").length,
  });

  const buyer = evaluateBuyerFit({
    name: enrichment.title,
    originalTitle: data.title,
    description,
    category: enrichment.category,
    subcategory,
    costNOK,
    suggestedPrice,
    overallScore: score.overall,
    imagesCount: images.length,
    variantsCount: variants.length,
    specsCount: Object.keys(mergedSpecs).length,
  });

  const warnings = detectProductWarnings({
    name: enrichment.title,
    description,
    originalTitle: data.title,
    costNOK,
    suggestedPrice,
    category: enrichment.category,
    subcategory,
    images,
    variants,
    specs: mergedSpecs,
  });

  if (buyer.rejected) {
    return {
      rejected: true,
      reason: buyer.issues
        .filter((i) => i.severity === "reject")
        .map((i) => i.message)
        .join(" · ") || `REJECTED score ${score.overall}`,
      goodsId: candidate.goodsId,
      url: candidate.url,
    };
  }

  const profit = suggestedPrice - costNOK;
  const marginPct = suggestedPrice > 0 ? (profit / suggestedPrice) * 100 : 0;
  const markupPct = costNOK > 0 ? (profit / costNOK) * 100 : 0;

  return {
    goodsId: candidate.goodsId,
    url: candidate.url,
    supplier: "temu",
    name: enrichment.title,
    originalTitle: data.title,
    category: enrichment.category,
    subcategory,
    costNOK: Math.round(costNOK),
    sellingPrice: suggestedPrice,
    compareAtPrice,
    marginPct: Math.round(marginPct * 10) / 10,
    markupPct: Math.round(markupPct * 10) / 10,
    score: score.overall,
    decision: buyer.decision,
    whySelected: candidate.whySelected,
    searchTheme: candidate.searchTheme,
    warnings: warnings.map((w) => w.message),
    slug: enrichment.slug,
    metaTitle: enrichment.metaTitle,
    metaDescription: enrichment.metaDescription,
    tags: enrichment.tags,
    imagesCount: images.length,
    variantsCount: variants.length,
    aiGenerated,
    alreadyInStore: candidate.alreadyInStore,
  };
}

async function main() {
  if (!existsSync("data")) mkdirSync("data");

  const candidatesPath = join(process.cwd(), "data", "buyer-candidates.json");
  if (!existsSync(candidatesPath)) {
    console.error("Missing data/buyer-candidates.json — run build-buyer-candidates.ts first");
    process.exit(1);
  }

  const payload = JSON.parse(readFileSync(candidatesPath, "utf8")) as {
    candidates: Candidate[];
  };

  const limit = Number(process.env.LIMIT || payload.candidates.length);
  const candidates = payload.candidates.slice(0, limit);
  const scraper = new TemuScraper();

  const queue: ReviewQueueItem[] = [];
  const rejected: Array<{ goodsId: string; url: string; reason: string }> = [];
  const errors: Array<{ goodsId: string; url: string; error: string }> = [];

  console.log(`Processing ${candidates.length} candidates (no DB writes)...\n`);

  for (let i = 0; i < candidates.length; i++) {
    const candidate = candidates[i];
    process.stdout.write(`[${i + 1}/${candidates.length}] ${candidate.goodsId} … `);
    try {
      const result = await processCandidate(candidate, scraper);
      if ("rejected" in result && result.rejected) {
        rejected.push({ goodsId: result.goodsId, url: result.url, reason: result.reason });
        console.log(`REJECTED — ${result.reason.slice(0, 80)}`);
      } else {
        queue.push(result as ReviewQueueItem);
        const item = result as ReviewQueueItem;
        console.log(`${item.decision.toUpperCase()} score=${item.score} «${item.name}»`);
      }
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      errors.push({ goodsId: candidate.goodsId, url: candidate.url, error: message });
      console.log(`ERROR — ${message.slice(0, 80)}`);
    }

    // polite delay to reduce Temu rate-limiting
    await new Promise((r) => setTimeout(r, 1500));
  }

  // Group by category
  const byCategory: Record<string, ReviewQueueItem[]> = {};
  for (const item of queue) {
    const key = item.category || "Ukategorisert";
    if (!byCategory[key]) byCategory[key] = [];
    byCategory[key].push(item);
  }
  for (const key of Object.keys(byCategory)) {
    byCategory[key].sort((a, b) => b.score - a.score);
  }

  const output = {
    generatedAt: new Date().toISOString(),
    savedToDatabase: false,
    summary: {
      processed: candidates.length,
      queued: queue.length,
      approved: queue.filter((q) => q.decision === "approved").length,
      review: queue.filter((q) => q.decision === "review").length,
      rejected: rejected.length,
      errors: errors.length,
    },
    byCategory,
    queue,
    rejected,
    errors,
  };

  const outPath = join(process.cwd(), "data", "buyer-review-queue.json");
  writeFileSync(outPath, JSON.stringify(output, null, 2));
  console.log(`\nReview queue written → ${outPath}`);
  console.log(JSON.stringify(output.summary, null, 2));
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * E2E Resend verification:
 * 1) List domains + status
 * 2) Validate EMAIL_FROM against verified domains
 * 3) Send customer confirmation + admin notification for a real order
 * 4) Confirm DB SENT
 *
 * Usage (PowerShell):
 *   $env:RESEND_API_KEY="re_..."; npx tsx scripts/e2e-resend-test.ts
 * Or put the key in .env first, then:
 *   npx tsx scripts/e2e-resend-test.ts
 */
require("dotenv").config();
const { PrismaClient } = require("@prisma/client");
const { Resend } = require("resend");

const prisma = new PrismaClient();
const TARGET = process.env.E2E_EMAIL_TO || "rob.tol@hotmail.com";

function parseFrom(from: string): { name?: string; email: string; domain: string } {
  const m = from.match(/^(?:(.+?)\s*)?<([^>]+)>$|^([^\s<>]+)$/);
  const email = (m?.[2] || m?.[3] || "").trim().toLowerCase();
  const domain = email.split("@")[1] || "";
  return { name: m?.[1]?.trim(), email, domain };
}

async function main() {
  const key = (process.env.RESEND_API_KEY || "").trim();
  if (!key) {
    console.error("FAIL: RESEND_API_KEY is empty. Add it to .env or set $env:RESEND_API_KEY");
    process.exit(1);
  }

  let from = (process.env.EMAIL_FROM || "").trim();
  if (!from) from = "ElectroHypeX <beth.t@example.com>";

  const resend = new Resend(key);

  console.log("=== 1) Domains ===");
  const domainsResp = await resend.domains.list();
  if (domainsResp.error) {
    console.error("domains.list error:", domainsResp.error);
    process.exit(1);
  }
  const domains = domainsResp.data?.data || domainsResp.data || [];
  for (const d of domains) {
    console.log(`- ${d.name}: status=${d.status} sending=${d.capabilities?.sending}`);
  }

  const verified = (Array.isArray(domains) ? domains : []).filter(
    (d: any) => d.status === "verified" || d.status === "verified_pending"
  );
  // Resend uses status "verified" when ready
  const readyDomains = (Array.isArray(domains) ? domains : [])
    .filter((d: any) => String(d.status).toLowerCase() === "verified")
    .map((d: any) => String(d.name).toLowerCase());

  console.log("verifiedDomains:", readyDomains);

  console.log("=== 2) EMAIL_FROM check ===");
  let parsed = parseFrom(from);
  console.log("configured EMAIL_FROM:", from, "→ domain:", parsed.domain);

  const onboardingOk = parsed.domain === "resend.dev";
  const customOk = readyDomains.includes(parsed.domain);

  if (!onboardingOk && !customOk) {
    const recommended = readyDomains.length
      ? `ElectroHypeX <noreply@${readyDomains[0]}>`
      : "ElectroHypeX <beth.t@example.com>";
    console.warn("EMAIL_FROM domain is NOT verified in Resend.");
    console.warn("Recommended EMAIL_FROM:", recommended);
    from = recommended;
    parsed = parseFrom(from);
    process.env.EMAIL_FROM = from;
    console.log("Using recommended from for this test:", from);
  } else {
    console.log("EMAIL_FROM domain OK for sending");
  }

  // Ensure email module sees env
  process.env.EMAIL_FROM = from;
  if (!(process.env.ADMIN_EMAIL || "").trim()) {
    process.env.ADMIN_EMAIL = TARGET;
    console.log("ADMIN_EMAIL was empty — temporarily set to", TARGET, "for this test");
  }

  console.log("=== 3) Prepare order with customer email", TARGET, "===");
  let order = await prisma.order.findFirst({
    where: { customer: { email: TARGET } },
    include: { customer: true },
    orderBy: { createdAt: "desc" },
  });

  if (!order) {
    order = await prisma.order.findFirst({
      include: { customer: true },
      orderBy: { createdAt: "desc" },
    });
    if (!order?.customer) {
      console.error("No order with customer found");
      process.exit(1);
    }
    await prisma.customer.update({
      where: { id: order.customer.id },
      data: { email: TARGET },
    });
    console.log("Updated customer email on order", order.orderNumber, "→", TARGET);
  }

  // Reset email statuses so we can observe SENT transition
  await prisma.order.update({
    where: { id: order.id },
    data: {
      customerEmailStatus: "NOT_SENT",
      customerEmailLastError: null,
      customerEmailSentAt: null,
      adminEmailStatus: "NOT_SENT",
      adminEmailSentAt: null,
    },
  });

  console.log("=== 4) Send customer confirmation + admin notification ===");
  const { sendOrderConfirmation, sendAdminNotification, getEmailEnvStatus } = await import(
    "../lib/email.ts"
  );
  console.log("envStatus:", getEmailEnvStatus());

  const customerResult = await sendOrderConfirmation(order.id);
  console.log("customerResult:", customerResult);

  const adminResult = await sendAdminNotification(order.id);
  console.log("adminResult:", adminResult);

  const after = await prisma.order.findUnique({
    where: { id: order.id },
    select: {
      orderNumber: true,
      customerEmailStatus: true,
      customerEmailSentAt: true,
      customerEmailLastError: true,
      adminEmailStatus: true,
      adminEmailSentAt: true,
      customer: { select: { email: true } },
    },
  });
  console.log("=== 5) DB after ===");
  console.log(after);

  // Also try a raw Resend send for delivery proof id
  const probe = await resend.emails.send({
    from,
    to: TARGET,
    subject: `ElectroHypeX E2E probe ${new Date().toISOString()}`,
    text: `Probe email from ElectroHypeX E2E test. Order ${order.orderNumber}. From=${from}`,
  });
  console.log("=== 6) Raw Resend probe ===");
  console.log(probe);

  const ok =
    customerResult.success &&
    adminResult.success &&
    after?.customerEmailStatus === "SENT" &&
    after?.adminEmailStatus === "SENT" &&
    !probe.error;

  if (!ok) {
    console.error("E2E FAILED");
    process.exit(1);
  }

  console.log("E2E OK — Resend accepted sends; DB statuses SENT. Check inbox:", TARGET);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

/**
 * Fix .env Stripe Keys Script
 * 
